WITH payload AS (SELECT $archive_payload$[{"id":"bba561fa-a6b2-5919-bb8f-dd93b677f068","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات-ترويج احلبوب احملظورة -الشروع يف ترويج احلبوب احملظورة -حيازة املسكر بقصد الشرب -شرب املسكر -إقامة حد املسكر -التعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة الهاتف اجلوال وإسقاط شريحة اجلوال.","document_number":"34232452","case_number":"3496448","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/06","year":"1434","subject":"مخدرات-ترويج احلبوب احملظورة -الشروع يف ترويج احلبوب احملظورة -حيازة املسكر بقصد الشرب -شرب املسكر -إقامة حد املسكر -التعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة الهاتف اجلوال وإسقاط شريحة اجلوال.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34232452:‬تاريخه ‪1434/06/06:‬هـ‬\n                          ‫رقم الدعوى ‪3496448:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34344739‬تاريخه‪1434/10/29 :‬هـ‬\n\n\n      ‫مخدرات‪-‬ترويــج احلبــوب احملظــورة ‪ -‬الشــروع يف ترويــج احلبــوب‬\n      ‫احملظــورة ‪ -‬حيــازة املســكر بقصــد الشــرب ‪ -‬شــرب املســكر ‪ -‬إقامــة‬\n      ‫حــد املســكر‪ -‬التعزيــر بالســجن واجللــد والغرامــة واملنــع مــن الســفر‬\n                    ‫ومصــادرة الهاتــف اجلــوال وإســقاط شــريحة اجلــوال‪.‬‬\n\n\n\n\n                                                     ‫‪ -1‬قاعدة ‪ :‬املرء مؤاخذ بإقراره‪.‬‬\n                                                            ‫‪ -2‬قاعدة ‪ :‬ال عذر ملن أقر‪.‬‬\n      ‫‪ -3‬قــول اهلل تعالــى ‪( :‬يــا أيهــا الذيــن آمنــو إمنــا اخلمــر وامليســر واألنصــاب‬\n              ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون)‪.‬‬\n      ‫‪ -4‬قولــه صلــى اهلل عليــه وســلم ‪ (:‬كل مســكر خمــر وكل خمــر‬\n                                                                      ‫حــرام)‪ .‬رواه مســلم‪.‬‬\n      ‫‪ -5‬ملــا تشــاور الصحابــة يف عهــد عمــر رضــي اهلل عنــه حــن اكثــر‬\n      ‫النــاس مــن الشــرب ‪ ،‬قــال عبدالرحمــن بــن عــوف رضــي اهلل عنــه ‪ :‬أخف‬\n      ‫احلــدود ثمانــون فوافــق علــى ذلــك الصحابــة ‪ .‬الشــرح املمتــع (‪.)293/14‬‬\n      ‫‪ -6‬قــرار هيئــة كبــار العلمــاء رقــم (‪ )53‬وتاريــخ ‪1397/4/4‬ه ـ والــذي‬\n      ‫تضمــن ‪ :‬أن عقوبــة شــارب اخلمــر احلــد ال التعزيــر باإلجمــاع وأنــه ثمانــون‬\n                                                                                      ‫جلــدة‪.‬‬\n      ‫‪ -7‬يســوغ اجلمــع بــن احلــد والتعزيــر اذا وجــد جنايتــن ملــا روى أحمــد‬\n      ‫بإســناده أن عليــا أتــي بالنجاشــي قــد شــرب اخلمــر يف رمضــان فجلــده‬\n‫‪493‬‬\n\f‫ثمانــن احلــد وعشــرين ســوط ًا لفطــره يف رمضــان‪ .‬وأخرجــه ‪ :‬أيض ـ ًا‬\n    ‫عبدالــرزاق وابــن أبــي شــيبة والبيهقــي (كشــاف القنــاع‪.)112/14‬‬\n‫‪ -8‬الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخدرات واملؤثرات‬\n                                                                 ‫العقلية ‪.‬‬\n‫‪ -9‬الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخدرات واملؤثرات‬\n                                                                 ‫العقلية ‪.‬‬\n‫‪ -10‬الفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n                                                   ‫واملؤثــرات العقليــة‪.‬‬\n              ‫‪ -11‬تعميم وزير الداخلية رقم (‪ )9798‬يف ‪1428/2/10‬هـ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بيــع عــدد مــن حبــوب اإلمفيتامني‬\n‫املنبهــة احملظــورة بقصــد االجتــار والشــروع يف بيــع عــدد مــن حبــوب‬\n‫اإلمفيتامــن احملظــورة وحيازتــه للمــواد املســكرة وتعاطيهــا ولــه‬\n‫ســوابق ‪ ،‬حيــث ورد بــاغ ملكافحــة املخــدرات مــن أحــد مصادرهــا عــن‬\n‫قيــام املدعــى عليــه بترويــج احلبــوب احملظــورة ومت متكــن املصــدر مــن‬\n‫االتصــال عليــه مبســمع مــن أحــد أفــراد الفرقــة وطلــب منــه شــراء عــدد‬\n‫مــن احلبــوب احملظــورة فوافــق املدعــى عليــه ومت تفتيــش املصــدر وتزويده‬\n‫باملبلــغ املرقــم وتكليــف أحــد األفــراد مبرافقتــه ومتــت عمليــة االســتالم‬\n‫والتســليم ولــم يتــم القبــض علــى املدعــى عليــه خوف ـ ًا مــن انكشــاف‬\n‫هويــة املصــدر ‪ ،‬ثــم مت متكــن املصــدر مــن االتصــال علــى املدعــى عليــه‬\n‫مــرة أخــرى وحــدد مكانــه ومت القبــض عليــه وبتفتيشــه عثــر معــه علــى‬\n‫زجاجتــي مــاء بداخلهــا مســكر ولــم يعثــر علــى املبلغ املرقــم كما ضبط‬\n\n                                                                                   ‫‪494‬‬\n\f      ‫معــه علــى اجلــوال الــذي مت التنســيق عليــه وطلــب املدعــي العــام إثبــات‬\n      ‫إدانــة املدعــى عليــه مبــا نســب إليــه واحلكــم عليــه بعقوبــة الســجن‬\n      ‫واجللــد والغرامــة والتشــديد عليــه يف العقوبــة لكثــرة ســوابقه ومنعــه‬\n      ‫مــن الســفر ومصــادرة الهاتــف اجلــوال وإســقاط شــريحته وإلزامــه بإعــادة‬\n      ‫املبلــغ احلكومــي وإقامــة حــد املســكر عليــه‪ ،‬كمــا أقــر املدعــى عليــه‬\n      ‫مبــا نســب وأنكــر الشــروع يف بيــع عــدد مــن احلبــوب احملظــورة وتعاطيــه‬\n      ‫للحبــوب احملظــورة ‪ ،‬بنــاء علــى مــا تقــدم فقــد حكمــت احملكمــة علــى‬\n      ‫املدعــى عليــه بإقامــة حــد املســكر وبتعزيــره بالســجن واجللــد والغرامــة‬\n      ‫واملنــع مــن الســفر ومصــادرة الهاتــف اجلــوال وإســقاط شــريحته ‪ ،‬صــرف‬\n      ‫النظــر عــن طلــب املدعــي العــام إعــادة املبلــغ املالــي املرقــم وصــدق‬\n                                              ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬         ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة‬\n      ‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالدمــام برقــم وتاريــخ ‪ 1434/02/27‬ه ـ املقيــدة باحملكمــة‬  ‫ّ‬\n      ‫برقم وتاريخ ‪ 1434/02/27‬هـ ففي يوم األربعاء املوافق ‪1434/05/29‬‬\n      ‫ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 00‬وفيهــا حضــر املدعــي العــام ‪...... /‬‬\n      ‫وادعــى علــى احلاضــر معــه ‪ ....... /‬ســعودي اجلنســية بالبطاقــة رقــم‬\n      ‫‪ ............‬قائــا يف دعــواه بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام‬\n      ‫لفــرع الهيئــة ‪ ...........‬أدعــي علــى املذكــور أعــاه حيــث إنــه باالطــاع‬\n      ‫علــى محضــر االنتقــال و القبــض والتفتيــش املعــد مــن قبــل رجــال‬\n      ‫الضبــط اجلنائــي بشــعبة مكافحــة املخــدرات بالدمــام تبــن انــه يف يــوم‬\n\n‫‪495‬‬\n\f‫األربعــاء املوافــق ‪1434/1/7‬ه ـ ورد بــاغ مــن أحــد املصــادر الســرية عــن‬\n‫شــخص يدعــى‪ ( ....... /‬املدعــى عليــه) يقــوم بترويــج احلبــوب احملظــورة و‬\n‫يتواجــد يف مخطــط ( ‪ ) 8‬بالدمــام ‪ ،‬وبنــاء علــى ذلــك مت متكــن املصــدر‬\n‫مــن االتصــال علــى جوالــه رقــم (‪ )....‬مبســمع مــن أحــد أفــراد الفرقــة‬\n‫القابضــة وطلــب منــه حبوبـ ًا مببلــغ (‪ )200‬مائتــن ريــال فأجابــه بتوفرهــا‬\n‫لديــه و طلــب منــه احلضــور إليــه مبخطــط ( ‪ ) 8‬ومت االنتقــال إلــى املوقــع‬\n‫برفقــة املصــدر بعــد تفتيشــه و تزويــده مببلــغ مرقــم و مت تكليــف أحــد‬\n‫أفــراد الفرقــة مبرافقتــه ومت االتصــال عليــه حيــث حــدد املــكان خلــف‬\n‫(محطــة ‪ ) .....‬علــى طريــق ‪ .........‬و حضــر الشــخص املخبــر عنــه و اســتلم‬\n‫املبلــغ املرقــم مــن املصــدر و ســلمه عــدد ( ‪ ) 6‬ســت حبــات بيضــاء اللــون‬\n‫و ذلــك مبــرأى مــن الفــرد املرافــق للمصــدر و لــم يتــم القبــض عليــه خوفــا‬\n‫مــن انكشــاف هويــة املصــدر ثــم مت متكــن املصــدر مــن االتصــال علــى‬\n‫نفــس املــروج و طلــب منــه عــدد (‪ )25‬خمســة و عشــرون حبــة محظــورة‬\n‫فطلــب منــه املــروج مقابلتــه خلــف (ســوبرماركت ‪ )........‬بحــي ( ‪) 75‬‬\n‫و مت انتقــال الفرقــة للموقــع و بعــد ربــع ســاعة شــوهد املــروج مترجــا‬\n‫علــى قدميــه حيــث توجــه املــروج للمصــدر و قبــل وصولــه لــه مت القبــض‬\n‫عليــه و اتضــح انــه املدعــى عليــه و بتفتيشــه عثــر علــى عــدد (‪ )2‬قارورتــي‬\n‫مــاء صحــة بداخلهــا شــراب مســكر و لــم يعثــر علــى املبلــغ املرقــم و قــد‬\n‫مت ضبــط اجلــوال الــذي مت التنســيق عليــه بحوزتــه ‪ ،‬و أثبــت التقريــر‬\n‫الكيمــاوي الشــرعي رقــم (‪ ).....‬و تاريــخ ‪1434/2/5‬ه ـ ايجابيــة احلبــوب‬\n‫املروجــة ملــادة األمفيتامــن املنبهــة و املدرجــة باجلــدول الثانــي فئة (ب) من‬\n‫نظــام مكافحــة املخــدرات و املؤثــرات العقليــة ‪ ،‬كمــا أثبــت التقريــر‬\n‫املنــوه عنــه احتــواء عينــة الســائل املضبــوط علــى مــادة الكحــول االيثيلــي‬\n\n\n                                                                                     ‫‪496‬‬\n\f                                                                   ‫و بنســبة مســكرة ‪.‬‬\n      ‫وباســتجواب املدعــى عليــه أقــر بقيامــه بتســليم املصــدر عــدد ( ‪ )6‬ســت‬\n      ‫حبــات محظــورة و باتصــال املصــدر عليــه و طلبــه منــه هــذه احلبــوب‬\n      ‫مقابــل مبلــغ (‪ )200‬ريــال و أضــاف انــه لــم يبيعهــا علــى املصــدر و انــه‬\n      ‫لــم يســتلم منــه أي مبلــغ مالــي كمــا أقــر بــان املصــدر اتصــل عليــه و‬\n      ‫طلبــه منــه أن يحضــر لــه عــدد (‪ )25‬حبــة محظــورة و انــه اتفــق معــه‬\n      ‫علــى مقابلتــه و لكــن ليــس بهــدف تســليمه ( ‪ ) 25‬حبــة التــي طلبهــا و‬\n      ‫إمنــا ليقومــا بالتنــزه ســويا بحكــم صداقتــه بــه و أقــر بحيــازة قارورتــي‬\n      ‫الشــراب املســكر بغــرض االســتعمال و انــه يتعاطــى احلبــوب احملظــورة‬\n                                                  ‫و الشــراب املســكر منــذ أســبوع ‪.‬‬\n                              ‫وقد انتهى التحقيق إلى اتهام املدعى عليه باالتي‪:‬‬\n      ‫‪ -1‬بيــع عــدد ( ‪ ) 6‬ســت حبــات مــن حبــوب األمفيتامــن املنبهــة و‬\n                                                        ‫احملظــورة بقصــد االجتــار ‪.‬‬\n                      ‫‪ -2‬الشروع يف بيع ( ‪ ) 25‬خمسة و عشرون حبة محظورة ‪.‬‬\n           ‫‪ -3‬حيازة عدد ( ‪ ) 2‬قارورتي ماء صحة بها مسكر بقصد الشرب‬\n                                ‫‪ -4‬شربه للمسكر و تعاطيه للحبوب احملظورة ‪.‬‬\n                                                       ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n      ‫‪ -1‬اعترافــه مبــا نســب إليــه املرفــق علــى اللفــة رقــم (‪ )13-11‬و ص (‪)21‬‬\n                                                ‫مــن امللــف املرفــق علــى اللفــة رقــم (‪)1‬‬\n                         ‫‪ -2‬محضر القبض املنوه عنه املرفق على اللفة رقم ( ‪) 1‬‬\n      ‫‪ -3‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم‬\n                                                                              ‫(‪)25 - 24‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه و هــو بكامــل أهليتــه املعتبــرة‬\n\n\n‫‪497‬‬\n\f       ‫شــرعا فعــل محــرم و معاقــب عليــه شــرع ًا و نظام ـ ًا أطلــب مــا يلــي ‪:‬‬\n‫أو ًال ‪ :‬اثبــات ادانتــه مبــا أســند إليــه مــن بيــع احلبــوب احملظــورة و شــروعه‬\n‫يف بيعهــا و تعاطيــه لهــا وفق ـ ًا للفقرتــن رقــم (‪ )2‬و (‪ )7‬مــن املــادة رقــم‬\n‫(‪ )3‬مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة و احلكــم عليــه‬\n                                                                            ‫مبــا يلــي ‪:‬‬\n‫‪ -1‬بعقوبــة الســجن و اجللــد و الغرامــة الــواردة يف الفقــرة رقــم (‪)1‬‬\n‫مــن املــادة رقــم (‪ )38‬مــن النظــام اكتفــاء بالعقوبــة األشــد اســتناد ًا‬\n‫للمــادة (‪ )62‬مــن النظــام ‪ ،‬و تشــديد العقوبــة عليــه وفقــا للمــادة‬\n‫(‪/2/38‬ج) مــن النظــام و اســتنادا لتعميــم ســمو وزيــر الداخليــة رقــم‬\n‫( ‪2/8346/4/5/1‬ش ) و تاريــخ ‪1427/2/8‬ه ـ ‪ ،‬و التشــديد عليــه‬\n‫لكثــرة ســوابقه اســتنادا لبرقيــة صاحــب الســمو امللكــي نائــب وزيــر‬\n            ‫الداخليــة رقــم (‪ )93958/5/5/1‬و تاريــخ ‪1429/8/23‬ه ـ ‪.‬‬\n‫‪ -2‬منعــه مــن الســفر إعمــاال ملقتضــى الفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n                                                                 ‫(‪ )56‬مــن النظــام ‪.‬‬\n‫‪ -3‬مصــادرة الهاتــف اجلــوال العائــد للمذكــور مــن نــوع نوكيــا و الــذي‬\n‫يحمــل الرقــم املصنعــي (‪ )......‬ال ســتخدامه يف بيــع احلبــوب احملظــورة و‬\n‫االتفــاق علــى بيعهــا وفقــا للفقــرة رقــم (‪ )1‬من املادة رقــم (‪ )53‬من النظام‬\n‫‪ ،‬و اســقاط شــريحة هاتفــه اجلــوال وعــدم صرفهــا لــه مــرة أخــرى وفقــا‬\n  ‫لتعميــم ســمو وزيــر الداخليــة رقــم (‪ )9798‬و تاريــخ ‪1428/2/10-9‬ه ـ ‪.‬‬\n‫ثانيــا ‪ :‬احلكــم بالزامــه بإعــادة مبلــغ (‪ )200‬مائتــي ريــال بــد ًال عــن املبلغ‬\n‫احلكومــي الــذي لــم يضبــط اســتنادا إلــى تعميــم ســمو وزيــر الداخليــة‬\n                     ‫رقــم (‪ )65980 /4/5/1‬و تاريــخ ‪1428/10/23-22‬ه ـ ‪.‬‬\n‫ثالثــا ‪ :‬اثبــات ادانتــه مبــا أســند إليــه مــن شــرب املســكر و احلكــم عليــه‬\n\n\n                                                                                            ‫‪498‬‬\n\f                                                                       ‫بحــد الســكر ‪.‬‬\n      ‫رابعــا‪ :‬اثبــات ادانتــه مبــا أســند إليــه مــن حيازتــه لقارورتــي مــاء بهــا‬\n      ‫مســكر بقصــد الشــرب و احلكــم عليــه بعقوبــة تعزيريــة تزجــره و تــردع‬\n      ‫غيــره لقــاء ذلــك و لقــاء تعــدد ســوابقه يف شــرب املســكر وفقــا لقــرار‬\n      ‫هيئــة كبــار العلمــاء رقــم (‪ )53‬و تاريــخ ‪1397/4/4‬ه ـ ‪ .‬هــذه دعــواي‬\n      ‫ا مــا ذكــره املدعــي‬     ‫‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫العــام مــن أننــي قمــت ببيــع عــدد (‪ )6‬ســت حبــات مــن حبــوب االمفيتامــن‬\n      ‫املنبهــة و احملظــورة بقصــد االجتــار فصحيــح ومــا ذكــره مــن أننــي‬\n      ‫شــربت املســكر فصحيــح و مــا ذكــره مــن أننــي قمــت بحيــازة عــدد (‪)2‬‬\n      ‫قارورتــي مــاء صحــة بهــا مســكر بقصــد الشــرب فصحيــح ومــا ذكــره‬\n      ‫مــن أننــي قمــت بالشــروع يف بيــع (‪ )25‬خمســة و عشــرون حبــة محظــورة‬\n      ‫و أننــي أتعاطــى احلبــوب احملظــورة فغيــر صحيــح هكــذا أجــاب ‪.‬ثــم‬\n      ‫ا بــأن‬‫جــرى ســؤال املدعــى عليــه عــن رقــم اجلــوال (‪ ).....‬فأجــاب قائ ـ ً‬\n      ‫هــذا الرقــم عائــد ألخــي و هــو املســتخدم يف الترويــج هكــذا أجــاب ‪.‬ثــم‬\n      ‫جــرى ســؤال املدعــى عليــه عــن املبلــغ احلكومــي املرقــم و قــدره مائتــا‬\n      ‫ا لــم أســتلم هــذا املبلــغ هكــذا أجــاب ‪.‬ثــم جرى ســؤال‬ ‫ريــال فأجــاب قائـ ً‬\n      ‫املدعــي العــام هــل لديــك بينــة علــى دعــواك فيمــا يتعلــق بشــروع املدعــى‬\n      ‫عليــه يف بيعــه خمســة وعشــرين حبــة محظــورة وتعاطيــه لهــا وفيمــا يتعلــق‬\n      ‫باســتالم املدعــى عليــه للمبلــغ احلكومــي املرقــم فأجــاب قائــا ليــس‬\n      ‫لــدي بينــة ســوى مــا يف أوراق املعاملــة هكــذا أجــاب وقــد جــرى اطالعــي‬\n      ‫علــى أوراق املعاملــة كمــا جــرى اطالعــي علــى التقريــر الكيمــاوي‬\n      ‫الشــرعي رقــم (‪ 604‬ك ش‪ ) 41/31/‬وتاريــخ ‪ 1434/2/5‬ه ـ املرفــق‬\n      ‫باملعاملة لفة رقم (‪ )25 ،24‬و املتضمن ثبوت إيجابية احلبوب املضبوطة‬\n\n\n‫‪499‬‬\n\f‫ملــادة االمفيتامــن احملظــورة و ثبــوت احتــواء عينــة الســوائل املضبوطــة‬\n‫ملــادة الكحــول اإليثيلــي و بنســبة مســكرة ‪.‬كمــا جــرى اطالعــي علــى‬\n‫ســوابق املدعــى عليــه املرفقــة باملعاملــة املتضمنــة عدد (‪ )1‬تشــفيط‪،‬عدد‬\n‫(‪ )2‬ســرقة ‪ ،‬عــدد (‪ )4‬شــرب مســكرات ‪ ،‬و بعرضهــا علــى املدعــى‬\n‫عليــه صــادق علــى صحتهــا ‪.‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫ونظــرا ملــا قــرره الطرفــان ومــا مت رصــده وضبطــه أعــاه وبعــد االطــاع‬\n‫علــى أوراق املعاملــة ودراســتها ونظــرا ملصادقــة املدعــى عليــه مبــا نســب‬\n‫إليــه مــن بيــع احلبــوب احملظــورة و شــرب املســكر و حيــازة قارورتــي‬\n‫املســكر بقصــد الشــرب و املــرء مؤاخــذ بإقــراره وال عــذر ملــن أقر ونظرا‬\n‫إلنــكار املدعــى عليــه الشــروع يف بيــع خمســة و عشــرين حبــة محظــورة‬\n‫و إنــكاره لتعاطيــه للحبــوب احملظــورة وإلنــكاره اســتالم املبلــغ املالــي‬\n‫املرقــم و األصــل العــدم وال يوجــد بينــة موصلــة علــى ذلــك ونظــرا إلــى أن‬\n‫مــا قــام بــه املدعــى عليــه هــو محــرم شــرعا ومجــرم نظامــا واهلل تعالــى‬\n‫يقــول‪( :‬يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم‬\n‫رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون) ولقولــه صلــى‬\n‫اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل خمــر حــرام )رواه مســلم‬\n‫«وألن الصحابــة ـ رضــي اهلل عنهــم ملــا تشــاوروا يف عهــد عمــر رضــي اهلل‬\n‫عنــه حــن أكثــر النــاس مــن شــربه‪ ،‬قــال عبــد الرحمــن بــن عــوف رضــي‬\n‫اهلل عنــه‪ :‬أخــف احلــدود ثمانــون فوافــق علــى ذلــك الصحابــة» أ‪.‬ه ـ الشــرح‬\n‫املمتــع (‪ )293/14‬واســتنادا لقــرار هيئــة كبــار العلمــاء رقــم ‪ 53‬وتاريــخ‬\n‫‪1397/4/4‬ه ـ والــذي تضمــن بــأن عقوبــة شــارب اخلمــر احلــد ال التعزيــر‬\n‫باإلجمــاع كمــا قــرر أنــه ثمانــون جلــدة ‪.‬أ‪.‬ه ـ وألنــه يســوغ اجلمــع بــن‬\n‫احلــد والتعزيــر إذا وجــد جنايتــن ملــا روى أحمــد بإســناده أن علي ـ ًا أتــي‬\n\n\n                                                                                    ‫‪500‬‬\n\f      ‫بالنجاشــي قــد شــرب خمــر ًا يف رمضــان فجلــده ثمانــن احلــد وعشــرين‬\n      ‫ســوط ًا لفطــره يف رمضــان وأخرجــه أيض ـ ًا عبدالــرزاق وابــن أبــي شــيبة‬\n      ‫والبيهقــي (كشــاف القنــاع ‪ )112/14‬وبنــاء علــى الفقــرة رقــم (‪ )1‬مــن‬\n      ‫املــادة رقــم (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n                                                                     ‫ولــكل مــا ســبق ‪:‬‬\n      ‫(أوالً)‪:‬ثبــت لــدي إدانــة املدعــى عليــه مبــا نســب إليــه مــن بيــع عــدد (‪)6‬‬\n      ‫ســت حبــات مــن حبــوب االمفيتامــن املنبهــة و احملظــورة بقصــد االجتــار‬\n               ‫وبذلك حكمت وحكمت على املدعى عليه لقاء ذلك مبا يلي ‪:‬‬\n      ‫(‪ )1‬حكمــت علــى املدعــى عليــه بســجنه مــدة خمــس ســنوات يحتســب‬\n      ‫منهــا مــا أمضــاه موقوفــا يف هــذه القضيــة وذلــك وفقــا للفقــرة رقــم (‪)1‬‬\n      ‫مــن املــادة رقــم (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n                                              ‫و هــذه العقوبــة شــاملة لتعــدد ســوابقه ‪.‬‬\n                     ‫(‪ )2‬حكمت على املدعى عليه بجلده تعزيرا مائتي جلدة ‪.‬‬\n      ‫علــى دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة والتــي تليهــا‬\n      ‫عشــرة أيــام وذلــك وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬علــى أن يكــون جلــد احلــد قبــل‬\n      ‫أول دفعــة يف جلــد التعزيــر بخمســة عشــر يومــا و هــذه العقوبــة شــاملة‬\n      ‫حليــازة املدعــى عليــه لقارورتــي مــاء صحــة بهــا مســكر بقصــد الشــرب ‪.‬‬\n      ‫(‪ )3‬حكمــت علــى املدعــى عليــه بدفــع غرامــة ماليــة وقدرهــا ثالثــة‬\n      ‫آالف ريــال وذلــك وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن نظــام‬\n                                         ‫مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫(‪)4‬حكمــت علــى املدعــى عليــه مبنعــه مــن الســفر إلــى خــارج اململكــة‬\n      ‫بعــد انتهــاء عقوبــة الســجن ملــدة خمــس ســنوات وفقــا للفقــرة رقــم (‪)1‬‬\n\n\n‫‪501‬‬\n\f‫مــن املــادة رقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n‫(‪ )5‬حكمــت علــى املدعــى عليــه مبصــادرة الهاتــف اجلــوال املســتخدم يف‬\n‫الترويــج واملذكــور يف الئحــة دعــوى املدعــي العــام وذلــك وفقــا للفقــرة‬\n‫رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                            ‫العقليــة و لصاحــب اجلــوال الرجــوع عليــه بالقيمــة ‪.‬‬\n‫(‪ )6‬حكمــت علــى املدعــى عليــه بإســقاط شــريحته املســتخدمة يف‬\n‫الترويــج واملذكــورة يف الئحــة دعــوى املدعــي العــام وعــدم صرفهــا‬\n‫للمتهــم نفســه وذلــك بنــاء علــى تعميــم ســمو وزيــر الداخليــة رقــم ( )‬\n‫وتاريــخ ‪1428/2/10-9‬هــ‪ .‬و لصاحــب الشــريحة الرجــوع عليــه بالقيمــة‬\n‫(‪ )7‬صرفــت النظــر عــن إيقــاع العقوبــة علــى املدعــى عليــه بإعــادة املبلــغ‬\n                          ‫املالــي املرقــم وقــدره مائتــا ريــال و بذلــك حكمــت‬\n‫(ثانيـاً)‪ :‬ثبــت لــدي إدانــة املدعــى عليــه مبا نســب إليه من شــربه املســكر‬\n‫وبذلــك حكمــت وحكمــت علــى املدعــى عليــه لقــاء ذلــك حــدا بجلــده‬\n   ‫ثمانــن جلــدة دفعــة واحــدة يف مــكان عــام إقامــة حلــد املســكر عليــه ‪.‬‬\n‫(ثالث ـاً)‪ :‬ثبــت لــدي إدانــة املدعــى عليــه مبــا نســب إليــه مــن حيازتــه‬\n‫لقارورتــي مــاء صحــة بهــا مســكر بقصــد الشــرب و عقوبتــه علــى ذلــك‬\n‫داخلــة يف عقوبــة جلــد التعزيــر املذكــورة أعــاه يف الفقــرة رقــم (‪. )2‬‬\n‫(رابعـاً)‪ :‬لــم يثبــت لــدي إدانــة املدعــى عليــه مبــا نســب إليــه مــن شــروعه‬\n‫يف بيــع خمســة و عشــرين حبــة محظــورة و لــم يثبــت لــدي إدانــة املدعــى‬\n‫عليــه بتعاطيــه للحبــوب احملظــورة و بذلــك حكمــت وبعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــى عليــه قناعتــه باحلكــم وقــرر املدعــي العــام‬\n‫االعتــراض علــى احلكــم بالئحــة اعتراضيــة فأجبتــه لطلبــه وأفهمــت‬\n‫املدعــي العــام بــأن عليــه مراجعــة احملكمــة يف يــوم األربعــاء املوافــق‬\n\n\n                                                                                       ‫‪502‬‬\n\f      ‫‪14 34 / 06 / 07‬ه ـ الســتالم نســخة مــن احلكــم لتقــدمي الئحتــه‬\n      ‫االعتراضيــة خــال ثالثــن يومــا مــن تاريــخ االســتالم وإال ســقط حقــه‬\n      ‫يف طلــب االســتئناف وختمــت يف الســاعة ‪ 10:30‬وعلــى ذلــك جــرى‬\n      ‫التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/29‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/6/7‬ه ـ افتتحت‬\n      ‫اجللســة يف الســاعة العاشــرة صباحــا وهــذا اليــوم هــو اليــوم احملــدد‬\n      ‫لتســليم املدعــي العــام نســخة مصــورة مــن قــرار احلكــم إال أنــه لــم‬\n      ‫يحضــر وقــد مت االنتهــاء مــن قــرار احلكــم وعليــه فقــد مت إيــداع نســخة‬\n      ‫مصــورة مــن قــرار احلكــم يف املعاملــة يف هــذا اليــوم نفســه ويعــد اإليــداع‬\n      ‫بدايــة مليعــاد الثالثــن يومـ ًا املقــررة لطلــب اســتئناف احلكــم وللمعلوميــة‬\n      ‫فقــد جــرى حتريــره وختمــت يف الســاعة العاشــرة والنصــف وعلــى ذلــك‬\n      ‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                         ‫آلــه وصحبــه وســلم حــرر يف ‪1434/6/7‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n      ‫األحــد يــوم املوافــق ‪14 34/ 07/14‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫العاشــرة صباحــا وفيهــا قــد انتهــت املــدة املنصــوص عليهــا يف املــادة‬\n      ‫الرابعــة والتســعني بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة ولــم يتقــدم‬\n      ‫املدعــي العــام بالئحتــه االعتراضيــة خــال هــذه املــدة لــذا قــررت رفــع‬\n      ‫كامــل املعاملــة حملكمــة االســتئناف وفقــا ملــا نصــت عليــه اخلامســة‬\n      ‫والتســعون بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة وللمعلوميــة فقــد‬\n      ‫جــرى حتريــره وختمــت يف الســاعة العاشــرة والنصــف صباحــا وعلــى‬\n      ‫ذلــك جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n\n\n‫‪503‬‬\n\f                   ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪14 34 /07/14‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده و بعــد ففــي يــوم األربعــاء املوافــق ‪ 1434/11/12‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 10:00‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية بخطــاب رئيــس محكمة االســتئناف رقم‬\n‫وتاريــخ ‪ 1434/11/09‬ه ـ وبرفقهــا القــرار رقــم وتاريخ ‪1434/10/29‬‬\n‫ه ـ الصــادر مــن قضــاة الدائــرة اجلزائيــة األولــى وهــم فضيلــة الشــيخ‪...../‬‬\n‫وفضيلــة الشــيخ ‪ ...... /‬وفضيلــة الشــيخ ‪ ..... /‬واملتضمــن املصادقــة علــى‬\n‫احلكــم و للمعلوميــة فقــد جــرى حتريــره وختمــت يف الســاعة ‪10:15‬‬\n‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                      ‫أجمعــن حــرر يف ‪ 1434/11/12‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                     ‫‪504‬‬\n\f505\n\f                       ‫كشاف املوضوعات‬\n‫الصفحة‬                 ‫موضوع القضية‬                      ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه لتهريبه املخدرات‬\n                                                          ‫تهريب‬\n  ‫‪5‬‬        ‫واحلشيش واحلبوب املخدرة وحليازته للقضيب‬                 ‫‪1‬‬\n                                                         ‫مخدرات‬\n             ‫الصناعي واملطالبة بإبعاده من البالد‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه لتهريب وترويج‬      ‫تهريب‬\n  ‫‪12‬‬                                      