من‬    ‫ترويج‬\n ‫‪452‬‬                                                                ‫‪46‬‬\n                         ‫احلبوب احملظورة‬                  ‫مخدرات‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه لترويجه احلشيش‬       ‫ترويج‬\n ‫‪459‬‬                                                                ‫‪47‬‬\n         ‫املخدر واحلبوب احملظورة وتعاطي احلشيش املخدر‬     ‫مخدرات‬\n\f‫الصفحة‬                 ‫موضوع القضية‬                     ‫التصنيف‬   ‫م‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه لبيعه القات‬      ‫ترويج‬\n ‫‪472‬‬                                                              ‫‪48‬‬\n            ‫بقصد االجتار والهروب من رجال األمن‬          ‫مخدرات‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه لترويجه احلشيش‬     ‫ترويج‬\n ‫‪478‬‬                                                              ‫‪49‬‬\n                           ‫املخدر‬                       ‫مخدرات‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه ببيع قطعة من‬\n                                                         ‫ترويج‬\n ‫‪485‬‬      ‫احلشيش املخدر بقصد االجتار وحيازة عدد من‬                ‫‪50‬‬\n                                                        ‫مخدرات‬\n           ‫حبوب الترامادول احملظورة بقصد التعاطي‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه ببيع حبوب‬\n                                                         ‫ترويج‬\n ‫‪493‬‬      ‫اإلمفيتامني املنبهة احملظورة والشروع يف ذلك‬             ‫‪51‬‬\n                                                        ‫مخدرات‬\n               ‫وحيازة املواد املسكرة وتعاطيها‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":493,"source_page_end":512,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fb6f76f8cc7a5756c08c1922f38311bdcbe472b3a478192c92bbac3b48a2fd3c","normalized_text_hash":"86eb416243e52d5b6365f92329aa9c77f89ffe85ad3d17d3c33cb457562d694c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p493-34232452"},{"id":"ab9e4033-43c9-5f00-a0f3-d13a028b567a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -احليازة بقصد التعاطي والترويج -تداخل العقوبات التعزيرية -التعزير بالسجن واجللد والغرامة واملصادرة وإعادة املبلغ احلكومي.","document_number":"34179143","case_number":"3497908","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/06","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -احليازة بقصد التعاطي والترويج -تداخل العقوبات التعزيرية -التعزير بالسجن واجللد والغرامة واملصادرة وإعادة املبلغ احلكومي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك‪ 34179143:‬تاريخه ‪1434/04/06:‬هـ‬\n                        ‫رقم الدعوى‪3497908 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34214409‬تاريخه‪1435/05/18 :‬هـ‬\n\n\n    ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬احليــازة بقصــد التعاطــي‬\n    ‫والترويــج ‪ -‬تداخــل العقوبــات التعزيريــة ‪ -‬التعزيــر بالســجن واجللــد‬\n                            ‫والغرامــة واملصــادرة وإعــادة املبلــغ احلكومــي‪.‬‬\n\n\n\n\n                                             ‫‪ -1‬قاعدة املرء مؤاخذ بإقراره ‪.‬‬\n    ‫‪ -2‬مــا نــص عليــه أهــل العلــم مــن أن العقوبــات التعزيريــة تتداخــل ‪.‬‬\n                                               ‫(كشــاف القنــاع ‪.)113/14‬‬\n    ‫‪ -3‬املــواد (‪ )3‬و (‪ )38‬و (‪ )53‬و(‪ )56‬و (‪ )62‬مــن نظــام مكافحــة‬\n                                             ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n    ‫ادعــى املدعــى العــام ضــد املدعــى عليهمــا بترويــج عشــرين حبــة مــن‬\n    ‫حبــوب اإلمفيتامــن املنبهــة احملظــورة بقصــد االجتــار‪ ،‬وحيــازة األول‬\n    ‫لعــدد مــن حبــوب اإلمفيتامــن‪ ،‬لقصــد التعاطــي‪ ،‬وحيــازة املدعــي‬\n    ‫عليــه الثانــي لعــدد مــن حبــوب اإلمفيتامــن لقصــد التعاطــي والترويــج‪،‬‬\n    ‫وتعاطــي املدعــي عليهمــا حلبــوب اإلمفيتامــن‪ .‬حيــث وردت معلومــات‬\n    ‫ملكافحــة املخــدرات مــن أحــد املصــادر الســرية عــن قيــام املدعــى عليــه‬\n    ‫األول بالتوســط يف ترويــج احلبــوب احملظــورة ومت متكــن املصــدر مــن‬\n\n‫‪5‬‬\n\f‫االتصــال علــى املدعــى عليــه األول واتفــق معــه علــى شــراء عــدد مــن‬\n‫احلبــوب احملظــورة وكانــت املكاملــة علــى مســمع مــن أفــراد الفرقــة‬\n‫القابضــة وجــرى تفتيــش املصــدر وتزويــده باملبلــغ املرقــم ثــم مت االنتقــال‬\n‫للموقــع احملــدد وبعــد انتهــاء عمليــه واالســتالم والتســليم مت القبــض‬\n‫علــى املدعــى عليــه األول والســيطرة عليــه وبتفتيشــه عثــر يف جيبــه علــى‬\n‫ثــاث حبــات مــن حبــوب اإلمفيتامــن‪ ،‬كمــا عثــر علــى اجلــوال الــذي‬\n‫مت التنســيق عليــه ومبداهمــه الشــقة وجــد فيهــا املدعــى عليــه الثانــي‬\n‫وبتفتيشــه عثــر بجيبــه علــى عــدد مــن حبــوب اإلمفيتامــن‪ ،‬كــم عثــر‬\n‫يف محفظتــه علــى مبلــغ مالــي مــن ضمنــه املبلــغ املرقــم‪ ،‬وطلــب املدعــي‬\n‫العــام إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بعقوبــة الســجن واجللــد‬\n‫والغرامــة والتشــديد عليهمــا كــون املــادة املروجــة حبوبـ ًا منبهــه ولكــون‬\n‫املدعــى عليــه األول عســكري ًا ومنعهمــا مــن الســفر ومصــادرة جــوال‬\n‫املدعــى عليــه األول وســيارته املســتخدمني باجلرميــة ومصــادرة املبلــغ‬\n‫املضبــوط بحــوزه املدعــى عليــه الثانــي بعــد اقتطــاع املبلــغ احلكومــي‬\n‫املرقــم وإثبــات إدانــة املدعــى عليــه األول مبا أســند إليه من مقاومة رجال‬\n‫الضبــط كمــا أقــر املدعــى عليــه األول مبــا نســب إليــه ‪ ،‬وأقــر املدعــى‬\n‫عليــه الثانــي مبــا نســب إليــه وذكــر بــأن باقــي املبلــغ املضبــوط معــه‬\n‫غيــر قيمــة احلبــوب املروجــة املذكــورة يف الدعــوى لــم يكــن ناجتـ ًا عــن‬\n‫ـاء علــى مــا تقــدم ثبــت إدانــة‬\n                                ‫الترويــج و إمنــا هــو قســط إيجــار الشــقة ‪ ،‬وبنـ ً‬\n‫املدعــى عليهمــا وحكمــت احملكمــة علــى املدعــى عليــه األول بتعزيــره‬\n‫بالســجن و املنــع مــن الســفر و اجللــد والغرامــة ومصــادرة الهاتــف اجلــوال‬\n‫و إســقاط شــريحته‪ ،‬وعلــى املدعــى عليــه الثانــي بتعزيــره بالســجن واملنــع‬\n‫مــن الســفر واجللــد والغرامــة وصــرف النظــر عــن طلــب املدعــي العــام‬\n\n\n                                                                                         ‫‪6‬‬\n\f    ‫مصــادرة املبلــغ املضبــوط مــع املدعــى عليــه الثانــي و يكتفــي باقتطــاع‬\n    ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬    ‫املبلــغ احلكومــي املرقــم ‪ُ ،‬‬\n\n\n\n    ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/4/3‬ه ـ لــدي أنــا‬\n    ‫ـاء علــى املعاملــة احملالــة‬\n                               ‫‪ .......‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n    ‫إلينــا مــن رئيــس احملكمــة برقــم (‪ )......‬وتاريــخ ‪1434/2/30‬ه ـ افتتحت‬\n    ‫اجللســة وفيهــا حضــر ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n    ‫(‪ ).........‬و سعودي ‪ .......‬اجلنسية مبوجب السجل املدني رقم (‪)................‬‬\n    ‫وقــدم املدعــي العــام الئحــة اإلدعاء املتضمنة بصفتي مدعي ًا عام ًا بدائرة‬\n    ‫اإلدعــاء العــام لفــرع الهيئــة ‪ .......‬أدعــي علــى املذكوريــن أعــاه حيــث‬\n    ‫إنــه باإلطــاع علــى محضــري البــاغ و االنتقــال و القبــض و التفتيــش‬\n    ‫املعديــن مــن قبــل مكافحــة املخــدرات بالدمــام تبــن أنــه يف يــوم االثنــن‬\n    ‫املوافــق ‪1434/1/19‬ه ـ وردت معلومــات مــن أحــد املصــادر الســرية‬\n    ‫عــن شــخص يدعــى‪ ....... /‬يقــوم بالتوســط يف ترويــج احلبــوب احملظــورة‬\n    ‫فتــم متكينــه مــن االتصــال علــى جــوال املدعــى عليــه األول ( ‪ ) ..‬رقــم‬\n    ‫(‪ ).............‬و رقمــه املصنعــي (‪ )...‬و طلــب منــه حبــوب كبتاجــون مببلــغ‬\n    ‫(‪ )800‬ثمامنائــة ريــال فوافــق املذكــور علــى ذلــك و طلــب مــن املصــدر‬\n    ‫أن ينتظــره عنــد شــركة ‪ ....‬الواقعــة بحــي ‪ ....‬و كانــت املكاملــة علــى‬\n    ‫مســمع مــن أفــراد الفرقــة القابضــة ثــم جــرى تفتيــش املصــدر تفتيشــا‬\n    ‫دقيقــا و تزويــده مببلــغ مرقــم و قــدره (‪ )800‬ثمامنائــة ريــال و بانتقالهــم‬\n    ‫للموقــع املتفــق عليــه متركــز أفــراد الفرقــة القابضــة بعــدة مواقــع وبعــد‬\n    ‫قرابــة الربــع ســاعة حضــرت ســيارة مــن نــوع ‪ ....‬حتمــل اللوحــة رقــم (‪)....‬‬\n\n‫‪7‬‬\n\f‫و ركــب املصــدر برفقتــه و اجتهــا إلــى إحــدى العمائــر و شــوهد () ينــزل‬\n‫مــن ســيارته و يدخــل العمــارة فتــم متابعتــه و معرفــة الشــقة التــي دخلهــا‬\n‫و بعــد خمــس دقائــق خــرج املذكــور و ركــب ســيارته و أعطــى املصــدر‬\n‫اإلشــارة الدالــة علــى إمتــام عمليــة الترويــج و متــت متابعتــه حتــى عــاد إلــى‬\n‫مكانــه األول و أنــزل املصــدر و مت القبــض عليــه () و قــام مبقاومــة‬\n‫أفــراد الفرقــة القابضــة محــاوال الهــرب و ســلم املصــدر أفــراد الفرقــة‬\n‫القابضــة الكميــة املروجــة و هــي عــدد (‪ )20‬عشــرين حبــة أثبــت التقرير‬\n‫الكيمــاوي الشــرعي رقــم (‪ 419‬ك ش) و تاريــخ ‪1434/2/2‬ه ـ إيجابيــة‬\n‫عينتهــا ملــادة االمفيتامــن املنبهــة احملظــورة املــدرج يف اجلــدول (‪ )2‬فئــة‬\n‫(ب) مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة و بتفتيشــه عثــر‬\n‫يف جيبــه األيســر علــى ( ‪ ) 3‬ثــاث حبــات أثبــت التقريــر الكيمــاوي‬\n‫الشــرعي املشــار إليــه ايجابيتهــا ملــادة االمفيتامــن املنبهــة احملظــورة‬\n‫كمــا مت العثــور معــه علــى اجلــوال الــذي مت التنســيق عليــه و مبداهمــة‬\n‫الشــقة وجــد فيهــا املدعــى عليــه الثانــي ( )و بتفتيشــه عثــر بجيبــه األيســر‬\n‫علــى (‪ )21‬واحــد وعشــرين حبــة أثبــت التقريــر الكيمــاوي الشــرعي‬\n‫الســابق إيجابيــة عينتهــا ملــادة االمفيتامــن املنبهــة احملظــورة كمــا عثــر‬\n‫يف جيبــه األميــن علــى محفظــة بداخلهــا مبلــغ مالــي و قــدره ( ‪) 4913‬‬\n‫أربعــة آالف و تســعمائة وثالثــة عشــر ريــال مــن ضمنهــا املبلــغ املرقــم‬\n‫وبســؤاله مــن قبــل أفــراد الفرقــة القابضــة حــال القبــض عليــه اعتــرف‬\n‫بأنــه حضــر إليــه صديقــه () و طلــب منــه حبــوب مببلــغ (‪ )800‬ثمامنائــة‬\n‫ريــال وقــام بتســليمه عــدد (‪ )25‬خمســة و عشــرين حبــة و اســتلم منــه‬\n‫املبلــغ و باســتجواب املدعــى عليــه األول () و بســماع أقوالــه أفــاد أنــه يف‬\n‫يــوم االثنــن املوافــق ‪1434/1/19‬ه ـ مت القبــض عليــه مــن قبــل رجــال‬\n\n\n                                                                                         ‫‪8‬‬\n\f    ‫مكافحــة املخــدرات أثنــاء وقوفــه بجانــب الســيارة و بتفتيشــه عثــر يف‬\n    ‫جيــب ثوبــه األيســر علــى (‪ )3‬ثــاث حبــات مــن احلبــوب املنبهــة و هــي لــه‬\n    ‫بقصــد التعاطــي كمــا أقــر بتعاطــي احلبــوب املنبهــة منــذ خمســة أشــهر‬\n    ‫و أخــر مــرة كانــت قبــل القبــض عليــه بثالثــة أيــام مضيفــا أنــه حصــل‬\n    ‫بينــه و بــن أفــراد الفرقــة القابضــة مشــادة كالميــة ألنــه لــم يظهــر لــه‬\n    ‫هويتهــم و نفــى مــا ســوى ذلــك و باســتجواب املدعــى عليــه الثانــي (‪).....‬‬\n    ‫و ســماع أقوالــه أقــر أنــه يف يــوم االثنــن املوافــق ‪1434/1/19‬ه ـ حضــر‬\n    ‫إلــى شــقته املدعــو‪ ......./‬و طلــب منــه حبوب ـ ًا منبهــة فســلمه عــدد (‪)25‬‬\n    ‫خمســة وعشــرين حبــة مــن احلبــوب املنبهــة و اســتلم مبلــغ و قــدره (‪)800‬‬\n    ‫ثمامنائــة ريــال و مــن ثــم غــادر الشــقة و بعدهــا بربــع ســاعة مت مداهمتــه‬\n    ‫مــن قبــل رجــال مكافحــة املخــدرات و بتفتيشــه عثــر يف جيبــه األيســر‬\n    ‫علــى (‪ )21‬واحــد وعشــرين حبــة مــن احلبــوب املنبهــة و هــي لــه بقصــد‬\n    ‫التعاطــي كمــا أقــر بتعاطــي احلبــوب املنبهــة منــذ خمســة أشــهر و آخــر‬\n    ‫مــرة كانــت قبــل القبــض عليــه بســاعتني و مبواجهتهمــا مــع بعــض‬\n    ‫أصــر كل منهمــا علــى أقوالــه و ســقط علــى األرض و أفــاد بأنــه بســبب‬\n                       ‫الصــداع و قــد انتهــى التحقيــق إلــى اتهامهمــا مبــا يلــي‪:‬‬\n    ‫‪ -1‬بيــع املدعــى عليهمــا عــدد (‪ )20‬عشــرين حبــة مــن حبــوب االمفيتامــن‬\n                                                  ‫املنبهــة احملظــورة بقصــد االجتار‬\n    ‫‪ -2‬حيــازة املدعــى عليــه األول (‪ )3( )....‬ثــاث حبــات مــن حبــوب‬\n                             ‫االمفيتامــن املنبهــة احملظــورة بقصــد التعاطــي‬\n    ‫‪3‬ـ حيــازة املدعــى عليــه الثانــي (‪ ).....‬عــدد (‪ )21‬واحــد وعشــرين حبــة‬\n     ‫مــن حبــوب االمفيتامــن املنبهــة احملظــورة بقصــد التعاطــي و الترويــج‬\n                                ‫‪ -4‬تعاطي املدعى عليهما احلبوب املنبهة احملظورة‬\n\n\n‫‪9‬‬\n\f‫‪ -5‬مقاومــة املدعــى عليــه األول (‪ )......‬رجــال الضبــط أثنــاء القبــض عليــه‬\n                                                  ‫وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪ -1‬إقرارهمــا املنــوه عنــه املرفــق علــى اللفــات رقــم (‪ )25-17‬و ص (‪ 21‬ـ ‪)23‬‬\n                                           ‫مــن امللــف املرفــق علــى اللفــة رقــم (‪)1‬‬\n‫‪ -2‬محاضــر البــاغ و االتصــال و االنتقــال و الضبــط املنــوه عنهــا املدونــة‬\n                ‫علــى الصفحــات رقــم (‪ )14-12 ، 4 ، 2‬مــن ملــف التحقيــق‬\n‫‪ -3‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم‬\n                                                                                  ‫(‪)26‬‬\n‫‪ -4‬العثــور علــى املبلــغ املرقــم مــن ضمــن املبلــغ املضبــوط مــع قرينــة علــى‬\n                                                ‫أنــه نــاجت عــن االجتــار يف املخــدرات‬\n‫‪ -5‬العثــور علــى اجلــوال الــذي مت التنســيق عليــه مــع املدعــى عليــه األول‬\n                                                          ‫قرينــة علــى صحــة االتهــام‬\n‫‪ -6‬محضــر املواجهــة املنــوه عنــه املرفــق علــى اللفــة رقــم ‪ 25‬وحيــث إن‬\n‫مــا أقــدم عليــه املدعــى عليهمــا و همــا بكامــل أهليتهمــا املعتبــرة شــرع ًا‬\n               ‫فعــل محــرم و معاقــب عليــه شــرع ًا و نظامـ ًا أطلــب مــا يلــي ‪:‬‬\n‫أو ًال ‪ :‬إثبــات إدانتهمــا مبــا أســند إليهمــا يف الفقــرة رقــم ( ‪،4 ،3 ،2 ،1‬‬\n‫) مــن وصــف التهمــة وفــق الفقــرة رقــم ( ‪ ) 2‬مــن املــادة رقــم ( ‪ ) 3‬مــن‬\n‫نظــام مكافحــة املخــدرات و املؤثــرات العقليــة و احلكــم عليهمــا مبــا‬\n                                                                                   ‫يلــي‪:‬‬\n‫‪1‬ـ بعقوبــة الســجن و اجللــد و الغرامــة الــواردة يف الفقــرة رقــم (‪ )1‬مــن‬\n‫املــادة رقــم (‪ )38‬مــن النظــام اكتفــاء بالعقوبــة األشــد اســتناد ًا للفقــرة‬\n‫رقــم (‪ )1‬مــن املــادة رقــم (‪ )62‬مــن ذات النظــام و التشــديد عليهمــا كــون‬\n‫املــادة املروجــة حبوبـ ًا منبهــة وفــق الفقــرة (‪/2‬ج) مــن املــادة رقــم (‪ )38‬مــن‬\n\n\n                                                                                            ‫‪10‬‬\n\f     ‫النظــام و اســتنادا لبرقيــة صاحــب الســمو امللكــي وزيــر الداخليــة رقــم‬\n     ‫(‪2/8346/5/1‬ش) و تاريــخ ‪1427/2/8‬ه ـ و لكــون (‪ ).....‬عســكري ًا‬\n     ‫اســتناد ًا إلــى برقيتــي صاحــب الســمو امللكــي وزيــر الداخليــة رقــم‬\n     ‫(‪ )112103/4/5/1‬و تاريخ ‪1429/11/4‬هـ‪ ،‬و رقم (‪)10130/4/5/1‬‬\n     ‫وتاريــخ ‪1429/2/15‬ه ـ ‪2‬ـ منعهمــا مــن الســفر وفــق الفقــرة رقــم (‪ )1‬مــن‬\n                                                           ‫املــادة رقــم (‪ )56‬مــن النظــام‬\n     ‫‪3‬ـ مصــادرة جــوال (‪ ).....‬و ســيارته املســتخدمني يف اجلرميــة و املوصوفــن‬\n     ‫بالوقائــع وفــق الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن النظــام و عــدم‬\n     ‫صــرف شــريحة اجلــوال لــه مــرة أخــرى وفق ـ ًا لتعميــم وزيــر الداخليــة‬\n     ‫رقــم(‪ ).....‬و تاريــخ ‪1428/2/10-9‬ه ـ و مصــادرة املبلــغ املضبــوط بحــوزة‬\n     ‫(‪).....‬املشــار إليــه بالوقائــع ( ‪ 4113‬ريــا ًال ‪ /‬بعــد اقتطــاع املبلــغ احلكومــي‬\n     ‫املرقــم ) لكونــه نــاجت عــن االجتــار يف املخــدرات وفــق الفقــرة رقــم (‪)2‬‬\n     ‫مــن املــادة رقــم (‪ )53‬مــن النظــام ثاني ـ ًا ‪ -‬إثبــات إدانــة (‪ ).....‬مبــا أســند‬\n     ‫إليــه مــن مقاومــة رجــال الضبــط أثنــاء القبــض عليــه و احلكــم عليــه‬\n     ‫بعقوبــة تعزيريــة رادعــة وبــاهلل التوفيــق وبســؤال املدعــى عليهمــا أجــاب‬\n     ‫األول بقولــه مــا ذكــره املدعــي العــام صحيــح واملصــدر زميلــي وعــادة‬\n     ‫مــا نشــتري احلبــوب احملظــورة مــع بعــض وقــد اســتلمت مــن املدعــى‬\n     ‫عليــه األول خمــس وعشــرين حبــة وســلمتها للمصــدر وأعطانــي مقابــل‬\n     ‫عمليــة التنســيق أربــع حبــات أكلــت منهــا حبــة وضبــط بحوزتــي علــى‬\n     ‫ثــاث حبــات وقــد اســتخدمت جوالــي يف عمليــة التنســيق لبيــع احلبــوب‬\n     ‫وقــد حصلــت مشــادة ومالســنة بينــي وبــن فرقــة القبــض وأنــا أعمــل يف‬\n     ‫الشــرطة العســكرية القــوات البريــة هــذه إجابتــي كمــا أجــاب الثانــي‬\n     ‫بقولــه مــا ذكــره املدعــي العــام صحيــح جملــة وتفصيــا ولكــن باقــي‬\n\n\n‫‪11‬‬\n\f‫املبلــغ املضبــوط معــي غيــر قيمــة احلبــوب املروجــة املذكــورة يف الدعــوى‬\n‫العامــة لــم يكــن ناجتــا عــن الترويــج وإمنــا هــو قســط إيجــار الشــقة‬\n‫التــي أســكن فيهــا هــذه إجابتــي وبعــد تدويــن مــا ســبق جــرى االطــاع‬\n‫علــى التقريــر الكيمــاوي الشــرعي رقــم (‪ ).....‬املتضمــن إيجابيــة‬\n‫عينــات جميــع احلبــوب املضبوطــة يف هــذه القضيــة ملــادة اإلمفيتامــن‬\n‫املنبهــة واحملظــورة كمــا جــرى اإلطــاع علــى ســوابق املدعــى عليهمــا‬\n‫املرفقــة بالئحــة االدعــاء العــام واملتضمنــة عــدم وجــود ســوابق مســجلة‬\n‫عليهمــا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة املتضمنــة املصادقــة‬\n‫عليهــا وحيــث إن املــرء مؤاخــذ بإقــراره وبنــاء علــى التقريــر الكيمــاوي‬\n‫الشــرعي املشــار إليــه أعــاه وحيــث إن موجــب تعاطــي احلبــوب احملظــورة‬\n‫التعزيــر وبنــاء علــى مــا نــص عليــه أهــل العلــم مــن أن العقوبــات التعزيريــة‬\n‫تتداخل(كشــاف القنــاع ‪ )113/14‬واســتناد ًا للمــادة الثالثــة واملــادة‬\n‫الثامنــة والثالثــن واملــادة الثالثــة واخلمســن واملــادة السادســة واخلمســن‬\n‫واملــادة الثانيــة والســتني مــن نظــام املخــدرات واملؤثــرات العقليــة وحيــث‬\n‫لــم تقــم بينــة علــى أن املبلــغ املضبــوط مــع املدعــى عليــه ‪-‬غيــر املبلــغ‬\n‫احلكومــي املرقــم‪ -‬نــاجت عــن ترويــج احلبــوب احملظــورة وحيــث إن املدعــى‬\n‫عليــه يعمــل عســكريا ممــا يســتدعي التشــديد يف العقوبــة لــذا فقــد‬\n‫ثبــت لــدي إدانــة املدعــى عليــه األول مبــا يلــي ‪ :‬التوســط يف بيــع خمــس‬\n‫وعشــرين حبــة مــن احلبــوب احملظــورة مبقابــل وتعاطــي احلبــوب احملظــورة‬\n‫واســتخدامه جوالــه املشــار إليــه يف الئحــة االدعــاء يف عمليــة التنســيق‬\n‫لبيــع احلبــوب وحيــازة ثــاث حبــات مــن حبــوب اإلمفيتامــن املنبهــة‬\n‫واحملظــورة بقصــد التعاطــي ومقاومــة رجــال الضبــط أثنــاء القبــض عليــه‬\n‫وحكمــت عليــه لقــاء ذلــك مبــا يلــي‪ :‬أوال‪ :‬ســجنه خمــس ســنوات وســتة‬\n\n\n                                                                                        ‫‪12‬‬\n\f     ‫أشــهر اعتبــارا مــن تاريــخ إيقافــه ومنعــه مــن الســفر خــارج اململكــة مــدة‬\n     ‫خمــس ســنوات وســتة أشــهر تبــدأ بعــد االنتهــاء مــن تنفيــذ عقوبــة الســجن‬\n     ‫احملكــوم بهــا وجلــده مائتــن وخمســن جلــدة مفرقــة علــى خمــس‬\n     ‫دفعــات متســاوية وبــن كل دفعــة واألخــرى مــدة ال تقــل عــن عشــرة‬\n     ‫أيــام وإلزامــه بدفــع غرامــة ماليــة مقدارهــا خمســة آالف ريــال ثانيــا‪/‬‬\n     ‫مصــادرة الهاتــف اجلــوال ذي الرقــم املصنعــي(‪ ).....‬وإســقاط شــريحته‬\n     ‫وعــدم صرفهــا للمدعــى عليــه مــرة أخــرى كمــا ثبــت لــدي إدانــة املدعــى‬\n     ‫عليــه الثانــي ببيــع خمــس وعشــرين حبــة مــن احلبــوب احملظــورة بقصــد‬\n     ‫االجتــار وحيــازة واحــد عشــرين حبــة مــن احلبــوب احملظــورة بقصــد‬\n     ‫التعاطــي واالجتــار وتعاطــي احلبــوب احملظــورة وحكمــت عليــه لقــاء‬\n     ‫ذلــك مبــا يلــي ســجنه خمــس ســنوات وســتة أشــهر اعتبــارا مــن تاريــخ‬\n     ‫إيقافــه ومنعــه مــن الســفر خــارج اململكــة مــدة خمــس ســنوات وســتة‬\n     ‫أشــهر تبــدأ بعــد االنتهــاء مــن تنفيــذ عقوبــة الســجن احملكوم بهــا وجلده‬\n     ‫مائتــن وخمســن جلــدة مفرقــة علــى خمــس دفعــات متســاوية وبــن كل‬\n     ‫دفعــة واألخــرى مــدة ال تقــل عــن عشــرة أيــام وإلزامــه بدفــع غرامــة ماليــة‬\n     ‫مقدارهــا خمســة آالف ريــال كمــا حكمــت بصــرف النظــر عــن طلــب‬\n     ‫املدعــي العــام مصــادرة املبلــغ املضبــوط مــع املدعــى عليــه وقــدره أربعــة‬\n     ‫آالف ومائــة وثالثــة عشــر ريــاال و يكتفــى باقتطــاع املبلــغ احلكومــي‬\n     ‫املرقــم وقــدره ثمامنائــة ريــال وبعــرض احلكــم علــى املدعــى عليهمــا‬\n     ‫قــررا عــدم القناعــة بــه ألن احلكــم شــديد ومــدة الســجن احملكــوم بهــا‬\n     ‫كثيــرة جــدا وطلبــا رفــع احلكــم إلــى محكمــة االســتئناف بــدون الئحــة‬\n     ‫اعتراضيــة فأجيبــا لطلبهمــا وقــرر املدعــي العــام االعتــراض واالكتفــاء‬\n     ‫مبــا يف أوراق املعاملــة فأجيــب لطلبــه وبــاهلل التوفيــق وصلــى اهلل علــى‬\n\n\n‫‪13‬‬\n\f                                   ‫نبينــا محمــد وبــه حــرر يف ‪1434/4/3‬هــ‪.‬‬\n‫ويف يــوم األربعــاء املوافــق ‪1434/5/29‬ه ـ افتتحــت اجللســة الســاعة‬\n‫العاشــرة والربــع وقــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم‬\n‫(‪ )....‬وتاريــخ ‪1434/5/27‬ه ـ املتعلقــة بدعــوى املدعــي العــام ضــد ‪.......‬‬\n‫‪ ..... /2 /1‬وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة األولــى برقــم‬\n‫() وتاريــخ ‪1434/5/18‬ه ـ املتضمــن املصادقــة علــى احلكــم لــذا جــرى‬\n‫إحلــاق ذلــك حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                ‫وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n\n\n\n\n                                                                                    ‫‪14‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":5,"source_page_end":14,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e482d0bf6bf1341d36efe4089f6e030a460b095f94bf74178fb07770a53683bb","normalized_text_hash":"f6582ca1085f8a4dbf2f03ddf7449d9c624cc9838f4e0f6194a864235ac61959","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p5-34179143"},{"id":"5011b255-c6a6-5d5a-b260-efeae8aefe3b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج الهروين املخدر -تعاطي الهروين املخدر -إقرار املدعي عليه التعاطي وإنكار االجتار -وجود سوابق قضائية -تعزير بالسجن واجللد وإلغاء الشريحة.","document_number":"3382924","case_number":"32300716","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/2/15","year":"1434","subject":"مخدرات -ترويج الهروين املخدر -تعاطي الهروين املخدر -إقرار املدعي عليه التعاطي وإنكار االجتار -وجود سوابق قضائية -تعزير بالسجن واجللد وإلغاء الشريحة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 3382924 :‬تاريخه‪1433/2/15 :‬هـ‬\n                       ‫رقم الدعوى‪32300716:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪/438‬خ‪/1‬ب تاريخه‪1433/6/30 :‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬ترويــج الهرويــن املخــدر ‪ -‬تعاطــي الهرويــن املخــدر ‪ -‬إقــرار‬\n     ‫املدعــي عليــه التعاطــي وإنــكار االجتــار ‪ -‬وجــود ســوابق قضائيــة ‪ -‬تعزير‬\n                                           ‫بالســجن واجللــد وإلغــاء الشــريحة‪.‬‬\n\n\n\n\n                                                                 ‫‪ -‬حد املسكر‪.‬‬\n                          ‫‪ -‬الفقــرة (‪ )2‬املــادة (‪ )3‬والفقــرة (‪ )5‬مــن البنــد ً‬\n     ‫(أول) مــن املــادة (‪)37‬‬\n     ‫والفقــرة (‪ )1‬مــن املــادة (‪ )53‬واملــادة (‪ )62‬مــن نظــام مكافحة املخدرات‬\n                                                             ‫واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n        ‫‪ -‬تعميم وزير الداخلية (‪ )65980/4/5/1‬بتاريخ ‪1428/10/23‬هـ‪.‬‬\n\n\n\n     ‫أقــام املدعــى العــام علــى املدعــى عليــه دعــوى جنائيــة لقيامــه بترويــج‬\n     ‫الهيرويــن وتعاطيــه‪ -‬وإلعــداد منزلــه وكــرا يتــم مــن خاللــه ترويــج‬\n     ‫الهرويــن ‪ ،‬مت القبــض علــى املدعــى عليــه بعــد تســليم املصــدر الســري‬\n     ‫مــادة الهيرويــن‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة‬\n     ‫للهرويــن املخــدر‪ ،‬وشــهدت الفرقــة القابضــة بصحــة واقعــة القبــض‪،‬‬\n     ‫طالــب املدعــي العــام بإثبــات إدانــة املدعــى عليــه بعقوبــة القتــل ومصــادرة‬\n     ‫الهاتــف النقــال املســتخدم يف عمليــة الترويــج وإلغــاء الشــريحة املتعلقــة‬\n\n‫‪15‬‬\n\f‫بالرقــم املســتخدم يف اجلرميــة وعــدم صرفهــا للمدعــى عليــه مــرة أخــرى‪،‬‬\n‫وإلزامــه بــرد املبلــغ املالــي احلكومــي املرقــم وقــدره مائتــا ري ــال‪ ،‬أنكــر‬\n‫املدعــى عليــه مــا جــاء يف دعــوى املدعــي العــام‪ ،‬ثبــت لــدى احملكمــة‬\n‫تعاطــي املدعــى عليــه للهيرويــن املخــدر ولوجــود الشــبهة القويــة علــى‬\n‫الترويــج املعضــدة بالقرائن‪،‬وحكــم عليــه بحــده حــد املســكر ثمانــن‬\n‫جلــدة لقــاء تعاطيــه الهيرويــن ‪ ،‬وبســجنه خمــس ســنوات مــن تاريــخ‬\n‫إيقافــه‪ ،‬وجلــده ألــف جلــدة مفرقــة علــى دفعــات كل مــرة خمســون‬\n‫جلــدة علــى أن ال تقــل املــدة بــن كل دفعــة والتــي تليهــا عشــرة أيــام‬\n‫ويكــون نصــف اجللــد علنــا‪ ،‬وإلغــاء الشــريحة وعــدم صرفهــا للمتهــم‬\n‫مــرة أخــرى‪ ،‬ومنعــه مــن الســفر خلــارج البــاد مــدة مماثلــة ملــدة ســنتني‬\n‫بعــد انتهــاء مــدة محكوميتــه ‪ ،‬وقــد قنــع املدعــى عليــه‪ ،‬ومت تصديــق‬\n                                         ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدينــا‬\n‫نحــن ‪ .................‬و‪ ................‬القائــم بعمــل فضيلــة رئيــس احملكمــة‬\n‫‪ .................‬و‪.......................‬القائــم بع ــمل ف ــضيلة القاضــي ‪.................‬‬\n‫القضــاة يف احملكمــة العامــة بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا من‬\n‫فضيلــة رئيــس احملكمــة العامــة بالدمام‪/‬املســاعد برقــم ‪32300716‬‬\n‫وتاريــخ ‪1432/07/20‬ه ـ املقيــدة باحملكمــة برقــم ‪32923551‬وتاريــخ‬\n‫‪ 1432/07/20‬ه ـ ففــي يــوم االحــد املوافــق‪ 1432/08/16‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪02 : 05‬وفيهــا حضــر املدعــي العــام ‪ ................‬وادعــى‬\n‫علــى احلاضــر معــه ‪ ..................‬ســعودي اجلنســية مبوجــب الســجل‬\n\n                                                                                                 ‫‪16‬‬\n\f     ‫املدنــي رقــم ‪ ...................‬قائــا يف دعــواه بصفتــي مدعيـ ًا عامـ ًا بدائــرة‬\n     ‫االدعــاء العــام لفــرع الهيئــة باملنطقــة الشــرقية أدعــي علــى املذكــور‬\n     ‫أعــاه فباالطــاع علــى محضــر القبــض املعــد مــن قبــل رجــال الضبــط‬\n     ‫بشــعبة مكافحــة املخــدرات بالدمــام بتاريــخ ‪1432/5/5‬ه ـ تبــن أنــه‬\n     ‫مت القبــض علــى املدعــى عليــه اثــر بــاغ مــن أحــد املصــادر الســرية‬\n     ‫عــن قيامــه بترويــج الهيرويــن املخــدر مــن داخــل منزلــه وبنــاء عليــه مت‬\n     ‫متكــن املصــدر مــن االتصــال عليــه علــى جوالــه رقــم (‪ )..................‬وقــام‬\n     ‫املصــدر بطلــب هيرويــن مخــدر مببلــغ (‪ )100‬مائــة ريــال فطلــب منــه‬\n     ‫االتصــال عليــه بعــد ســاعة لكونــه مشــغو ًال وقــام املصــدر مــرة أخــرى‬\n     ‫باالتصــال عليــه فأفــاده بأنــه يقــوم اآلن بتجهيــز الكميــة املطلوبــة‬\n     ‫وطلــب منــه االنتظــار لدقائــق واحلضــور إليــه يف منزلــه وبنــاء عليــه مت‬\n     ‫ـراء للذمــة ومت تزويــده باملبلــغ‬   ‫تفتيــش املصــدر تفتيش ـ ًا دقيق ـ ًا وذلــك إبـ ً‬\n     ‫احلكومــي وقــدره (‪ )100‬مائــة ريــال ثــم ذهــب إلــى منــزل املدعــى عليــه‬\n     ‫حتــت أنظــار الفرقــة حتــى دخــل أحــد املنــازل ومت إقفــال بــاب املنــزل علــى‬\n     ‫الفــور ومت بعــد ذلــك مقابلــة املصــدر وأفــاد بأنــه اســتلم الكميــة املروجــة‬\n     ‫املطلوبــة وس ـلّم املبلــغ إلــى املدعــى عليــه فتــم اســتالم الكميــة املروجــة‬\n     ‫مــن قبــل أحــد أفــراد الفرقــة وهــي عبــارة عــن قصاصــة ورقيــة مطويــة‬\n     ‫عثــر بداخلهــا علــى مــادة بيضــاء اللــون تــزن (‪ )0.5‬خمســة مــن العشــرة‬\n     ‫مــن اجلــرام أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪1804‬ك ش)‬\n     ‫وتاريــخ ‪1432/5/26‬ه ــإيجابية املــادة املروجــة للهيرويــن املخــدر املدرجــة‬\n     ‫باجلــدول األول فئــة (أ) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة ‪ ،‬ولــم يتــم القبــض عليــه يف حينــه ومت رصــد منزلــه مــن يــوم‬\n     ‫الســبت بتاريــخ ‪1432/5/5‬ه ـ إلــى يــوم االثنــن بتاريــخ ‪1432/5/21‬ه ـ‬\n\n\n‫‪17‬‬\n\f‫ومت القبــض علــى عــدة أشــخاص يحضــرون إلــى منزلــه لشــراء الهيرويــن‬\n‫املخــدر ويقــوم بإدخالهــم إلــى املنــزل لتســليمهم الكميــات املروجــة ويف‬\n‫يــوم األحــد ‪1432/5/13‬ه ـ مت القبــض علــى املدعــو ‪ ............... /‬وهــو‬\n‫يخــرج مــن منــزل املدعــى عليــه وبحوزتــه كميــة مــن الهيرويــن املخــدر‬\n‫ومبناقشــته اعتــرف بأنــه يحصــل علــى الهيرويــن املخــدر مــن املدعــى‬\n‫عليــه ومت تقييــد قضيتــه بالرقــم (‪ ، )320500529‬ويف يــوم الثالثــاء‬\n‫‪1432/5/15‬ه ـ مت القبــض علــى املدعــو ‪ ............. /‬عقــب مشــاهدته‬\n‫مــن قبــل أفــراد الفرقــة وهــو يدخــل املنــزل وبالقبــض عليــه عثــر معــه‬\n‫علــى هيرويــن مخــدر ومبناقشــته عمــا عثــر معــه اعتــرف بأنــه يحصــل‬\n‫عليهــا مــن املدعــى عليــه وقيــدت قضيتــه بالرقــم (‪ ، )320500540‬ويف‬\n‫يــوم الســبت ‪1432/5/19‬ه ـ شــوهد املدعــو ‪ ................ /‬يحضــر إلــى‬\n‫منــزل املدعــى عليــه ويدخــل املنــزل و ميكــث بضعــة دقائــق ثــم يخــرج‬\n‫مــن املنــزل فتــم القبــض عليــه وبتفتيشــه عثــر معــه علــى هيرويــن مخــدر‬\n‫واعتــرف بأنــه حصــل عليهــا مــن املدعــى عليــه وقيــدت قضيتــه بالرقــم‬\n‫(‪ )320500565‬ويف يــوم االثنــن ‪1432/5/21‬ه ـ ويف الســاعة العاشــرة‬\n‫صباح ـ ًا وأثنــاء مراقبــة املنــزل مت القبــض علــى املدعــى عليــه أثنــاء‬\n‫حضــوره إلــى منزلــه وبتفتيشــه شــخصي ًا لــم ُيعثــر معــه علــى شــيء مــن‬\n‫وعثــر معــه علــى جــوال يحمــل الرقــم املصنعــي (‪)0588625‬‬    ‫املمنوعــات ُ‬\n‫وبداخلــه شــريحة ‪ ........‬ســارية املفعــول يحمــل نفــس الرقــم الــذي متــت‬\n‫عليــه عمليــة التنســيق لبيــع الهيرويــن املخــدر بتاريــخ ‪1432/5/5‬ه ـ‬\n‫ومبناقشــته عــن قيامــه بترويــج الهيرويــن املخــدر بتاريــخ ‪1432/5/5‬ه ـ‬\n‫أنكــر ذلــك ومت إيقافــه كــون جرميتــه تنــدرج حتــت القضايــا املوجبــة‬\n‫لإليقــاف وفــق القــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬هــ‪.‬‬\n\n\n                                                                                  ‫‪18‬‬\n\f     ‫وبســماع أقــوال املدعــى عليــه أنكــر قيامــه بالترويــج ملــادة الهيرويــن‬\n     ‫املخــدر وأقــر بتعاطيــه لــه وأنــه يحصــل علــى الهيرويــن مــن شــخص‬\n     ‫باكســتاني اجلنســية ‪ ،‬وباســتجوابه أنكــر قيامــه بترويــج الهيرويــن‬\n     ‫املخــدر وأفــاد بأنــه قــد اتصــل بــه شــخص يعرفــه وطلــب منــه مرافقتــه‬\n     ‫ملستشــفى ‪ .....‬باخلبــر وطلــب مــن هــذا الشــخص احلضــور إليــه كونهما ال‬\n     ‫ميلــكان ســيارة للذهــاب برفقــة أحــد األشــخاص وقــام أحــد األشــخاص‬\n     ‫بتوصيلهمــا إلــى اخلبــر وبعــد ذلــك عــادا مــن اخلبــر بســيارة أجــرة وعنــد‬\n     ‫وصولــه إلــى املنــزل مت القبــض عليــه مــن املكافحــة وبتفتيشــه لــم يتــم‬\n     ‫العثــور بحوزتــه علــى شــيء مــن املمنوعــات وبتفتيــش مرافقــه مت العثــور‬\n     ‫بحوزتــه علــى كيــس صغيــر يحتــوي علــى الهيرويــن املخــدر ومت القبــض‬\n     ‫عليهمــا جميع ـ ًا وأنكــر قيامــه بالترويــج للهيرويــن املخــدر وأنكــر‬\n     ‫قيامــه باالتفــاق علــى بيــع الهيرويــن املخــدر وإدخــال األشــخاص ملنزلــه‬\n     ‫لهــذا الغــرض وأن املدعــو ‪ ...............‬هــو جــاره ويحضــر إليــه يف أوقــات‬\n     ‫مختلفــة واملدعــو ‪ ...........‬زميــل عمــل ســابق يف شــركة ‪ ......‬وأمــا املدعــو‬\n     ‫‪ .............‬فبينهمــا خــاف وقــد طــرده مــن املنــزل وأضــاف بأنــه ال عالقــة‬\n     ‫لــه مبــا مت ضبطــه مــن مــادة الهيرويــن بحوزتهــم وال بطريقــة حصولهــم‬\n     ‫عليــه وفيمــا يخــص املدعــو ‪ .............‬فإنهمــا يتشــاركان يف الهيرويــن‬\n     ‫املخــدر وأضــاف بأنــه يحصــل علــى الهيرويــن املخــدر مــن عــدة أشــخاص‬\n     ‫مــن اجلنســية الباكســتانية وأنــه يتعاطــى الهيرويــن املخــدر‪ .‬وانتهــى‬\n     ‫التحقيــق إلــى اتهــام املدعــى عليــه بترويــج مــا وزنــه (‪ )0.5‬خمســة مــن‬\n     ‫العشــرة مــن اجلــرام مــن مــادة الهيرويــن املخــدر عــن طريــق البيــع وتعاطيــه‬\n     ‫لــه وفــق الفقــرة (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة ‪ ،‬وبإعــداد منزلــه وكــر ًا يتــم مــن خاللــه ترويــج مــادة‬\n\n\n‫‪19‬‬\n\f                                                                     ‫الهيرويــن املخــدر‪.‬‬\n                                                     ‫وذلك لألدلة والقرائن اآلتية ‪:‬‬\n    ‫‪ -1‬ما ورد يف أقوال املدعى عليه املنوه عنها على اللفة رقم (‪.)28-26‬‬\n‫‪ -2‬محضــر البــاغ واالتصــال والترقيــم والقبــض والتفتيــش املــدون علــى‬\n ‫الصفحــات رقــم (‪ )3 ،1‬مــن ملــف التحقيــق املرفــق علــى اللفــة رقــم (‪.)1‬‬\n‫‪ -3‬مــا ورد يف إفــادة األشــخاص اللذيــن مت القبــض عليهــم بعــد شــرائهم‬\n‫للهيرويــن املخــدر منــه حســب مــا تضمنــه محضــر القبــض املرفــق علــى‬\n              ‫الصفحــة رقــم (‪ )4-2‬مــن ملــف التحقيــق علــى اللفــة رقــم (‪.)1‬‬\n    ‫‪ -4‬التقرير الكيميائي الشرعي املرفق على اللفة رقم ( ‪.)18*-116‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه _ وهــو بكامــل أهليتــه املعتبــرة‬\n‫ـب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب مــا يلــي ‪:‬‬           ‫شــرع ًا _ فعــلٌ محـ ٌ‬\n                                                      ‫ـرم ومعاقـ ٌ‬\n‫أو ًال ‪ :‬إثبــات إدانتــه مبــا ُنســب إليــه وفقـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم‬\n‫(‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه‬\n                                                                               ‫مبــا يلــي ‪:‬‬\n‫‪ -1‬بعقوبــة القتــل املنصــوص عليهــا يف الفقــرة رقــم (‪ )5‬مــن البنــد أو ًال‬\n‫مــن املــادة (‪ )37‬مــن النظــام املشــار إليــه مــع مراعــاة مــا تقضــي بــه املــادة‬\n                                                             ‫(‪ )62‬مــن النظــام ذاتــه‪.‬‬\n‫‪ -2‬مبصــادرة جوالــه الــذي يحمــل الرقــم املصنعــي رقــم (‪)0588625‬‬\n‫وفقـ ًا للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن النظام ذاته وعدم صرف الشــريحة‬\n‫لنفــس املدعــى عليــه وفق ـ ًا لتعميــم وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ‬\n                                                                   ‫‪1428/2/10-9‬هـ‪.‬‬\n‫ثاني ـ ًا ‪ :‬املطالبــة باملبلــغ املرقــم الــذي لــم يتــم العثــور عليــه وفــق تعميــم‬\n‫وزيــر الداخليــة رقــم (‪ )65980/4/5/1‬وتاريــخ ‪1428/10/23-22‬هــ‪.‬‬\n\n\n                                                                                               ‫‪20‬‬\n\f     ‫هكــذا ادعــى وبســؤال املدعــى عليــه عمــا جــاء يف دعــوى املدعــي العــام‬\n     ‫أجــاب قائــا مــا ذكــره املدعــي العــام غيــر صحيــح وأمــا األشــخاص‬\n     ‫الثالثــة الذيــن قبــض عليهــم بعــد خروجهــم مــن منزلــي ومعهــم الهيرويــن‬\n     ‫فقــد كانــوا يحضــرون إلــي ويطلبــون منــي أن أســتخدم معهــم فأرفــض‬\n     ‫ذلــك هكــذا اجــاب فطلبنــا مــن املدعــي العــام حتديــد الترويــج هــل هــو‬\n                                                ‫للمــرة األولــى أو الثانيــة فاســتعد بذلــك‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف‬\n     ‫يــوم الثالثــاء ‪1432/10/29‬ه ـ افتتحــت اجللســة الســاعة ‪01 : 04‬وفيهــا‬\n     ‫حضــر الطرفــان علمــا أن املوعــد الســابق كان رئيــس اجللســة فيــه يف‬\n     ‫إجــازة اعتياديــة وجــرى ســؤال املدعــي العــام عــن الترويــج هــل هــو للمــرة‬\n     ‫الثانيــة قــال نعــم ثــم جــرى ســؤاله عــن البينــة قــال أطلــب مهلــة لذلــك‬\n     ‫فأجيــب لطلبــه وأقفلــت اجللســة الســاعة الواحــدة والربــع ورفعــت ليــوم‬\n     ‫األحــد ‪1432/11/25‬ه ـ الســاعة التاســعة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1432/10/29‬ه ـ‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف يــوم‬\n     ‫األحــد ‪1432/11/25‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 35‬وفيهــا حضــر‬\n     ‫املدعــي العــام وأحضــر البينــة وهــم‪ :‬الشــاهد ‪ ...........‬ســعودي بالســجل‬\n     ‫املدنــي رقــم ‪ ..............‬مــن مواليــد عــام ‪1397‬ه ـ والشــاهد ‪.................‬‬\n     ‫سعودي بالسجل املدني رقم ‪ .............‬من مواليد عام ‪1389‬هـ والشاهد‬\n     ‫‪ .................‬ســعودي بالســجل املدني رقم ‪ ..............‬والشــاهد ‪.................‬‬\n     ‫ســعودي بالســجل املدنــي رقــم ‪ ................‬مــن مواليــد عــام ‪1401‬ه ـ ولــم‬\n     ‫يحضــر املدعــى عليــه رغــم طلبنــا لــه بخطابنــا بتاريــخ ‪1432/11/10‬ه ـ‬\n     ‫وأقفلــت اجللســة لذلــك الســاعة التاســعة وأربعــن دقيقــة ورفعــت ليــوم‬\n\n\n‫‪21‬‬\n\f‫األحــد ‪1433/1/2‬ه ـ الســاعة التاســعة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1432/11/25‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدينــا‬\n‫نحــن ‪ .................‬مســاعد رئيــس احملكمــة العامــة بالدمــام والقائــم‬\n‫بعمــل فضيلــة الرئيــس الشــيخ ‪ .................‬والقاضيــان ‪......................‬و‪....‬‬\n‫‪ ............‬ويف يــوم األحد‪1433/1/2‬ه ـ افتتحــت اجللســة الســاعة التاســعة‬\n‫والربــع وحضــر الطرفــان ولــم يحضــر املدعــي العــام بينتــه فطلبنــا منــه‬\n‫إحضارهــا اجللســة القادمــة فاســتعد بذلــك لــذا أقفلــت اجللســة لذلــك‬\n‫الســاعة التاســعة والنصــف ورفعــت ليــوم األحد‪1433/1/16‬ه ـ الســاعة‬\n‫التاســعة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                      ‫آلــه وصحبــه وســلم ‪ .‬حرريف‪1433/1/2‬ه ـ‬\n‫وقــد جــرى ســماع الدعوى واجلواب بحضــور فضيلة الرئيس ‪...................‬‬\n‫ويف يــوم االحــد املوافــق ‪1433/01/16‬ه ـ حضــر الطرفــان وأحضــر‬\n‫املدعــي العــام الفرقــة القابضــة ومــن ضمنهــم الشــاهد ‪...............‬ســعودي‬\n‫بالســجل املدنــي رقــم (‪ )...............‬مــن مواليــد الدمــام ‪1406‬ه ـ و يعمــل‬\n‫عريف ًا يف مكافحة املخدرات والشــاهد ‪ ....................‬ســعودي اجلنســية‬\n‫بالســجل املدنــي رقــم ‪...................‬مــن مواليــد عــام ‪1389‬ه ـ ويعمــل رقيبـ ًا‬\n‫يف مكافحــة املخــدرات وبســؤال كل واحــد عمــا لديــه قــال كل واحــد‬\n‫منهمــا مبفــرده أشــهد بأننــي مــن ضمــن الفرقــة القابضــة التــي كتبــت‬\n‫محضــر القبــض و التفتيــش علــى املدعــى عليه احلاضــر ‪ .................‬وذلك‬\n‫أنــه وردنــا بــاغ عــن املدعــى عليــه ببيعــه املخــدرات فاتصــل املصــدر علــى‬\n‫املدعــى عليــه و أنــا أســمعه و طلــب منــه بيعــه هيرويــن فوافــق املدعــى‬\n‫عليــه وواعــده بعــد ســاعة ثــم ذهــب املصــدر الــى املدعــى عليــه مبنزلــه‬\n\n\n                                                                                            ‫‪22‬‬\n\f     ‫الواقــع يف حــي ‪ .............‬وفتــح لــه بــاب املنــزل املدعــى عليــه وقــد رأينــاه‬\n     ‫و هــو يفتــح البــاب ثــم دخــل املصــدر بعــد تفتيشــه و ملــا خــرج املصــدر‬\n     ‫قابلتــه ووجــدت معــه كميــة مــن الهيرويــن ولــم نقبــض علــى املدعــى‬\n     ‫عليــه مباشــرة وقــد راقبنــا املنــزل عــدة أيــام وقبضنــا علــى اثنــن يخرجــان‬\n     ‫منــه ومعهــم كميــة مــن الهيرويــن وبســؤالهما أجابــا بأنهمــا يشــتريان‬\n     ‫مــن املدعــى عليــه ‪ ................‬الهيرويــن علم ـ ًا أن الرقــم الــذي اتصــل‬\n     ‫عليــه املصــدر وجدنــاه مــع املدعــى عليــه هكــذا شــهدا ثــم جــرى عــرض‬\n     ‫الشــاهدين علــى املدعــى عليــه فقــال إننــي لــم أروج ولــم يذكــر فيهمــا‬\n     ‫شــيئا وجــرى تزكيتهمــا مــن قبــل الشــاهد ‪ ...............‬ســعودي اجلنســية‬\n     ‫ـزك آخــر فقــال الشــاهدان‬           ‫بالســجل املدنــي رقــم‪ ...............‬فطلبنــا مـ ٍ‬\n     ‫سنرســله خــال هــذا األســبوع ويف يــوم الســبت ‪1433/1/29‬ه ـ حضــر‬\n     ‫املزكــي ‪ ...............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n            ‫‪ ..............‬الــذي شــهد بثقــة وعدالــة الشــاهدين ‪.............................‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف هــذا‬\n     ‫اليــوم األحد‪1433/1/23‬ه ـ افتتحــت اجللســة الســاعة ‪48:12‬وحضــر‬\n     ‫الطرفــان ولــم يحضــر املزكــي لــذا أقفلــت اجللســة الســاعة الثانيــة‬\n     ‫عشــرة وخمســن دقيقــة ورفعــت ليــوم األربعــاء ‪1433/1/26‬ه ـ إلحضــار‬\n     ‫املزكــي وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                              ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/1/23‬ه ـ‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف هــذا‬\n     ‫اليــوم األربعــاء ‪1433/1/26‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 00‬وفيهــا‬\n     ‫حضــر الطرفــان ولــم يتــم إحضــار املزكــي وقــد جــرى االتصــال علــى‬\n     ‫الشــاهد ‪ ....‬عــدة مــرات واســتعد بإحضــار مــزك ولــم يتــم إحضــاره لــذا‬\n\n\n‫‪23‬‬\n\f‫جــرى إفهــام املدعــي العــام إن لــم يتــم إحضــار املزكــي اآلخــر فســيتم‬\n‫البــت يف القضيــة وأقفلــت اجللســة الســاعة احلاديــة عشــر وعشــر دقائــق‬\n‫ورفعــت ليــوم األحــد ‪1433/2/14‬ه ـ الســاعة العاشــرة وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                  ‫‪1433/1/26‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف هــذا‬\n‫اليوم السبت ‪1433/1/29‬ه ــافتتحت اجللسة الساعة ‪42:05:01‬وحضر‬\n‫املزكــي ‪ .................‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ 1013242407‬الــذي شــهد بثقــة وعدالــة الشــاهدين ‪.........................‬‬\n‫وأقفلــت اجللســة الواحــدة والربــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/1/29‬ه ـ‬\n‫ويف يــوم األحــد ‪1433/2/14‬ه ـ ا حضــر الطرفــان وقــرر املدعــي العــام‬\n‫أن الترويــج للمــرة الثانيــة وذلــك بنــاء علــى القــرار الشــرعي الصــادر مــن‬\n‫احملكمــة اجلزئيــة بالدمــام رقــم ‪ 2/175‬وتاريــخ ‪1416/6/12‬هـ هكذا‬\n‫قــرر وباالطــاع عليــه وجدنــاه مطابقــا ملــا ذكــر فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وعــدم البينــة املوصلــة للدعــوى واســتالم املبلــغ فلــم‬\n‫يثبــت لدينــا مــا أســند إليــه مــن ترويجــه ملــادة الهروين املذكــورة وإلقراره‬\n‫بتعاطــي الهرويــن املخــدر فقــد ثبــت لدينــا تعاطيــه للهرويــن املخــدر‬\n‫ولوجــود الشــبهة القويــة علــى الترويــج املعتضــدة بالقرائــن مــن شــهادة‬\n‫الفرقــة القابضــة ووجــود الشــريحة التــي حتمــل الرقــم الــذي اتصــل عليــه‬\n‫املصــدر معــه وخــروج األشــخاص مــن منزلــه ومعهــم شــيء مــن املخــدرات‬\n‫ولوجــود الســوابق عليــه جلميــع مــا ســبق فقــد أمرنــا مبــا يلــي أوال‪ :‬يجلــد‬\n‫املدعــى عليــه حــد املســكر ثمانــن جلــده لقــاء تعاطيــه الهرويــن املخدر‪،‬‬\n\n\n                                                                                       ‫‪24‬‬\n\f     ‫ثانيــا‪ :‬يســجن خمــس ســنوات مــن تاريــخ إيقافــه ‪ ،‬ثالثــا‪ :‬يجلــد تعزيــرا‬\n     ‫ألــف جلــده مفرقــه علــى دفعــات كل دفعــة خمســون جلــده بــن الدفعــة‬\n     ‫والتــي تليهــا مــا ال يقــل عــن عشــرة أيــام ويكــون نصــف اجللــد بعــد صــاة‬\n     ‫اجلمعــة أمــام جامــع ‪ ...........‬يف حــي ‪ ...........‬بالدمــام مكشــوف الوجــه‬\n     ‫والــرأس والنصــف اآلخــر بعــد صــاة اجلمعــة أمــام جامــع ‪ ..........‬بالدمــام‬\n     ‫مكشــوف الوجــه والــرأس رابعــا‪ :‬تصــادر الشــريحة التــي اتصــل‬\n     ‫عليهــا املصــدر ووجــدت مــع املدعــى عليــه وال تصــرف لــه مــرة أخــرى‬\n     ‫تعزيــرا خامســا‪ :‬مينــع املدعــى عليــه مــن الســفر ملــدة خمــس ســنوات بعــد‬\n     ‫انتهــاء محكوميتــه بنــاء علــى املــادة (‪3‬و‪ )56‬مــن نظــام املخــدرات وبــه‬\n     ‫حكمنــا وبعرضــه عليهمــا قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام‬\n     ‫وطلــب االســتئناف مســتعدا بتقــدمي الئحــة اعتراضيــة فأجيــب لطلبــه‬\n     ‫وأفهــم مبراجعــة احملكمــة يــوم الســبت ‪1433/2/20‬هـ الســتالم نســخة‬\n     ‫احلكــم لتقــدمي االعتــراض عليــه خــال ثالثــن يومــا مــن تاريــخ حتديــد‬\n     ‫اســتالم صــورة احلكــم وإذا مضــت املــدة ولــم يقــدم شــيئا ســقط حقــه‬\n     ‫يف االعتــراض وســترفع املعاملــة حملكمــة االســتئناف وكانــت ســاعة‬\n     ‫النطــق باحلكــم احلاديــة عشــرة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/2/14‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n     ‫فقــد وردتنــا املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n     ‫برقــم‪ 33/861348‬وتاريــخ ‪1433/7/8‬ه ـ املرفــق بهــا قــرار الدائــرة‬\n     ‫اجلزائيــة اخلماســية األولــى رقــم ‪/438‬خ‪/1‬ب وتاريــخ ‪1433/6/30‬ه ـ‬\n     ‫املتضمــن بعــد املقدمــة مــا نصــه (وبدراســة القــرار وصــورة ضبطــه‬\n     ‫وأوراق املعاملــة لوحــظ مــا يلــي‪ :‬أوالً‪ /‬أن أصحــاب الفضيلــة حكمــوا‬\n\n\n‫‪25‬‬\n\f‫مبنــع املدعــى عليــه مــن الســفر ملــدة خمــس ســنوات مــع أنــه لــم يثبــت‬\n‫عليــه ســوى االســتعمال واملتعــن احلكــم مبنعــه مــن الســفر ســنتني ثانيـاً‪/‬‬\n‫لــم يجــر أصحــاب الفضيلــة الــازم حيــال طلــب املدعــي العــام بإعــادة‬\n‫املبلــغ املرقــم ملالحظــة مــا ذكــر وإكمــال الــازم ومــن ثــم إعــادة املعاملــة‬\n‫إلكمــال الزمهــا واهلل املوفــق) أعضــاء الدائــرة قاضــي اســتئناف د‪.‬‬\n‫‪.....................‬توقيعــه وختمــه قاضــي اســتئناف ‪ .............‬توقيعــه وختمــه‬\n‫قاضــي اســتئناف ‪ ................‬توقيعــه وختمــه قاضــي اســتئناف ‪.............‬‬\n‫توقيعــه وختمــه رئيــس الدائــرة ‪ .................‬توقيعــه وختمــه‪ ،‬واجلــواب‬\n‫علــى ذلــك فــإن املالحظــة األولــى فقــد رجعنــا عمــا حكمنــا مبنعــه مــن‬\n‫الســفر ملــدة خمــس ســنوات وحكمنــا مبنعــه ملــدة ســنتني وأمــا اجلــواب‬\n‫علــى املالحظــة الثانيــة فلــم يثبــت لدينــا موجــب إعــادة املبلــغ وصرفنــا‬\n‫ا للحكــم الســابق وبــاهلل‬    ‫النظــر عــن ذلــك وبــه حكمنــا حكمـ ًا مكمـ ً‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                    ‫حــرر يف ‪1433/10/28‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فقــد‬\n‫وردتنــا املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية برقــم‬\n‫‪ 33/2049430‬وتاريــخ ‪1434/2/2‬ه ـ املرفــق بهــا الدائــرة اجلزائيــة‬\n‫اخلماســية األولــى رقــم ‪3416907‬وتاريــخ ‪1434/1/19‬ه ـ املتضمــن مــا‬\n‫نصــه (وحيــث ســبق دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫وباالطــاع علــى مــا أجــاب بــه أصحــاب الفضيلــة علــى قرارنــا رقــم‬\n‫‪/438‬خ‪/1‬ب وتاريــخ ‪1433/6/30‬ه ـ قررنــا املصادقــة علــى احلكــم‬\n‫بعــد اإلجــراء األخيــر واهلل املوفــق) أعضــاء الدائــرة قاضــي اســتئناف‬\n‫د‪ ....................‬توقيعــه وختمــه قاضــي اســتئناف ‪ ................‬توقيعــه‬\n\n\n                                                                                        ‫‪26‬‬\n\f     ‫وختمــه قاضــي اســتئناف ‪ ................‬توقيعــه وختمــه قاضــي اســتئناف‬\n     ‫‪ ..................‬توقيعــه وختمــه رئيــس الدائــرة ‪ ..................‬توقيعــه وختمــه‬\n     ‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                     ‫وســلم حــرر يف ‪1434/2/11‬هــ‪.‬‬\n     ‫احلمد هلل وحده وبعد ‪ . . .‬فقد اطلعنا نحن قـضاة الدائــرة اجلزائـيـة اخلماسـيـة‬\n     ‫األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام الشــيخ‪................./‬‬\n     ‫برقــم ‪ 331313428‬وتاريــخ ‪1433/11/14‬ه ـ واملقيــدة لــدى احملكمــة‬\n     ‫برقــم ‪/33/2049430‬خ‪ 1‬وتاريــخ ‪1433/11/17‬ه ـ املرفــق بهــا القــرار‬\n     ‫الشــرعي ذو الرقــم ‪ 3382924‬والتاريــخ ‪1433/2/15‬ه ـ الصــادر‬\n     ‫مــن فضيلتــه وصاحبــي الفضيلــة القضــاة باحملكمــة املشــاركني لــه‬\n     ‫الشــيخ‪ .................../‬والشــيخ‪/‬د‪ .......................‬اخلــاص بدعــوى‪ /‬املدعي‬\n     ‫العــام ضــد‪ ................../‬يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم‬\n     ‫أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل فيــه ‪ .‬وحيــث ســبق دراســة‬\n     ‫القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n     ‫أصحــاب الفضيلــة علــى قرارنا رقم ‪/438‬خ‪/1‬ب وتاريخ ‪1433/6/30‬هـ‬\n     ‫قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪.‬واهلل املوفــق وصلــى‬\n       ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪ 1434/1/19‬ه ـ ‪.‬‬\n\n\n\n\n‫‪27‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":15,"source_page_end":27,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2584b5c464371d81bdbeeb5b8b5ff8bfb9fc724dd564ba71b94d2a7a626fcdd2","normalized_text_hash":"f442d9b9124b8dee39dae3cd4c9bc9606528c42bbe058bdd95e24bb1b140c662","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p15-3382924"},{"id":"dae07222-574f-510d-a8c1-91af6886f7d7","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -حيازة قطع من احلشيش -حيازة احلبوب احملظورة -تعاطي احلشيش -تعاطي احلبوب احملظورة -الوساطة يف ترويج احلشيش املخدر -إقامه حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد واملصادرة والغرامة واإلبعاد.","document_number":"33358951","case_number":"32473675","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باجلبيل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/28","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -حيازة قطع من احلشيش -حيازة احلبوب احملظورة -تعاطي احلشيش -تعاطي احلبوب احملظورة -الوساطة يف ترويج احلشيش املخدر -إقامه حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد واملصادرة والغرامة واإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33358951:‬تاريخه ‪1433/7/28 :‬هـ‬\n                   ‫رقم الدعوى ‪32473675:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34181852‬تاريخه‪1434/4/8 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬حيــازة قطــع مــن احلشــيش‬\n‫‪ -‬حيــازة احلبــوب احملظــورة ‪ -‬تعاطــي احلشــيش ‪ -‬تعاطــي احلبــوب‬\n‫احملظــورة ‪ -‬الوســاطة يف ترويــج احلشــيش املخــدر ‪ -‬إقامــه حــد املســكر‬\n‫علــى متعاطــي احلشــيش ‪ -‬التعزيــر بالســجن واجللــد واملصــادرة‬\n                                                      ‫والغرامــة واإلبعــاد‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ‪ (:‬كل مســكر حــرام ) رواه أبــو داود‬\n                                                                     ‫واحمــد‪.‬‬\n‫‪ -2‬قولــه صلــى اهلل عليــه وســلم ‪(:‬مــن شــرب اخلمــر فاجلــدوه) رواه أبــو‬\n                                                                ‫داود واحمــد‪.‬‬\n‫‪ -3‬املــواد (‪ )38‬و(‪)41‬و(‪)53‬و(‪)56‬و(‪ )62‬مــن نظــام مكافحــة املخــدرات‬\n                                                        ‫واملؤثــرات العقليــة‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا األول ‪ :‬بترويــج احلشــيش‬\n‫املخــدر‪ ،‬وحيــازة عــدد مــن قطــع احلشــيش وعــدد مــن حبــوب الــروش‬\n‫احملظــورة ‪ ،‬وعــدد مــن ســجائر احلشــيش بقصــد التعاطــي وتعاطيــه‬\n‫للحبــوب احملظــورة ‪ ،‬واحلشــيش املخــدر‪ ،‬املدعــي عليــه الثانــي ‪:‬‬\n‫بالتوســط يف ترويج احلشــيش املخدر وحيازة قطعه من احلشــيش بقصد‬\n\n                                                                                 ‫‪28‬‬\n\f     ‫التعاطــي وتعاطيــه لــه‪ ،‬حيــث وردت معلومــات ملكافحــة املخــدرات عــن‬\n     ‫قيــام املدعــى عليــه الثانــي بالتوســط يف ترويــج احلشــيش املخــدر ومت‬\n     ‫متكــن املصــدر مــن االتصــال عليــه واتفــق املصــدر مــع الوســيط علــى‬\n     ‫شــراء قطعــة مــن احلشــيش وشــوهد الوســيط (املدعــى عليــه الثانــي )‬\n     ‫وهــو يركــب مــع املصــدر يف ســيارته وحتــرك ثــم توقــف بجــوار إحــدى‬\n     ‫الفلــل ونــزل الوســيط ثــم عــاد وركــب مــع املصــدر وحتــرك بعــد خمــس‬\n     ‫دقائــق ‪ ،‬أعطــى املصــدر اإلشــارة املتفــق عليهــا ومت ضبــط الوســيط‬\n     ‫وضبــط معــه علــى قطعــة حشــيش ‪ ،‬كمــا قــام املصــدر بتســليم القطعــة‬\n     ‫املشــتراة للفرقــة وأفــاد الوســيط أن الــذي قــام بتســليم تلــك القطعــة أحــد‬\n     ‫املروجــن ويســكن يف الفيــا التــي كان يقــف عنــد بابهــا قبــل القبــض‬\n     ‫عليــه‪ ،‬ومت القبــض علــى املــروج ‪ ،‬وبتفتيــش غرفــة املــروج عثــر علــى‬\n     ‫ســبع قطــع حشــيش ‪ ،‬كمــا عثــر علــى عــدد مــن حبــوب الــروش وعثــر‬\n     ‫علــى طفايــة بهــا ســجائر مخلوطــة باحلشــيش كمــا عثــر مــع الوســيط‬\n     ‫علــى جــزء مــن املبلــغ املرقــم بينمــا عثــر مــع املــروج علــى جــزء آخــر‪ .‬وطلــب‬\n     ‫املدعــي العــام إثبــات مــا أســند للمدعــى عليهما ‪ ،‬أقر املدعــى عليه األول‬\n     ‫مبــا نســب إليــه ‪ -‬دفــع بــأن حبــوب الــروش يســتعملها بنــاء علــى وصفــه‬\n     ‫طبيــه‪ -‬أحضــر الوصفــة الطبيــة ‪ ،‬اقــر املدعــى عليــه الثانــي مبــا نســب‬\n     ‫إليــه ‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بإقامــه حــد املســكر‬\n     ‫عليهمــا وبتعزيرهمــا بالســجن واجللــد واملصــادرة والغرامــة وإعــادة املبلــغ‬\n     ‫احلكومــي حســب مــا هــو مفصــل يف منطــوق احلكــم ‪ ،‬وصــدق احلكــم‬\n                                                           ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪29‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ ......‬القاضــي باحملكمــة العامــة باجلبيــل وبنــاء علــى املعاملــة احملالــة لنــا‬\n‫برقــم (‪ ).....‬وتاريــخ ‪1432/10/23‬ه ـ واملقيــدة باحملكمــة برقــم (‪).....‬‬\n‫وتاريــخ ‪1432/10/23‬ه ـ ففــي يــوم االحــد املوافــق ‪1433/03/13‬ه ـ‬\n‫افتتحــت اجللســة الســاعة العاشــرة وفيهــا حضــر املدعــي العــام بدائــرة‬\n‫التحقيــق واإلدعــاء العــام باجلبيــل ‪ ......‬واملدعــى عليهمــا ‪ ......‬ســعودي‬\n‫بالســجل املدنــي رقــم ( ‪ )......‬و ‪ ......‬ســعودي بالســجل املدنــي رقــم ( ‪)......‬‬\n‫وادعــى املدعــي العــام قائــا بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة التحقيــق‬\n‫واإلدعــاء العــام مبحافظــة اجلبيــل أدعــى علــى كل مــن ‪ -1-:‬املواطــن ‪/‬‬\n‫‪ ، ......‬مبوجــب الســجل املدنــي رقــم (‪ )......‬البالــغ مــن العمــر(‪ )27‬عامـاً‪،‬‬\n‫مفــرج عنــه ويســكن مبحافظــة اجلبيــل‪ -2‬املواطــن ‪ ، ...... /‬مبوجــب‬\n‫الســجل املدنــي رقــم (‪ )......‬البالــغ مــن العمــر(‪ )26‬عام ـ ًا ‪ ،‬مفــرج عنــه‬\n‫ويســكن مبحافظــة اجلبيــل حيــث أنــه بتاريــخ ‪1432/9/5-4‬ه ـ وردت‬\n‫معلومــات ملكافحــة املخــدرات باجلبيــل مــن أحــد مصادرهــا الســرية عــن‬\n‫وجــود شــخص يدعــى (‪ )......‬يســكن مبدينــة الدمــام ويقــوم بالتوســط‬\n‫بترويــج احلشــيش املخــدر وقــد أبــدى املصــدر اســتعداده لإلطاحــة بــه ومت‬\n‫متكــن املصــدر مــن االتصــال بالوســيط على رقــم جوالــه (‪ )......‬وكانت‬\n‫املكاملــة علــى مســمع مــن أحــد أفــراد الفرقــة ‪ ،‬حيــث اتفــق املصــدر مــع‬\n‫الوســيط علــى شــراء قطعــة مــن احلشــيش املخــدر ب ـ (‪ )500‬بخمســمائة‬\n‫ـاء مــن يــوم‬\n             ‫ريــال) وكانــت املكاملــة عنــد الســاعة (‪ )8:00‬الثامنــة مسـ ً‬\n‫االثنــن املوافــق ‪1432/9/4‬ه ـ ‪ ،‬عليــه مت التنســيق مــع شــعبة مكافحــة‬\n\n                                                                                         ‫‪30‬‬\n\f     ‫املخــدرات بالدمــام ومت االنتقــال برفــق املصــدر بعــد تفتيشــه ومت تزويــده‬\n     ‫مببلــغ مرقــم قــدره (‪ )500‬خمســمائة ريــال ومتــت مراقبــة املصــدر الــذي‬\n     ‫كان يقــف بجــوار عمــارة ســكينة باحلــي ‪ ....‬بالدمــام وعنــد الســاعة‬\n     ‫ـاء شــوهد شــخص اتضــح فيمــا بعــد‬         ‫(‪ )9:30‬التاســعة والنصــف مسـ ً‬\n     ‫أنــه الوســيط وهــو يركــب مــع املصــدر يف ســيارته ثــم حتــركا باجتــاه‬\n     ‫حــي ‪ ....‬بالدمــام خلــف عمــارة ‪ ....‬وتوقــف بجــوار إحــدى الفلــل ونــزل‬\n     ‫الوســيط وشــوهد وهــو يقــف عنــد بــاب أحــد املنــازل وبعــد (‪ )10‬عشــر‬\n     ‫دقائــق عــاد الوســيط وركــب مــع املصــدر وحتــركا وبعــد خمــس دقائــق‬\n     ‫قــام املصــدر بإعطــاء إشــارة للفرقــة للداللــة علــى أنــه متــت عمليــة البيــع‬\n     ‫بعدهــا مت ضبــط الوســيط واتضــح أنــه املدعــى عليــه الثانــي ومت ضبــط‬\n     ‫قطعــة بنيــة اللــون بلــغ وزنهــا (‪ )1.5‬جــرام واحــد ونصــف اجلــرام يشــتبه‬\n     ‫أن تكــون مــن احلشــيش املخــدر كان يضعهــا علــى فخــذه األميــن كمــا‬\n     ‫قــام املصــدر بتســليم القطعــة املشــتراة للفرقــة وهــي قطعــة بنيــة اللــون‬\n     ‫بلــغ وزنهــا (‪ )12.1‬إثنــا عشــر جرامــا وواحــد مــن العشــرة مــن اجلــرام‬\n     ‫يشــتبه أن تكــون مــن احلشــيش املخــدر وقــد أفــاد الوســيط بــأن الــذي‬\n     ‫قــام بتســليم تلــك القطعــة أحــد املروجــن يدعــى (‪ )......‬ويســكن يف‬\n     ‫الفيــا التــي كان يقــف عنــد بابهــا قبــل القبــض عليــه فتمــت مراقبــة‬\n     ‫املدعــو (‪ )......‬وعنــد الســاعة (‪ )2:00‬الثانيــة فجــر ًا مــن يــوم (الثالثــاء)‬\n     ‫املوافــق ‪1432/9/5‬ه ـ شــوهد املذكــور فتــم القبــض عليــه واتضــح أنــه‬\n     ‫املدعــى عليــه األول والــذي أفــاد بوجــود بقيــة املخــدرات يف منزلــه فتــم‬\n     ‫اصطحــاب املفتشــة إلــى منزلــه ومت مقابلــة والــد املــروج والــذي أفــاد‬\n     ‫بأنــه ال مانــع لديــه مــن تفتيــش منزلــه ‪ ،‬وبتفتيــش غرفــة املــروج عثــر‬\n     ‫بأحــد األدراج علــى عــدد (‪ )7‬ســبع قطــع بنيــة اللــون بلــغ مجمــوع وزنهــا‬\n\n\n‫‪31‬‬\n\f‫(‪ )480.5‬أربعمائــة وثمانــن جرام ـ ًا وخمــس مــن العشــرة مــن اجلــرام‬\n‫يشــتبه أن تكــون مــن احلشــيش املخــدر كمــا عثــر بــدرج آخــر علــى‬\n‫علبــة بداخلهــا عــدد (‪ )41‬إحــدى وأربعــن حبــة بيضــاء اللــون يشــتبه‬\n‫أن تكــون مــن حبــوب الــروش احملظــورة وبتفتيــش املجلــس عثــر علــى‬\n‫طفايــة بهــا عــدد (‪ )3‬ثــاث ســجائر ملفوفــة بلــغ وزنهــا (‪ )4‬أربــع جرامــات‬\n‫ونصــف اجلــرام يشــتبه أن تكــون مخلوطــة باحلشــيش املخــدر كمــا عثــر‬\n‫مــع الوســيط علــى مبلــغ مالــي قــدره (‪ )100‬مائــة ريــال مــن املبلــغ املرقــم‬\n‫بينمــا عثــر مــع املــروج علــى مبلــغ (‪ )100‬مائــة ريــال فقــط مــن ملبلــغ املرقــم‬\n‫‪ ،‬وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪ 2992‬ك ش) وتاريــخ‬\n‫‪1432/9/13‬ه ـ إيجابيــة عينــات مــا مت ضبطــه مــن القطــع ملادة احلشــيش‬\n‫املخــدر واحتــواء مــا مت ضبطــه مــن الســجائر امللفوفــة على مادة احلشــيش‬\n‫املخــدر املــدرج باجلــدول رقــم (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ‬\n‫‪1426/7/9‬ه ـ ‪ ،‬وإيجابيــة مــا مت ضبطــه مــن احلبــوب احملظــورة كل‬\n‫علــى حــدة لعقــار الكلونازيبــام احملظــور املــدرج باجلــدول رقــم (‪ )2‬فئــة‬\n‫(د) مــن النظــام املشــار إليــه وباســتجواب األول (‪ )......‬أقــر بصحــة واقعــة‬\n‫القبــض عليــه مــن قبــل مكافحــة املخــدرات باجلبيــل بعــد قيامــه بترويــج‬\n‫قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )12.1‬إثنــا عشــر جرامــا وواحــد‬\n‫مــن العشــرة مــن اجلــرام مقابــل مبلــغ مالــي قــدره (‪ )400‬أربعمائــة ريــا ًال‬\n‫وكانــت عمليــة الترويــج بقصــد خدمــة زميلــه كمــا أقــر أنــه مت ضبــط‬\n‫عــدد (‪ )41‬واحــد وأربعــن حبــة مــن حبــوب الــروش احملظــورة وعــدد (‪)7‬‬\n‫ســبع قطــع مــن احلشــيش املخــدر بلــغ مجمــوع وزنهــا (‪ )480.5‬أربعمائــة‬\n‫وثمانــن جرام ـ ًا وخمســة مــن العشــرة مــن اجلــرام بأحــد األدراج باملنــزل‬\n\n\n                                                                                           ‫‪32‬‬\n\f     ‫كمــا عثــر باملجلــس داخــل طفايــة ســجائر علــى عــدد (‪ )3‬ثالثــة ســجائر‬\n     ‫مخلوطــة باحلشــيش املخــدر بلــغ مجمــوع وزنهــا (‪ )4.0‬أربعــة جرامــات‬\n     ‫وقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )4.5‬أربعــة جرامــات ونصــف‬\n     ‫اجلــرام جميعهــا تعــود لــه بقصــد التعاطــي وأمــا حبــوب الــروش فهــي‬\n     ‫للعــاج النفســي وقــد حصــل علــى هــذه الكميــات مــن شــخص بالقطيف‬\n     ‫ال يعــرف اســمه مببلــغ (‪ )7000‬ســبعة آالف ريــال وأنــه يتعاطــى احلشــيش‬\n     ‫املخــدر وحبــوب الــروش احملظــورة منــذ أربــع ســنوات وباســتجواب الثاني‬\n     ‫(‪ )......‬أقــر بصحــة واقعــة القبــض عليــه مــن قبــل مكافحــة املخــدرات‬\n     ‫باجلبيــل بعــد قيامــه بالتوســط يف ترويــج قطعــة مــن احلشــيش املخــدر‬\n     ‫بلــغ وزنهــا (‪ )12.1‬إثنــا عشــر جرامــا وواحــد مــن العشــرة مــن اجلــرام‬\n     ‫مقابــل مبلــغ قــدره (‪ )500‬خمســمائة ريــا ًال وكان قصــده مــن ذلــك هــو‬\n     ‫الكســب املــادي كمــا أقــر أنــه مت تنســيق عمليــة التوســط بالترويــج عــن‬\n     ‫طريــق جوالــه رقــم (‪ )......‬وأنــه ضبــط معــه قطعــة مــن احلشــيش املخــدر‬\n     ‫بلــغ وزنهــا (‪ )1.5‬جــرام واحــد ونصــف اجلــرام مــن نفــس القطعــة املروجــة‬\n     ‫ال تعــود لــه وأنــه يتعاطــى احلشــيش املخــدر منــذ ســنة ويحصــل عليــه مــن‬\n     ‫عــدة أشــخاص وأنــه هــذه أول مــرة يقــوم بالتوســط بترويــج احلشــيش‬\n     ‫املخــدر وانتهــى التحقيــق إلــى توجيــه االتهــام لــأول () بترويــج قطعــة مــن‬\n     ‫احلشــيش املخــدر بلــغ وزنهــا (‪ )12.1‬إثنــا عشــر جراما وواحد من العشــرة‬\n     ‫مــن اجلــرام بقصــد الكســب املــادي وحيــازة عــدد (‪ )8‬ثمــان قطــع مــن‬\n     ‫احلشــيش املخــدر بلــغ مجمــوع وزنهــا (‪ )485‬أربعمائــة وخمســة وثمانــن‬\n     ‫جرام ـ ًا وعــدد (‪ )41‬إحــدى وأربعــن حبــة مــن حبــوب الــروش احملظــورة‬\n     ‫وعــدد (‪ )3‬ثالثــة ســجائر مخلوطــة باحلشــيش املخــدر بلــغ مجمــوع وزنهــا‬\n     ‫(‪ )4‬أربــع جرامــات بقصــد التعاطــي وتعاطيــه للحشــيش املخــدر وحبــوب‬\n\n\n‫‪33‬‬\n\f‫الــروش احملظــورة وتوســط الثانــي (‪ )......‬بترويــج قطعــة مــن احلشــيش‬\n‫املخــدر بلــغ وزنهــا (‪ )12.1‬إثنــا عشــر جرام ـ ًا وواحــد مــن العشــرة مــن‬\n‫اجلــرام بقصــد الكســب املــادي وحيازتــه لقطعــة مــن احلشــيش املخــدر‬\n‫بلــغ وزنهــا (‪ )1.5‬جــرام واحــد ونصــف اجلــرام بقصــد التعاطــي وتعاطيــه‬\n‫لــذات النــوع ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1:‬إقرارهمــا املصدقــن‬\n‫شــرع ًا املنــوه عنهمــا واملدونــن علــى الصفحتــن رقــم (‪ )13 ، 9‬مــن دفتــر‬\n‫التحقيــق املرفــق علــى اللفــة رقــم (‪ -2)9‬محضــر القبــض والتفتيــش املنوه‬\n‫عنــه واملــدون علــى الصفحتــن رقــم (‪ )3 ، 2‬مــن دفتــر التحقيــق املرفــق‬\n‫علــى اللفــة رقــم (‪ -3)9‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق‬\n‫علــى اللفــة رقــم (‪ )20‬وبالبحــث عمــا إذا كان لهمــا ســوابق جنائيــة عثــر‬\n‫لــأول (‪ )......‬علــى ســابقة واحــدة حيــازة واســتعمال املخــدرات اقترنــت‬\n‫بقيــادة ســيارة وهــو بحالــة ســكر بينمــا عثــر للثانــي (‪ )......‬علــى ســابقة‬\n‫واحــدة محاولــة لــواط وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا ‪ -‬وهمــا‬\n‫بكامــل أهليتهمــا املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظام ـ ًا أطلــب مــا يلــي ‪ -:‬أو ًال ‪ :‬أطلــب إثبــات مــا أســند إليهمــا وفق ـ ًا‬\n‫للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة واحلكــم عليهمــا باآلتــي ‪ -1-:‬بعقوبــة الســجن واجللــد والغرامــة‬\n‫املنصــوص عليهــا يف الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن النظــام‬\n‫املشــار إليــه‪ -2‬منعهمــا مــن الســفر إلــى خــارج اململكــة وفقـ ًا للفقــرة رقــم‬\n‫(‪ )1‬مــن املــادة رقــم (‪ )56‬مــن النظــام املشــار إليــه ثانيـ ًا ‪ :‬احلكــم عليهمــا‬\n‫باملقتضــى الشــرعي لقــاء إقرارهمــا بتعاطــي مــادة احلشــيش املخــدر ثالثـ ًا‬\n‫‪ :‬مصــادرة جهــاز جــوال الوســيط الــذي متــت عــن طريقــه عمليــة الترويــج‬\n‫ذو الرقــم املصنعــي رقــم () ‪ ،‬مــع مراعــاة إعمــال املــادة رقــم (‪)62‬‬\n\n\n                                                                                         ‫‪34‬‬\n\f     ‫مــن نظــام املخــدرات واملؤثــرات العقليــة رابع ـ ًا ‪ :‬احلكــم عليــه بإعــادة‬\n     ‫املبلــغ املرقــم اســتناد ًا لتعميــم صاحــب الســمو امللكــي النائــب الثانــي‬\n     ‫لرئيــس مجلــس الــوزراء وزيــر الداخليــة (‪ )15980/4/5/1‬وتاريــخ ‪-22‬‬\n     ‫‪1428/10/23‬ه ـ وبعــرض دعــوى املدعــي العــام علــى املدعــى عليه األول‬\n     ‫أجــاب قائــا مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح وحبــوب‬\n     ‫الــروش التــي بحوزتــي موصوفــة لــي بوصفــة طبيــة حيــث أننــي أعانــي‬\n     ‫مــن اضطرابــات نفســية وقــد صرفــت لــي مــن املستشــفى وبعــرض دعــوى‬\n     ‫املدعــي العــام علــى املدعــى عليــه الثانــي ‪ ......‬أجــاب قائــا مــا ذكــره‬\n     ‫املدعــي العــام يف دعــواه كلــه صحيــح جملــة وتفصيــا ثــم جــرى ســؤال‬\n     ‫املدعــى عليــه األول ‪ ......‬هــل لديــه بينــة علــى مــا ذكــر فقــال نعــم أطلــب‬\n     ‫مهلــة إلحضارهــا لــذا رفعــت اجللســة وبــاهلل التوفيــق والصــاة والســام‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعني حــرر يف ‪1433/03/13‬هـ‬\n                                                                                        ‫‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n     ‫فلــدي أنــا القاضــي يف احملكمــة العامــة باجلبيــل ويف يــوم الســبت‬\n     ‫املوافق‪1433/3/19‬ه ـ افتتحــت اجللســة الســاعة العاشــرة والنصــف‬\n     ‫وفيهــا حضــر املدعــي العــام واملدعــى عليــه األول‪ .... /‬واملدعــى عليــه‬\n     ‫الثانــي‪ ..... /‬ثــم جــرى ســؤال املدعــى عليــه األول‪ ..... /‬عــن البينــة التــي‬\n     ‫وعــد بإحضارهــا فأبــرز صــورة ورقــة مــن مطبوعــات مستشــفيات ‪....‬‬\n     ‫مكتوبــة باللغــة اإلجنليزيــة كمــا أبــرز صــورة مــن مطبوعــات مكتــب‬\n     ‫‪ ....‬للترجمــة وذكــر بأنهــا ترجمــة للصــورة األولــى وباإلطــاع عليهــا‬\n     ‫وجــد هــذا نصها(تقريــر طبــي اســم املريــض‪ /‬العمر‪26/‬ســنة وتاريــخ‬\n     ‫اخــر زيــارة‪2011/8/16 /‬م اســم الطبيــب‪/...... /‬قســم الصحــة النفســية‬\n\n\n‫‪35‬‬\n\f‫حضــر املريــض للعيــادة ألول مــرة يف يــوم ‪2006/3/8‬م يشــكو مــن‬\n‫اكتئــاب اندفــاع انزعــاج يف النــوم وضغوطــات عاطفيــة مت تشــخيصه‬\n‫بواســطة طبيبــه املعالــج كحالــة اضطــراب وأعطــى حبــوب تروكســال‬\n‫‪50‬ملجــم انديــب ‪25‬ملجــم ريفوتريــل ‪2‬ملمجــم ثالثــة مــرات يف اليــوم‬\n‫ظــل املريــض يتابــع يف العيــادة بصــورة منتظمــة وكانــت حالتــه مســتقرة‬\n‫ولكنــه مــن وقــت آلخــر يشــكو مــن حالــة اكتئــاب توتــر وتهيــج ألقــل‬\n‫األســباب األمــر الــذي تطلــب إجــراء بعــض التعديــات يف طريقــة العــاج‬\n‫وآخــر زيــارة كانــت يف يــوم ‪2007/10/29‬م وأعطــي عــاج ريفوتريــل‬\n‫‪1‬ملجــم ثالثــة مــرات يف اليــوم ســتابلون ‪21.5‬ملجــم ثالثــة مــرات يف اليوم‬\n‫وتروكســال ‪50‬ملجــم يف الليــل ومنــذ ذلــك الوقــت لــم يحضــر املريــض‬\n‫للمتابعــة حــرر هــذا التقريــر بنــاء علــى طلــب املريــض د‪ ...... /‬استشــاري‬\n‫نفســي د‪ ....../‬استشــاري مناظيــر وجهــاز هضمــي املديــر الطبــي اخلتــم)‬\n‫وبعــرض الترجمــة علــى املدعــي العــام قــال أن مــا مت صرفــه مــن عــاج‬\n‫للمدعــى عليــه األول ‪ ...... /‬ليســت هــي حبــوب الــروش حســب التقريــر‬\n‫الكيمــاوي املرفــق باملعاملــة واملتهــم املدعــى عليــه بحيازتهــا وأطلــب‬\n‫الكتابــة ملكافحــة املخــدرات باجلبيــل للتأكــد مــن ذلــك ثــم جــرى‬\n‫ســؤال املدعــى عليــه األول‪ ...... /‬عــن املبلــغ احلكومــي املســتخدم يف‬\n‫عمليــة الشــراء وهــل قــام بإســتالمه فقــال نعــم اســتلمت مبلــغ وقــدره‬\n‫أربعمائــة ريــال مــن الوســيط ‪ 000‬وبعــد القبــض علــي ســلمت مكافحــة‬\n‫املخــدرات باجلبيــل مبلــغ وقــدره خمســمائة ريــال ثــم جــرى ســؤاله هــل‬\n‫لديــه بينــة علــى أنــه قــام بتســليم مكافحــة املخــدرات املبلــغ املســتخدم‬\n‫يف عمليــة الشــراء فقــال ليــس لــدي بينــة وللكتابــة ملكافحــة املخــدرات‬\n‫باجلبيــل للتأكــد مــن نوعيــة العــاج الــذي ذكــر املدعــى عليــه أنــه‬\n\n\n                                                                                   ‫‪36‬‬\n\f     ‫يســتخدمه رفعــت اجللســة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                  ‫وعلــى آلــه وصحبــه أجمعــن ‪ .‬حــرر بتاريــخ ‪1433/3/19‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n     ‫أنــا ‪ 0000‬القاضــي يف احملكمــة العامــة باجلبيــل ويف يــوم األحــد‬\n     ‫املوافــق‪ 1433/07/27‬ه ـ افتتحــت اجللســة الســاعة الثانيــة عشــر وفيهــا‬\n     ‫حضــر املدعــي العــام ‪ 000‬واملدعــى عليهمــا األول ‪ 000‬والثانــي ‪0000‬‬\n     ‫وكانــت قــد جــرت الكتابــة منــا ملديــر مكافحــة املخــدرات باجلبيــل‬\n     ‫برقــم (‪ ).....‬وتاريــخ ‪1433/04/20‬ه ـ املتضمــن طلــب اإلفــادة عــن‬\n     ‫التقريــر الطبــي الــذي أبــرزه املدعــى عليــه األول ‪ 000‬فوردنــا جوابــه‬\n     ‫رقــم (‪ ).....‬وتاريــخ ‪1433/05/16‬ه ـ واملقيــد باحملكمــة لدينــا برقــم‬\n     ‫(‪ ).....‬وتاريــخ ‪1433/05/18‬ه ـ واملرفــق بــه إفــادة مديــر إدارة املركــز‬\n     ‫اإلقليمــي ملراقبــة الســموم بصحــة الشــرقية رقــم (‪ 1043‬خ ش ‪)41/31 /‬‬\n     ‫وتاريــخ ‪1433/05/10‬ه ـ وباإلطــاع عليــه وجــد هــذا نصــه إشــارة إلــى‬\n     ‫خطابكــم رقــم (س ب) وتاريــخ ‪1433/05/03‬ه ـ املرســل بالفاكــس‬\n     ‫الــوراد لدينــا بتاريــخ ‪1433/05/10‬ه ـ واملبنــي علــى خطــاب ســعادة‬\n     ‫رئيــس محكمــة اجلبيــل رقــم (‪ ).....‬وتاريــخ ‪1433/04/20‬ه ـ املتضمــن‬\n     ‫طلبهــم باإلفــادة عــن عــاج ( ريفوتريــل ) وهــل هــو مــن أنــواع حبــوب‬\n     ‫الــروش احملظــورة أو احلبــوب املخــدرة أو احلبــوب احملظــورة االخــرى‬\n     ‫عليــه نفيدكــم بــأن أقــراص الريفوتريــل (‪ )Rivotril‬هــو االســم‬\n     ‫التجــاري لألقــراص التــي حتمــل العالمــة (روش ‪)Roche2( )2‬‬\n     ‫واســمها العلمــي هــو الكلونازيبــام (‪ )Clonazepam‬وهــي مــن‬\n     ‫ضمــن العقاقيــر التــي تســتخدم كمضــادات للصــرع واخلاضعــة للرقابــة‬\n     ‫التــي ال تصــرف إال بوصفــه طبيــة وتعتبــر مــن مجموعــة البنزوديازبــن‬\n\n\n‫‪37‬‬\n\f‫(‪ )Benzodiazepine‬وهــي مدرجــة يف اجلــدول الثانــي فئــة (د) مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املوافــق عليــه مبوجــب‬\n‫املرســوم امللكــي رقــم (م‪ )39 /‬وتاريــخ ‪1426/07/09‬ه ـ وتعميــم ســمو‬\n‫وزيــر الداخليــة رقــم () وتاريــخ ‪1426/10/25‬ه ـ وتعميــم ســمو وزيــر‬\n‫الداخليــة رقــم () وتاريــخ ‪1426/10/25‬ه ـ ثــم جــرى ســؤال املدعــى‬\n‫عليهمــا عــن املبلــغ احلكومــي فقــال املدعــى عليــه األول ‪ 0000‬أنــه اســتلم‬\n‫منــه (‪ )400‬أربعمائــة ريــال وقــال املدعــى عليــه الثانــي ‪ 000‬أنــه اســتلم‬\n‫منــه (‪ )100‬مائــة ريــال ثــم جــرى اإلطــاع علــى أوراق املعاملــة فوجــد علــى‬\n‫لفــة رقــم (‪ )20‬التقريــر الكيمــاوي الشــرعي رقــم (ك ش) املتضمــن‬\n‫ايجابيــة العينــات املأخــوذة مــن املضبوطــات مــع املدعــى عليهمــا ملــادة‬\n‫احلشــيش املخــدر وعقــار (الكلونازيبــام ) الــروش احملظــور كمــا وجــد‬\n‫علــى لفــة رقــم (‪ )14.16‬صحيفــة ســوابق املدعــى عليهمــا وباإلطــاع‬\n‫عليهــا وجــدت مطابقــة ملــا ذكــره املدعــي العــام يف دعــواه وبعرضهــا‬\n‫علــى املدعــى عليهمــا صادقــا عليهــا فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وإلقــرار املدعــى عليهمــا بدعــوى املدعــي العــام ولكــون مــا‬\n‫أقــدم عليــه املدعــى عليهمــا فعــل محــرم شــرعا ولقولــه صلــى اهلل عليــه‬\n‫وســلم (( كل مســكر حــرام )) وقولــه (( مــن شــرب اخلمــر فاجلــدوه‬\n‫)) رواهمــا ابــو داود وأحمــد وملــا جــاء يف التقريــر الطبــي الــذي أبــرزه‬\n‫املدعــى عليــه األول املتضمــن أن حيازتــه حلبــوب الــروش كان مبوجــب‬\n‫وصفــة طبيــة وملــا جــاء يف إفــادة مديــر إدارة املركــز اإلقليمــي ملراقبــة‬\n‫الســموم بصحــة الشــرقية وبنــاء علــى املــادة رقــم (‪ )38‬ورقــم (‪ )41‬ورقــم‬\n‫(‪ )53‬ورقــم (‪ )56‬ورقــم (‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة فقــد ثبــت لــدي إدانــه املدعــى عليــه األول بترويــج قطعــة مــن‬\n\n\n                                                                                    ‫‪38‬‬\n\f     ‫احلشــيش املخــدر بلــغ وزنهــا (‪ )12.1‬اثنــا عشــر جرامــا وواحــد بالعشــرة‬\n     ‫مــن اجلــرام بقصــد الكســب املــادي وحيازتــه لعــدد (‪ )8‬ثمــان قطــع مــن‬\n     ‫احلشــيش املخــدر بلــغ وزنهــا (‪ )485‬أربعمائــة وخمســة وثمانــن جرامــا‬\n     ‫وعــدد (‪ )3‬ثالثــة ســجائر مخلوطــة باحلشــيش املخــدر بلــغ وزنهــاه (‪)4‬‬\n     ‫أربــع جرامــات لقصــد التعاطــي وتعاطــي احلشــيش املخــدر وحيازتــه لعدد‬\n     ‫(‪ )41‬واحــد واربعــن حبــة مــن حبــوب الــروش لقصــد االســتعمال الطبــي‬\n     ‫والعــاج كمــا ثبــت لــدي إدانــة املدعــى عليــه الثانــي ‪ 000‬بالتوســط يف‬\n     ‫ترويــج قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )12.1‬إثنــا عشــر جرامــا‬\n     ‫وواحــد مــن العشــرة مــن اجلــرام بقصــد الكســب املــادي وحيازتــه لقطعــة‬\n     ‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )1.5‬جــرام وواحــد بالعشــرة مــن اجلــرام‬\n     ‫بقصــد التعاطــي وتعاطيــه للحشــيش املخــدر وحكمــت علــى املدعــى‬\n     ‫عليــه األول مبــا يلــي ‪ :‬أوال ‪ /‬يجلــد (‪ )80‬ثمانــن جلــدة حــد املســكر‬\n     ‫ثانيــا ‪ /‬يســجن ملــدة خمــس ســنوات ثالثــا‪ /‬يجلــد ثالثمائــة جلــده مفرقــة‬\n     ‫علــى ســت دفعــات متســاوية بــن كل دفعــة وأخــرى خمســة عشــر يومــا‬\n     ‫رابعــا ‪ /‬مينــع مــن الســفر خــارج اململكــة ملــدة خمــس أعــوام بعــد تنفيــذ‬\n     ‫عقوبة الســجن خامســا ‪ /‬إعادة املبلغ احلكومي وقدره (‪ )400‬أربعمائة‬\n     ‫ريــال ويــودع يف حســاب اإلدارة العامــة ملكافحــة املخــدرات وحكمــت‬\n     ‫علــى املدعــى عليــه الثانــي مبــا يلــي ‪ :‬أوال ‪ /‬يجلــد (‪ )80‬ثمانــن جلــده‬\n     ‫حــد املســكر ثانيــا ‪ /‬يســجن ملــدة ثــاث ســنوات ثالثــا ‪ /‬يجلــد مئتــي‬\n     ‫جلــده مفرقــة علــى أربــع دفعــات متســاوية بــن كل دفعــة وأخــرى خمســة‬\n     ‫عشــر يومــا رابعــا ‪ /‬مينــع مــن الســفر خــارج اململكــة ملــدة ثــاث ســنوات‬\n     ‫بعــد تنفيــذ عقوبــة الســجن خامســا ‪ /‬مصــادرة جهــاز الهاتــف اجلــوال‬\n     ‫املذكــور رقمــه املصنعــي يف دعــوى املدعــي العــام سادســا ‪ /‬إعــادة املبلــغ‬\n\n\n‫‪39‬‬\n\f‫احلكومــي وقــدره (‪ )100‬مائــة ريــال ويــودع يف حســاب اإلدارة العامــة‬\n‫ملكافحــة املخــدرات وبعــرض احلكــم علــى الطرفــن قــررا املدعــى‬\n‫عليهمــا القناعــة باحلكــم واملدعــي العــام عدمهــا وطلــب رفــع املعاملــة‬\n‫حملكمــة اإلســتئناف بــدون الئحــة إعتراضيــة واكتفــى مبــا قــدم لــذا‬\n‫قــررت رفــع القضيــة حملكمــة اإلســتئناف باملنطقــة الشــرقية وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                               ‫حــرر يف ‪ 1433/07/27‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n‫أنــا ‪ 0000‬القاضــي يف احملكمــة العامــة باجلبيــل ويف يــوم األحــد‬\n‫املوافــق ‪ 1434 / 03 / 22‬ه ـ افتتحــت اجللســة الســاعة الثامنــة والنصــف‬\n‫وحيــث كنــت مشــارك بــدورة تدريبيــة مبدينــة الريــاض مــن تاريــخ‬\n‫‪ 1433/12/18‬إلــى ‪1434/03/18‬ه ـ وفيهــا حضــر املدعــي العــام‬\n‫بدائــرة التحقيــق واإلدعــاء العــام باجلبيــل ‪ 0000‬واملدعــى عليهمــا األول‬\n‫‪ 0000‬واملدعــى عليــه الثانــي ‪ 0000‬وكانــت قــد عــادت املعاملــة مــن‬\n‫محكمــة االســتئناف باملنطقــة الشــرقية باخلطــاب رقــم (‪ )....‬وتاريــخ‬\n‫‪ 1433/11/13‬ه ـ املرفــق بــه القــرار رقــم (‪ )....‬وتاريــخ ‪1433/10/ 32‬‬\n‫ه ـ املتضمــن انــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ‬\n‫أوال ‪ /‬أن فضيلتــه لــم يقــرر بحقهمــا العقوبــة املاليــة املنصــوص عليهــا يف‬\n‫مــا أثبتــه بحــق املدعــى عليهمــا ثانيــا ‪ /‬يوجــد نقــص يف دعــوى املدعــي‬\n‫العــام يف القــرار عمــا يف صــورة الضبــط عليــه أجيــب أمــا مــا متعلــق‬\n‫باملالحظــة األولــى فقــد حكمــت علــى كل واحــد مــن املدعــى عليهمــا‬\n‫بدفــع غرامــة قدرهــا (‪ )1000‬ألــف ريــال تــودع يف حســاب اإلدارة العامــة‬\n‫ملكافحــة املخــدرات امــا مــا يتعلــق باملالحظــة الثانيــة فقــد مت إضافــة‬\n\n\n                                                                                   ‫‪40‬‬\n\f     ‫النقــص يف القــرار وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫آلــه وصحبــه وســلم حــرر يف ‪ 1434 / 03 /22‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة اجلبيــل برقــم وتاريــخ‬\n     ‫‪1434/3/23‬ه ـ املقيــدة لــدى احملكمــة برقــم وتاريــخ ‪1434/3/28‬ه ـ‬\n     ‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‬\n     ‫‪ 0000‬املســجل برقــم وتاريــخ ‪1433/7/28‬ه ـ اخلــاص بدعوى‪/‬املدعــى‬\n     ‫العــام ضــد‪ 0000 -2 0000 -1/‬يف قضيــة مخــدرات وقــد تضمــن القرار‬\n     ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة‬\n     ‫ضبطــه وباإلطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار‬\n     ‫وصــورة ضبطــه بنــاء علــى قرارنــا رقــم ج‪/1‬ب يف ‪1433/10/23‬هـ قررنا‬\n     ‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل‬\n               ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/4/7‬ه ـ ‪.‬‬\n\n\n\n\n‫‪41‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":28,"source_page_end":41,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1ac40de55bef872d2ae00414d6a77c152b78be5da68a45edc8287ce305a4f9ee","normalized_text_hash":"61d848dc9350403a807ab622d9093cbb522c9a0f59cebf815538796d8ab236c3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p28-33358951"},{"id":"de1cf89e-6594-5289-990b-0be4a1910366","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -حيازة احلشيش املخدر- بقصد التعاطي -تعاطي احلبوب احملظورة -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد والغرامة واإلبعاد - مصادرة اجلوال والشريحة املستخدمان يف اجلرمية.","document_number":"33398313","case_number":"33476118","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبكة املكرمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/28","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -حيازة احلشيش املخدر- بقصد التعاطي -تعاطي احلبوب احملظورة -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد والغرامة واإلبعاد - مصادرة اجلوال والشريحة املستخدمان يف اجلرمية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33398313 :‬تاريخه ‪1433/8/28:‬هـ‬\n                  ‫رقم الدعوى ‪33476118 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3422362‬تاريخه ‪1434/1/25 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬حيــازة احلشــيش املخــدر‪-‬‬\n‫بقصــد التعاطــي ‪ -‬تعاطــي احلبــوب احملظــورة ‪ -‬إقامــة حد املســكر على‬\n‫متعاطــي احلشــيش ‪ -‬التعزيــر بالســجن واجللــد والغرامــة واإلبعــاد ‪-‬‬\n                 ‫مصــادرة اجلــوال والشــريحة املســتخدمان يف اجلرميــة‪.‬‬\n\n\n\n\n             ‫‪ -1‬املادة ‪ 38‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n             ‫‪ -2‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n‫‪ -3‬الفقــرة ‪ 2‬مــن املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                 ‫العقليــة‬\n              ‫‪ -4‬تعميم سمو وزير الداخلية رقم ‪ 9798‬يف ‪1428/2/1‬هـ‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه ‪ ،‬مقيــم يحمــل بطاقــة بديلــة‬\n‫بتوجيــه االتهــام لــه بترويــج احلبــوب احملظــورة ‪ ،‬وحيــازة احلشــيش بقصــد‬\n‫التعاطــي ‪ ،‬وتعاطيــه للحشــيش وللحبــوب ‪ ،‬وطلــب املدعــي العــام إثبــات‬\n‫مــا أســند إليــه واحلكــم عليــه بالســجن واجللــد والغرامــة وإبعــاده خــارج‬\n‫اململكــة بعــد انتهــاء عقوبتــه وعــدم الســماح لــه بالعــودة إليهــا ومنعــه مــن‬\n‫دخولهــا ومصــادرة اجلهــاز اجلــوال وإلغــاء اخلدمــة عــن شــريحته املســتخدم‬\n\n                                                                                        ‫‪42‬‬\n\f     ‫يف اجلرميــة وعــدم صرفهــا مــرة أخــرى وإلــزام املدعــى عليــه بإعــادة املبلــغ‬\n     ‫املرقــم وإقامــة حــد املســكر عليــه ‪ ،‬مت القبــض علــى املدعــى عليــه‬\n     ‫بعــد إخباريــة مفادهــا أن املدعــى عليــه يقــوم ببيــع القــات ويتواجــد علــى‬\n     ‫هاتــف جوالــه ومت التنســيق مــع أحــد املصــادر الســرية لإلطاحــة بــه ‪،‬‬\n     ‫وســلم للمصــدر مبلــغ مالــي مرقــم ‪ ،‬ومت االتفــاق مــع املدعــى عليــه مــن‬\n     ‫قبــل املصــدر وحضــر املدعــى عليــه وركــب مــع املصــدر يف ســيارته ومت‬\n     ‫القبــض عليــه ووجــد معــه ثــاث حبــات أثبتــت إيجابيــة عيناتهــا ملــادة‬\n     ‫احلشــيش املخــدر وحبــوب اإلمفيتامــن املخــدر ‪ ،‬أقــر املدعــى عليــه‬\n     ‫بالدعــوى ‪ ،‬ثبــوت إدانــة املدعــى عليــه ‪ ،‬بنــاء علــى مــا تقــدم حكمــت‬\n     ‫احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة واإلبعــاد‬\n     ‫ومصــادرة اجلــوال والشــريحة املســتخدمان يف اجلرميــة وإقامــة حــد‬\n     ‫وصــدق احلكــم مــن محكمــة‬       ‫املســكر وإلزامــه بإعــادة املبلــغ املرقــم ‪ُ ،‬‬\n                                                                             ‫االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33476118‬‬\n     ‫وتاريــخ ‪ 1433/07/20‬ه ـ املقيــدة باحملكمــة برقــم ‪331355616‬‬\n     ‫وتاريــخ ‪ 1433/07/19‬ه ـ ففــي يــوم اإلثنــن املوافــق ‪1433/08/05‬‬\n     ‫ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 15‬صباحــا املتعلقــة بدعــوى املدعــي‬\n     ‫العــام ‪ ..........‬بالســجل املدنــي رقــم ‪ 1038368138‬مبوجــب التكليــف‬\n     ‫رقــم ه ـ م‪ 368/6/2‬وتاريــخ ‪1430/12/29‬ه ـ ضــد املدعــى عليــه‪......:‬‬\n     ‫(‪ )28‬عامـ ًا صومالــي اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪............‬‬\n\n‫‪43‬‬\n\f‫‪ )............/‬وتاريــخ ‪1433/6/14‬ه ـ صــادرة مــن مكافحــة املخــدرات‬\n‫مبحافظــة جــدة عاطــل يقيــم يف البــاد بطريقــة غيــر نظاميــة محصــن‬\n‫متعلــم موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر متديــد‬\n‫التوقيــف رقــم (ه ـ م‪ )40489/5/2‬يف ‪1433/6/15‬ه ـ اســتناد ًا للقــرار‬\n‫الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة‬\n‫ا يف دعــواه إنــه بتاريــخ‬ ‫(‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة قائ ـ ً‬\n‫‪1433/6/14‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل مكافحــة‬\n‫ـاء علــى إخباريــة أحــد املتهمــن املقبــوض‬  ‫املخــدرات مبحافظــة جــدة بنـ ً‬\n‫عليهــم يف قضيــة مخــدرات أن املدعــى عليــه يتواجــد علــى هاتــف جــوال‬\n‫رقــم (‪ ).......‬يقــوم ببيــع القــات وكذلــك احلبــوب وعلــى مســمع مــن أفــراد‬\n‫الفرقــة مت متكينــه مــن االتصــال علــى الرقــم املــدون باإلخباريــة فــرد‬\n‫عليــه املدعــى عليــه وطلــب منــه حزمتــن مــن القــات احملظــور فوافــق‬\n‫املدعــى عليــه فطلــب مــن املتعــاون مبلــغ (‪ )600‬ســتمائة ريــال علــى أن‬\n‫يقابلــه يف شــارع ‪ ......‬بحــي (‪ )........‬وذكــر املتعــاون للمدعــى عليــه أنــه‬\n‫ســوف يرســل لــه شــخص ًا مــن طرفــه لشــراء الكميــة ‪ ،‬فتــم اختيــار‬\n‫أحــد املصــادر الســرية لشــراء الكميــة وتزويــده مببلــغ (‪ )600‬ســتمائة‬\n‫ريــال ومت إفهامــه أن املدعــى عليــه إذا أصــر علــى اســتالم املبلــغ أن‬\n‫ال يســلمه املبلــغ لكــي ال يفقــد املبلــغ ويطلــب منــه كميــة مــن احلبــوب‬\n‫مببلــغ مناســب وإن طلــب اســتالم املبلــغ يســلمه عندهــا فتــم االنتقــال‬\n‫للموقــع ومت االتصــال علــى املدعــى عليــه مــن قبــل املصــدر وأفهمــه أنــه‬\n‫مــن طــرف املتهــم ويريــد اســتالم الكميــة علــى مســمع مــن أفــراد الفرقــة‬\n‫ويف متــام الســاعة الثانيــة والنصــف ظهــر ًا مــن نفــس اليــوم حضــر املدعــى‬\n‫عليــه وركــب مــع املصــدر وتوجهــا إلــى داخــل احلــي ثــم مت التواصــل مــع‬\n\n\n                                                                                     ‫‪44‬‬\n\f     ‫املصــدر فذكــر أن املدعــى عليــه أصــر علــى اســتالم املبلــغ لذلــك طلــب‬\n     ‫كميــة مــن احلبــوب احملظــورة مببلــغ (‪ )100‬مائــة ريــال وأنه ســلم له املبلغ‬\n     ‫ونــزل إلحضــار الكميــة وبعــد عشــر دقائــق عــاد املدعــى عليــه وركــب‬\n     ‫مــع املصــدر فتــم القبــض عليــه وبتفتيشــه عثــر معــه علــى محفظــة ســوداء‬\n     ‫اللون بداخلها قطعة ســوداء اللون تزن (‪ )0.5‬خمســة أعشــار اجلرام ومت‬\n     ‫ضبــط هاتفــه اجلــوال الــذي يحمــل نفــس الرقــم املــدون باإلخباريــة وعليــه‬\n     ‫ســلم املصــدر الكميــة املشــتراه لقائــد الفرقــة عــدد (‪ )3‬ثــاث حبــات‬\n     ‫بيجيــة اللــون وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪/2175‬ك‬\n     ‫ش م) لعــام ‪1433‬ه ـ إيجابيــة املضبوطــة ملــادة احلشــيش املخــدر واحتوائها‬\n     ‫علــى املــادة الفعالــة لــه مــن احلبــوب الثــاث املضبوطــة ملــادة االمفيتامــن‬\n     ‫املؤثــرة عقلي ـ ًا واملدرجــة باجلدولــن رقــم (‪ )1،2‬فئــة (أ‪،‬ب) امللحقــن‬\n                                ‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪:‬‬\n     ‫وباســتجواب املدعــى عليــه ‪ ...... /‬أقــر ببيــع (‪ )3‬ثــاث حبــات محظــورة‬\n     ‫وســلمها للمتعــاون وســلم املبلــغ للمــروج الــذي حصــل علــى احلبــوب منــه‪،‬‬\n     ‫وأن مــا ضبــط معــه مــن حشــيش مخــدر يعــود لــه بقصــد التعاطــي وأنــه‬\n     ‫يتعاطــى احلشــيش املخــدر واحلبــوب احملظورة ســابقا وقد انتهــى التحقيق‬\n     ‫إلــى اتهــام املدعــى عليــه‪ ........ /‬بترويــج (‪ )3‬ثــاث حبــات حتتــوي علــى‬\n     ‫مــادة االمفيتامــن املؤثــرة عقليـ ًا عــن طريــق البيــع بقصد االجتــار وحيازة‬\n     ‫(‪ )0.5‬خمســة أعشــار اجلــرام مــن مــادة احلشــيش املخــدر بقصــد التعاطــي‬\n     ‫وتعاطيــه منهــا ولنوعهــا وللحبــوب احملظــورة ســابق ًا ‪ ،‬اســتناد ًا للفقــرة‬\n     ‫(‪ )2‬مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليـ ًة‬\n     ‫‪ ،‬وذلــك لألدلــة والقرائــن التاليــة ‪-1 :‬مــا ورد يف أقوالــه املدونــة بدفتــر‬\n     ‫التحقيق صفحة رقم (‪ )3‬املرفق رقم ( ‪ -2 ) 15‬ما ورد مبحضر القبض‬\n\n\n‫‪45‬‬\n\f‫والضبــط والتفتيــش املنــوه عنــه املرفــق لفــة رقــم (‪ )1‬صفحــة رقــم (‪)11‬‬\n‫‪ -3‬مــا ورد يف التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة (‪19‬‬\n‫) وباإلطــاع علــى ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة وحيــث إن‬\n‫مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا مــن‬\n‫األفعــال احملرمــة شــرع ًا واملجرمــة نظامـ ًا طبقـ ًا للمــادة الثالثــة مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n‫رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬واملعاقــب عليهــا اســتناد ًا للمــادة‬\n‫(‪ )41،38‬مع مراعاة ما ورد باملادة (‪ )62‬من ذات النظام ‪ ،‬أطلب إثبات‬\n‫مــا أســند إليــه واحلكــم عليــه بالعقوبــات األصليــة والتكميليــة التاليــة ‪:‬ـ‬\n‫‪ -1‬بالســجن واجللــد والغرامــة لقــاء مــا أســند إليه اســتناد ًا للفقــرة (‪ )1‬مع‬\n‫تشــديد العقوبــة عليــه وفقـ ًا للحالــة (ج) مــن الفقــرة (‪ )2‬مــن املــادة (‪)38‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه وتعميــم‬\n‫صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪2/1346/4/5/1‬ش)‬\n‫وتاريــخ ‪1427/2/8‬ه ـ لقــاء بيــع احلبــوب ‪ -2‬إبعــاده خلــارج اململكــة بعــد‬\n‫االنتهــاء مــن تنفيــذ عقوبتــه وعــدم الســماح لــه بالعــودة إليهــا ومنعــه مــن‬\n‫دخولهــا وفقــا للفقــرة (‪ )2‬مــن املــادة (‪ )56‬مــن نظــام املخــدرات املشــار‬\n‫إليــه‪ -3‬مصــادرة جهــاز الهاتــف اجلــوال مــن نــوع (‪ ).....‬ذي الرقــم املصنعي‬\n‫(‪ )............‬املســتخدم يف ارتــكاب اجلرميــة اســتناد ًا للفقــرة (‪ )1‬مــن املــادة‬\n‫(‪ )53‬مــن نظــام مكافحــة املخــدرات املشــار إليــه وإلغــاء اخلدمــة عــن‬\n‫الشــريحة وعــدم صرفهــا لســوء اســتخدامها اســتناد ًا لتعميــم صاحــب‬\n       ‫الســمو امللكــي وزيــر الداخليــة رقــم (‪ )9798‬يف ‪9‬ــ‪1428/2/10‬ه ـ‬\n‫‪ -4‬كمــا اطلــب إلزامــه بدفــع املبلــغ املرقــم املفقــود وقــدره (‪)100‬‬\n‫مائــة ريــال العائــد ملكافحــة املخــدرات مبحافظــة جــدة اســتناد ًا لتعميــم‬\n\n\n                                                                                          ‫‪46‬‬\n\f     ‫صاحــب الســمو املكــي وزيــر الداخليــة رقــم (‪ )65980/4/5/1‬وتاريــخ‬\n     ‫‪22‬ــ‪1428/12/23‬ه ـ هكــذا ادعــى املدعــي العــام أ‪ .‬ه ـ وبســؤال املدعى‬\n     ‫ا صحيــح بعــت ثــاث حبــات مــن حبــوب‬        ‫عليــه عــن الدعــوى أجــاب قائ ـ ً‬\n     ‫االمفيتامــن بقصــد االجتــار وحــزت خمســة أعشــار اجلــرام مــن احلشــيش‬\n     ‫املخــدر بقصــد التعاطــي وتعاطيــت مــن ذات الكميــة ولنوعهــا وللحبوب‬\n     ‫احملظــورة يف الســابق وجميــع مــا ذكــره املدعــي العــام صحيــح جملــة‬\n     ‫ا وإننــي تائــب ونــادم علــى مــا بــدر منــي أ‪ .‬ه ـ ثــم جــرى اإلطــاع‬\n                                                                              ‫وتفصيـ ً‬\n     ‫علــى أوراق املعاملــة ومــن ضمنهــا مــا ورد يف أقوالــه املدونــة بدفتــر‬\n     ‫التحقيــق ص‪ 3‬لفــة (‪ )15‬املطابقــة إلجابتــه ومــا ورد مبحضــر القبــض‬\n     ‫لفــة (‪ )1‬والــذي وجــد يتوافــق مــع مــا ذكــره املدعــي العــام ومــا ورد يف‬\n     ‫التقريــر الكيميائــي الشــرعي رقــم (‪/2175‬ك م ش) املتضمــن إيجابيــة‬\n     ‫ـاء علــى مــا تقــدم مــن الدعــوى‬‫العينــة للحشــيش واحلبــوب املخــدرة فبنـ ً‬\n     ‫واإلجابــة واإلقــرار فقــد ثبــت لــدي إدانــة املدعــى عليــه مبــا أســند لــه‬\n     ‫بالدعــوى ونظــر ًا لعــدم الســوابق ولقلــة الكميــة وملــا ظهــر مــن توبتــه‬\n     ‫وندمــه حكمــت عليــه مبــا يأتــي ‪ -1 :‬ســجنه ســنتني حتتســب منهــا مــدة‬\n     ‫اإليقــاف وجلــده خمســن جلــدة مكــررة علــى ســت دفعــات بــن كل‬\n     ‫دفعــة وأخــرى مــاال يقــل عــن أســبوع وغرامــة ماليــة قدرهــا ألفــا ريــال‬\n     ‫اســتناد ًا للمادتــن (‪ )60-38‬مــن نظــام مكافحــة املخــدرات ‪-2‬إبعــاده‬\n     ‫خلــارج اململكــة بعــد انتهــاء تنفيــذ محكوميتــه وفق ـ ًا للفقــرة (‪ )2‬مــن‬\n     ‫املــادة (‪ )56‬مــن النظــام املذكــور ‪ -3‬مصــادرة جهــاز الهاتــف اجلــوال مــن‬\n     ‫نــوع (‪ )....‬ذي الرقــم املصنعــي (‪ )............‬املســتخدم يف ارتــكاب اجلرميــة‬\n     ‫استناد ًا للفقرة (‪ )1‬من املادة (‪ )53‬من نظام مكافحة املخدرات املشار‬\n     ‫إليــه وإلغــاء اخلدمــة عــن الشــريحة وعــدم صرفهــا لســوء اســتخدامها‬\n\n\n‫‪47‬‬\n\f‫اســتناد ًا لتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪)9798‬‬\n‫يف ‪9‬ــ‪1428/2/10‬ه ـ ‪-4‬إلزامــه بإعــادة املبلــغ املرقــم املفقــود وقــدره‬\n‫مائــة ريــال العائــد ملكافحــة املخــدرات مبحافظــة جــدة اســتناد ًا لتعميــم‬\n‫صاحــب الســمو املكــي وزيــر الداخليــة رقــم (‪ )65980/4/5/1‬وتاريــخ‬\n‫‪22‬ــ‪1428/12/23‬ه ـ وبجميــع ذلــك حكمــت وبعرضــه عليــه قــرر‬\n‫قناعتــه باحلكــم فيمــا قــرر املدعــي العــام عــدم قناعتــه باحلكــم وطلــب‬\n‫رفعــه حملكمــة االســتئناف بالئحــة تقــدم خــال ثالثــن يومـ ًا مــن تاريــخ‬\n‫تســجيل القــرار وإال رفعــت بــدون الئحــة وصلــى اهلل وســلم علــى نبينــا‬\n             ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/08/05‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/01/06‬ه ـ ويف‬\n‫متــام الســاعة الثامنــة والربــع صباحـ ًا لــدي أنــا ‪ ........‬القاضــي باحملكمــة‬\n‫اجلزائيــة مبحافظــة جــدة افتتحــت اجللســة وعــادت إلينــا املعاملــة مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 33/1990174‬وتاريــخ‬\n‫‪1433/11/10‬ه ـ وبرفقهــا قــرار املالحظــة رقــم ‪ 33/442987‬وتاريــخ‬\n‫‪1433/11/1‬ه ـ املتضمــن أنــه بدراســة احلكــم وصورة ضبطــه والالئحة‬\n‫االعتراضيــة فقــد تقــرر إعــادة القضيــة لفضيلــة حاكمهــا ملالحظــة أن‬\n‫املدعــى عليــه اعتــرف بتعاطــي احلشــيش املخــدر ولــم نــر فضيلتــه أقــام‬\n‫عليــه احلــد مــع أن فضيلتــه لــم يطلــع علــى الئحــة اعتــراض املدعــي العــام‬\n‫وكمــا أن صــورة الضبــط املرفقــة غيــر واضحــة وتصعــب قراءتهــا‬\n‫ملالحظــة ذلــك واهلل املوفــق اه ـ فعليــه وبنــاء علــى مــا ذكــره أصحــاب‬\n‫الفضيلــة فإنــي قــد قــررت إقامــة حــد املســكر علــى املدعــى عليــه بجلــده‬\n‫ثمانــن جلــدة دفعــة واحــدة علنــا وبجميــع ذلــك حكمــت وبعــرض ذلــك‬\n‫علــى املدعــي العــام واملدعــى عليــه بقيــا علــى مــا قــرراه ســابقا كمــا‬\n\n\n                                                                                       ‫‪48‬‬\n\f     ‫إنــي اطلعــت علــى الئحــة املدعــي العــام ولــم أجــد بهــا مــا يؤثــر علــى مــا‬\n     ‫حكمــت بــه وعليــه جــرى التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                   ‫آلــه وصحبــه وســلم حــرر يف ‪1434/01/06‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n     ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف‬\n     ‫يف منطقــة مكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة املســاعد مبحافظــة جــدة رقــم‬\n     ‫‪ 331990174‬وتاريــخ ‪1434/1/18‬ه ـ املرفــق بهــا القــرار الصــادر‬\n     ‫مــن فضيلــة الشــيخ‪ .......... /‬القاضــي باحملكمــة اجلزائيــة بجــدة برقــم‬\n     ‫‪ 33398313‬وتاريــخ ‪1433/8/28‬ه ـ ‪ ،‬املتضمــن دعــوى املدعــي العــام‬\n     ‫ضــد‪ ............ /‬صومالــي اجلنســية املتهــم يف مخــدرات احملكــوم‬\n     ‫دون بباطــن القــرار وبدراســة القــرار وصــورة ضبطــه الالئحــة‬             ‫مبــا ّ‬\n     ‫االعتراضيــة تقــرر املوافقــة علــى احلكــم بعــد االجــراء االخيــر واهلل‬\n          ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪49‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":42,"source_page_end":49,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b38054ac3cb87b1ad5131ea91443eeb2dcff5c3bbf76df32d3683b79a252dc6e","normalized_text_hash":"62c81a49fced6b02e16dcf5246760f335e051349ac86e82dea539c08884f7a96","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p42-33398313"},{"id":"e8a5ea76-53dd-555e-916b-6472dd3f04cb","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج قطعه حشيش -حيازه كمية من احلشيش بقصد الترويج واالجتار والتعاطي -حيازة حبوب اإلمفيتامن بقصد الترويج واالجتار والتعاطي -تعاطي احلبوب احملظورة -تعاطي احلشيش املخدر -محاولة الهروب من الفرقة القابضة -تداخل احلدود إذا كانت من نفس اجلنس -التعزير بالسجن واجللد والغرامة واملصادرة واملنع من السفر.","document_number":"33297215","case_number":"32581355","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/06/14","year":"1434","subject":"مخدرات -ترويج قطعه حشيش -حيازه كمية من احلشيش بقصد الترويج واالجتار والتعاطي -حيازة حبوب اإلمفيتامن بقصد الترويج واالجتار والتعاطي -تعاطي احلبوب احملظورة -تعاطي احلشيش املخدر -محاولة الهروب من الفرقة القابضة -تداخل احلدود إذا كانت من نفس اجلنس -التعزير بالسجن واجللد والغرامة واملصادرة واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33297215:‬تاريخه ‪1433/06/14 :‬هـ‬\n                    ‫رقم الدعوى‪32581355:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34175225‬تاريخه‪1434/03/29 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج قطعــه حشــيش‪ -‬حيــازه كميــة مــن احلشــيش‬\n ‫بقصــد الترويــج واالجتــار والتعاطــي ‪ -‬حيــازة حبــوب اإلمفيتامــن‬\n ‫بقصــد الترويــج واالجتــار والتعاطــي ‪ -‬تعاطــي احلبــوب احملظــورة‬\n ‫‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬محاولــة الهــروب مــن الفرقــة القابضــة‬\n ‫‪ -‬تداخــل احلــدود إذا كانــت مــن نفــس اجلنــس ‪ -‬التعزيــر بالســجن‬\n                       ‫واجللــد والغرامــة واملصــادرة واملنــع مــن الســفر‪.‬‬\n\n\n\n\n                                 ‫‪ -1‬قاعدة اإلقرار حجة قاصرة على املقر‬\n ‫‪ -2‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                     ‫العقليــة ‪.‬‬\n ‫‪ -3‬الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                     ‫العقليــة ‪.‬‬\n           ‫‪ -4‬املادة (‪ )53‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n ‫‪ -5‬الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                     ‫العقليــة ‪.‬‬\n ‫‪ -6‬الفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                     ‫العقليــة ‪.‬‬\n\n\n\n                                                                                   ‫‪50‬‬\n\f     ‫إدعــى املدعــي العــام ضــد املدعــى عليهمــا بترويــج قطعــة كبيــرة مــن‬\n     ‫احلشــيش املخــدر بقصــد االجتــار ‪ ،‬واتهــام األول ‪ :‬بحيــازة كميــة‬\n     ‫كبيــرة مــن احلشــيش واحلبــوب احملظــورة بقصــد الترويــج واالجتــار‬\n     ‫والتعاطــي و تعاطــي احلشــيش واحلبــوب احملظــورة ومحاولــة الهــرب مــن‬\n     ‫الفرقــة القابضــة وترويجــه للمــواد املخــدرة يف الســابق ‪ ،‬حيــث قبضــت‬\n     ‫مكافحــة املخــدرات علــى املدعــى عليــه الثانــي إثــر ترويجــه لكميــة‬\n     ‫مــن احلشــيش املخــدر وضبــط املبلــغ املرقــم مــع مرافقــه (لــم يوجــه إليــه‬\n     ‫إتهــام لعــدم عالقتــه بالقضيــة ) ‪ ،‬كان املدعــى عليــه الثانــي أثنــاء عمليه‬\n     ‫الترويــج يســتقل ســيارة عائــدة لــه ‪ ،‬وعنــد القبــض عليــه أفــاد أنــه حصــل‬\n     ‫علــى تلــك الكميــة املــروج مــن املدعــى عليــه األول ‪ ،‬مت االنتقــال إلــى‬\n     ‫مــكان تواجــد املدعــى عليــه األول و عنــد الوصــول إليــه حــاول الهــرب‬\n     ‫فتــم اللحــاق بــه والقبــض عليــه ‪ ،‬وبتفتيــش منــزل املدعــى عليــه األول‬\n     ‫عثــر علــى كميــة مــن احلشــيش املخــدر ‪ ،‬كمــا عثــر علــى كميــة مــن‬\n     ‫احلبــوب احملظــورة وعلــى مبلــغ نقــدي وعلــى دفتريــن بهمــا تســجيل‬\n     ‫ألرقــام عمليــات يشــتبه أنهــا عمليــات ترويــج متنوعــة و مديونيــات نتيجــة‬\n     ‫لبيــع املــواد املخــدرة ‪ ،‬كمــا ضبــط مجموعــة مــن األســلحة والذخائــر‬\n     ‫(فــرزت لهــا أوراق مســتقله) ‪ -‬طلــب املدعــي العــام إثبــات مــا أســند‬\n     ‫للمدعــى عليهمــا واحلكــم عليهمــا بعقوبــة الســجن واجللــد والغرامــة‬\n     ‫وتشــديد العقوبــة بحــق ملدعــى عليــه األول لتعــدد ســوابقه ‪ ،‬ومنعهمــا مــن‬\n     ‫الســفر و مصــادرة الســيارة و اجلوالــن إلســتخدامهما يف عمليــه الترويــج‬\n     ‫ومصــادرة املبلــغ املضبــوط و إســقاط الشــريحتني وعــدم صرفهمــا‬\n\n‫‪51‬‬\n\f‫للمدعــى عليهمــا واحلكــم علــى األول باملقتضــى الشــرعي لقــاء تعاطيــه‬\n‫احلشــيش و إثبــات مــا أســند لــأول مــن محاولــة الهــروب مــن رجــال األمــن‬\n‫و تعزيــره علــى ذلــك ‪ ،‬كمــا أقــر املدعــى عليــه األول بالتعاطــي والهــروب‬\n‫مــن الفرقــة القابضــة وأنكــر ماعــدا ذلــك ‪ ،‬ذكــر بــأن املضبوطــات‬\n‫التــي يف بيتــه تخــص املدعــى عليــه الثانــي ‪ ،‬وأقــر املدعــى عليــه الثانــي‬\n‫مبــا نســب إليــه‪ ،‬كمــا أضــاف بأنــه أقيــم عليــه حــد املســكر مؤخــر ًا‬\n‫وذكــر بــأن املضبوطــات تخــص املدعــى عليــه األول وال تخصــه ‪،‬ثبــوت‬\n‫إدانــة املدعــى عليهمــا ‪ ،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة عليهما‬\n‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة املبلــغ املضبــوط‬\n‫يف منــزل املدعــى عليــه األول و مصــادرة هاتــف اجلــوال للمدعــى عليــه‬\n‫الثانــي وإســقاط شــريحته ومصــادرة ســيارة املدعــى عليــه الثانــي ‪،‬‬\n‫وصــدق احلكــم‬  ‫وعــدم مصــادرة هاتــف اجلــوال للمدعــى عليــه األول ‪ُ ،‬‬\n                                                   ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ 000000‬القاضــي يف احملكمــة‬\n‫اجلزئيــة بالدمــام ويف يــوم الثالثــاء ‪1433/02/2‬ه ـ افتتحــت اجللســة‬‫ّ‬\n‫الســاعة ‪ 11 : 04‬وفيهــا قــدم املدعــي العــام ‪ 000000‬دعــواه ضــد‬\n‫ا فيهــا إنــه‬\n             ‫املدعــى عليهمــا األول ‪ 000000 :‬والثانــي ‪ 000000 :‬قائ ـ ً‬\n‫يف ليلــة الثالثــاء ‪1432/9/9‬ه ـ قبضــت مكافحــة املخــدرات باجلبيــل‬\n‫علــى املدعــى عليــه الثانــي (‪ )000‬مبحافظــة اجلبيــل إثــر ترويجــه‬\n‫لكميــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )951‬تســعمائة وواحــد ًا‬\n‫وخمســن جرام ـ ًا مببلــغ (‪ )14500‬أربعــة عشــر ألف ـ ًا وخمســمائة ريــال‬\n\n                                                                                    ‫‪52‬‬\n\f     ‫وكان املبلــغ مرقمـ ًا وقــد ضبــط املبلــغ مــع مرافــق املدعــى عليــه الثانــي‬\n     ‫ويدعــى‪( 0000 /‬لــم يوجــه لــه اتهــام لعــدم عالقتــه بالقضيــة) وكان‬\n     ‫املدعــى عليــه الثانــي أثنــاء عمليــة الترويــج يســتقل ســيارة ‪ .......‬حتمــل‬\n     ‫لوحــة رقــم (‪ )000000‬صنــع عــام (‪2009‬م) عائــدة لــه وعنــد القبــض‬\n     ‫عليــه أفــاد انــه حصــل علــى تلــك الكميــة املروجــة مــن املدعــى عليــه‬\n     ‫ـاء عليــه مت االنتقــال ملــكان تواجــد املدعــى عليــه‬       ‫األول‪ 0000/‬وبنـ ً‬\n     ‫األول مبحافظــة القطيــف مبركــز العواميــة وعنــد التوصــل إليــه حــاول‬\n     ‫الهــرب مــن الفرقــة القابضــة وباللحــاق بــه ســقط مــن مــكان مرتفــع‬\n     ‫وبالقبــض عليــه وتفتيــش منزلــه ُعثــر يف صالــة املنــزل علــى كميــة مــن‬\n     ‫احلشــيش املخــدر بلــغ وزنهــا (‪ )13724.7‬ثالثــة عشــر كيلــو وســبعمائة‬\n     ‫وأربعــة وعشــرين جرام ـ ًا وســبعة أعشــار اجلــرام كمــا ُعثــر يف املجلــس‬\n     ‫علــى كميــة مــن احلبــوب احملظــورة بلــغ مجموعهــا (‪ )822‬ثمامنائــة‬\n     ‫واثنــن وعشــرين حبــة ومبلــغ نقــدي يقــدر بــ(‪ )43700‬ثالثــة وأربعــن ألفـ ًا‬\n     ‫وســبعمائة ريــال كمــا ُعثــر علــى قطــع مــن احلشــيش املخــدر بلــغ إجمالــي‬\n     ‫وزنهــا (‪ )127.5‬مائــة وســبعة وعشــرين جرام ـ ًا ونصــف اجلــرام كمــا‬\n     ‫ُعثــر علــى دفتريــن بهمــا تســجيل ألرقــام عمليــات يشــتبه أنهــا عمليــات‬\n     ‫ترويــج متنوعــة ومديونيــات نتيجــة لبيــع املــواد املخــدرة كمــا ضبــط‬\n     ‫مجموعــة مــن األســلحة والذخيــرة املتنوعــة فــرز لهــا أوراق مســتقلة‬\n     ‫وأحيلــت للجهــة املختصــة وقــد أثبــت التقريــر الكيمــاوي الشــرعي‬\n     ‫رقــم (‪ )......‬وتاريــخ ‪1432/9/20‬ه ـ إيجابيــة العينــات املرســلة مــن املــواد‬\n     ‫املضبوطــة املشــار إليهــا أعــاه للمــواد املخــدرة حيــث ثبــت إيجابيــة عينــة‬\n     ‫املــادة املروجــة واملــواد املضبوطــة مــن القطــع للحشــيش املخــدر وثبــت‬\n     ‫إيجابيــة احلبــوب املضبوطــة حلبــوب األمفيتامــن املنبهــة واحملظــورة وقــد‬\n\n\n‫‪53‬‬\n\f‫صــدر بحــق األول‪ 0000 /‬التقريــر الطبــي رقــم () وتاريــخ ‪1432/9/9‬ه ـ‬\n‫مــن مستشــفى اجلبيــل العــام املتضمــن إصابتــه بــرض باألنــف وســحجات‬\n‫بالركبــة اليمنــى واملرفــق األميــن والوجــه وقُ درت مدة الشــفاء بثالثة أيام‬\n‫مــا لــم حتــدث مضاعفــات وباســتجوابهما اعتــرف املدعــى عليــه الثانــي‬\n‫بصحــة واقعــة القبــض وقيامــه ببيــع مــا وزنــه (‪ )951‬تســعمائة وواحــد‬\n‫وخمســون جرامـ ًا مــن احلشــيش املخــدر مببلــغ (‪ )14500‬أربعــة عشــر ألف ًا‬\n‫وخمســمائة ريــال وقــد قــام بنقلهــا بواســطة ســيارته ‪ .....‬املضبوطــة معــه‬\n‫وانــه أخــذ هــذه الكميــة مــن املدعــى عليــه األول مببلــغ (‪ )14000‬أربعــة‬\n‫عشــر ألــف ريــال بقصــد الكســب املــادي وصــادق علــى اعترافــه شــرع ًا‬\n‫كمــا اعتــرف األول بصحــة واقعــة القبــض وأنــه ســلم الكميــة املروجــة‬\n‫للمدعــى عليــه الثانــي بقصــد الترويــج واالجتــار وأن مــا ضبــط داخــل‬\n‫منزلــه مــن حشــيش مخــدر وحبــوب محظــورة عائــدة لــه بقصــد الترويــج‬\n‫وذلــك بغــرض الكســب املــادي وبعضهــا بقصــد االســتعمال وأقــر أنــه‬\n‫يتعاطــى احلشــيش املخــدر واحلبــوب احملظــورة وأن املبلــغ املضبــوط يف‬\n‫منزلــه وقــدره (‪ )43700‬ثالثــة وأربعــن ألف ـ ًا وســبعمائة ريــال متحصلــة‬\n‫ـدون فيهمــا‬‫مــن جتارتــه يف املخــدرات وأن الدفتريــن املضبوطــن معــه مـ ّ‬\n‫أســماء عمالئهــم واملديونيــات التــي عليهــم مــن جـ ّـراء بيعــه للمخــدرات‬\n‫وأقــر انــه ميتهــن بيــع املخــدرات منــذ زمــن ويتعامــل مــع أحــد كبــار جتــار‬\n‫املخــدرات الــذي ال يعرفــه إال بوجهــه وأفــاد أن كل مــا ضبــط داخــل‬\n‫منزلــه يخصــه هــو واملدعــى عليــه الثانــي ‪ 0000‬وأنهمــا شــركاء فيــه‬\n‫وصــادق علــى اعترافــه شــرع ًا ومبواجهــة املدعــى عليــه الثانــي مبا جاء يف‬\n‫اعتــراف األول أنكــر مشــاركته لــه وأفــاد أن هــذه أول مــرة يبيــع فيهــا‬\n‫املــواد املخــدرة وقــد انتهــى التحقيــق إلــى اتهامهمــا ببيــع مــا وزنــه (‪)951‬‬\n\n\n                                                                                       ‫‪54‬‬\n\f     ‫تســعمائة وواحــد وخمســون جرامـ ًا مــن احلشــيش املخــدر بقصــد الترويــج‬\n     ‫واالجتــار واتهــام األول‪ 0000/‬بحيــازة مــا وزنــه (‪ )13852.2‬ثالثــة عشــر‬\n     ‫كيلــو وثمامنائــة واثنــان وخمســون جرامـ ًا وعشــري اجلــرام مــن احلشــيش‬\n     ‫املخــدر وحيــازة (‪ )822‬ثمامنائــة واثنــن وعشــرين حبــة مــن احلبــوب‬\n     ‫احملظــورة كل ذلــك بقصــد الترويــج واالجتــار والتعاطــي وتعاطيــه‬\n     ‫للحشــيش املخــدر واحلبــوب احملظــورة ومحاولــة هربــه مــن الفرقــة‬\n     ‫القابضــة وترويجــه للمــواد املخــدرة يف الســابق وذلــك لألدلــة والقرائــن‬\n     ‫التاليــة‪ -1 :‬اعترافيهمــا املصدقــن شــرع ًا املنــوه عنهمــا املدونــن علــى‬\n     ‫الصفحــات رقــم(‪ )22 ، 21 ، 11‬مــن دفتــر التحقيــق املرفــق علــى اللفــة‬\n     ‫رقــم (‪ -2 .)22‬محضــر االنتقــال والقبــض والتفتيــش املنــوه عنــه املــدون‬\n     ‫علــى الصفحــات رقــم (‪ )5-2‬مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم‬\n     ‫(‪ -3)22‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــات‬\n     ‫رقــم (‪ -4)39 ، 38‬محضــر التحريــز املــدون علــى الصفحــة رقــم (‪)16‬‬\n     ‫مــن دفتــر التحقيــق املرفــق علــى اللفــة رقــم (‪ -5)22‬التقريــر الطبــي املنوه‬\n     ‫عنــه املرفــق علــى اللفــة رقــم (‪)15‬وبالبحــث عــن ســوابقهما اجلنائيــة ُعثــر‬\n     ‫لــأول علــى أربــع ســوابق اثنتــن منهــا تهريــب مســكرات والثالثــة ترويــج‬\n     ‫وحيــازة املســكرات والرابعــة حيــازة واســتعمال مخــدرات والهــرب‬\n     ‫وعثــر للثانــي علــى ســابقتني األولــى فعــل فاحشــة اللــواط‬  ‫مــن الســلطة ُ‬\n     ‫والثانيــة إحــراق صالــة أفــراح وحيــث إن مــا أقــدم عليــه املذكــوران فعــلٌ‬\n     ‫ـب عليــه شــرع ًا ونظام ـ ًا أطلــب إثبــات مــا ُأســند إليهمــا‬‫محــرم ومعاقـ ٌ‬\n     ‫وفق ـ ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات‬\n     ‫واحلكــم عليهمــا مبــا يلــي‪ -1:‬عقوبــة الســجن واجللد والغرامــة الواردة يف‬\n     ‫الفقــرة رقــم (‪ )1‬مــن املــادة (‪ )38‬مــن ذات النظــام مــع مراعــاة املــادة (‪)62‬‬\n\n\n‫‪55‬‬\n\f‫بحــق األول وتشــديد العقوبــة يف حقــه لتعــدد ســوابقه التــي لــم تردعــه‬\n‫عقوباتهــا اســتناد ًا لتعميــم ســمو نائــب وزيــر الداخليــة رقــم (‪)93958‬‬\n‫يف ‪1429/8/23‬ه ـ ‪ -2‬منعهمــا مــن الســفر خــارج البــاد وفق ـ ًا للفقــرة‬\n‫رقــم (‪ )1‬مــن املــادة (‪ )56‬مــن النظــام‪ -3‬مصــادرة الســيارة املشــار إليهــا‬\n‫واجلوالــن اخلاصــن باملتهمــن ذات الرقمــن املصنعيــن رقــم (‪)0000‬‬\n‫ورقــم (‪ )0000‬الســتخدامها يف عمليــة الترويــج وفق ـ ًا للفقــرة (‪ )1‬مــن‬\n‫املــادة (‪ )53‬مــن النظــام‪ -4‬مصــادرة املبلــغ املضبــوط وقــدره (‪)43700‬‬\n‫ريــال وفق ـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة (‪ )53‬مــن النظــام‪ -5.‬إســقاط‬\n‫الشــريحتني ذاتــي الرقمــن (‪ )0000‬و(‪ )0000‬وعــدم صرفهمــا للمدعــى‬\n‫عليهمــا الســتخدامهما يف عمليــة الترويــج ‪ -6 .‬احلكــم علــى األول‬\n‫باملقتضــى الشــرعي لقــاء تعاطيــه احلشــيش املخــدر‪ -7 .‬إثبــات مــا ُأســند‬\n‫لــأول مــن محاولــة هربــه مــن رجــال األمــن عنــد القبــض عليــه واحلكــم‬\n‫عليــه بعقوبــة تعزيريــة وبــاهلل التوفيــق‪ .‬ويف هــذه اجللســة حضــر املدعــى‬\n‫عليهمــا األول ‪ 000000 :‬مبوجــب بيانــات مواطــن مصــدق مــن مكافحــة‬\n‫املخــدرات باجلبيــل املــدون بــه رقــم الهويــة ‪ 0000‬والثانــي ‪000000 :‬‬\n‫مبوجــب بطاقــة الهويــة الوطنيــة املــدون بهــا الرقــم ‪ 0000‬وبعــرض دعــوى‬\n‫املدعــي العــام عليهمــا أجــاب املدعــى عليــه األول ‪ 00000‬قائــا‪ :‬غيــر‬\n‫صحيــح أننــي ســلمت املدعــى عليــه الثانــي ‪ 0000‬قطعــة احلشــيش املخــدر‬\n‫املذكــور يف الدعــوى أن وزنهــا ( ‪ ) 951‬تســعمائة وواحــد وخمســن‬\n‫جرامـ ًا وغيــر صحيــح اتهامــي بترويجهــا وإمنــا املدعــى عليــه الثانــي ‪0000‬‬\n‫هــو الــذي كان قــد وضعهــا يف منزلــي وهــو الــذي حضــر وأخذهــا وال‬\n‫عالقــة لــي بذلــك وأمــا املضبوطــات التــي ُوجــدت يف منزلــي فهــي تخــص‬\n‫املدعــى عليــه الثانــي ‪ 0000‬حيــث أحضرهــا لــي وطلــب منــي أن أتركهــا‬\n\n\n                                                                                   ‫‪56‬‬\n\f     ‫يف منزلــي وأتقاضــى مقابــل ذلــك مــا أتعاطــاه منهــا مــن حشــيش مخــدر‬\n     ‫وحبــوب أمفيتامــن فوافقــت علــى ذلــك ووضعتهــا يف منزلــي وهــي ال‬\n     ‫تخصنــي وصحيــح أننــي أتعاطــى احلشــيش املخــدر وآخــر مــرة تعاطيتــه‬\n     ‫يــوم القبــض علــي علم ـ ًا أنــه قــد صــدر علــي حكـ ٌـم مــن الشــيخ ‪0000‬‬\n     ‫يتضمــن‬\n         ‫ّ‬       ‫القاضــي باحملكمــة اجلزئيــة بالقطيــف منــذ حوالــي شــهر‬\n     ‫احلكــم علـ ّـي بحــد املســكر وصحيــح أننــي تعاطيــت حبــوب األمفيتامني‬\n     ‫منــذ أكثــر مــن عشــر ســنوات واآلن تركتهــا وصحيــح أننــي هربــت مــن‬\n     ‫الفرقــة القابضــة بســبب أننــي لــم أعلــم أنهــم رجــال أمــن وغيــر صحيــح‬\n     ‫اتهامــي بترويــج املــواد املخــدرة بالســابق واملبلــغ الــذي ُضبــط يف منزلــي‬\n     ‫املذكــور يف الدعــوى أنــه مبلغ ـ ًا وقــدره ( ‪ )43700‬ثالثــة وأربعــون ألــف‬\n     ‫وســبعمائة ريــال ال يخصنــي وإمنــا يخــص املدعــى عليــه الثانــي ‪00000‬‬\n     ‫والســوابق التــي ذكرهــا املدعــي العــام يف حقــي تخصنــي هــذه إجابتــي‬\n     ‫ا ‪ :‬مــا ذكــره املدعــي العــام‬\n                                    ‫‪ .‬ثــم أجــاب املدعــى عليــه الثانــي ‪ 0000‬قائـ ً‬\n     ‫يف دعــواه صحيــح فقــد قُ بــض علــي بعــد أن بعــت علــى املصــدر كميــة‬\n     ‫احلشــيش املذكــورة يف الدعــوى والتــي وزنهــا ( ‪ ) 951‬تســعمائة وواحــد‬\n     ‫وخمســن جرامـ ًا واســتلمت املبلــغ احلكومــي املرقــم وقــدره ( ‪) 14500‬‬\n     ‫أربعــة عشــر ألــف وخمســمائة ريــال وكان عملــي لذلــك بقصــد احلصــول‬\n     ‫علــى مبلــغ مالــي مــن خــال هــذه العمليــة حيــث أخــذت هــذه الكميــة‬\n     ‫التــي قمــت بترويجهــا مــن املدعــى عليــه األول ‪ 0000‬مببلــغ وقــدره (‬\n     ‫‪ ) 14000‬أربعــة عشــر ألــف ريــال لكــي أبيعهــا علــى املصــدر مببلــغ‬\n     ‫وقــدره ( ‪ ) 14500‬أربعــة عشــر ألــف وخمســمائة ريــال وقــد اســتخدمت‬\n     ‫هاتفــي اجلــوال املذكــور يف الدعــوى يف التنســيق لعمليــة الترويــج‬\n     ‫املذكــورة كمــا أن الســيارة التــي حضــرت فيهــا للمصــدر عنــد عمليــة‬\n\n\n‫‪57‬‬\n\f‫الترويــج املذكــورة أوصافهــا يف الدعــوى تعــود ملكيتهــا لــي مبوجــب‬\n‫ورقــة مبايعــة ولــم أنقــل الســيارة باســمي حتــى اآلن لوجــود مخالفــة علــي‬\n‫وقــد اشــتريت هــذه الســيارة قبــل القضيــة بأســبوع وهــذه الســيارة هــي‬\n‫املروجــة وأمــا مــا ذكــره املدعــى عليــه األول‬\n                                               ‫التــي نقلــت فيهــا الكميــة ّ‬\n‫مــن أن املضبوطــات التــي يف منزلــه تعــود لــي فهــذا غيــر صحيــح ولــم‬\n‫أحضرهــا لــه وال عالقــة لــي بهــا وكذلــك املبلــغ املضبــوط يف منزلــه‬\n‫املذكــور يف الدعــوى ال يخصنــي وال عالقــة لــي بــه والســابقتني اللتــن‬\n‫ذكرهمــا املدعــي العــام تخصنــي هــذه إجابتــي ثــم جــرى رفــع اجللســة‬\n‫وتأجلــت مبشــيئة اهلل للكتابــة للمحكمــة اجلزئيــة بالقطيــف والتأكــد‬\n‫ممــا ذكــره املدعــى عليــه األول ويف حــال صــدور حكــم عليــه بحــد‬\n‫املســكر تزويدنــا بصــور ٍة منــه وســوف يتــم إكمــال النظــر يف الدعــوى‬\n‫بعــد ورود اجلــواب وعلــى ذلــك حصــل التوقيــع واهلل املوفــق وصلــى اهلل‬\n                                              ‫علــى نبينــا محمــد وآلــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت ‪1433/6/7‬ه ـ ُفتحــت اجللســة‬\n‫الســاعة ‪ 1.12‬وقــد وردنــا صــورة مــن القــرار الشــرعي الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة اجلزائيــة مبحافظــة القطيــف الشــيخ‬\n‫‪0000‬برقــم ‪ 0000‬يف ‪1433/1/4‬ه ـ وممــا تضمنــه احلكــم علــى املدعــى‬\n‫عليــه ‪ 0000‬بحــد املســكر ‪ .‬ثــم جــرى ســؤال املدعــى عليــه األول ‪0000‬‬\n‫بأنــه ذكــر يف جوابــه عــن الدعــوى بــأن قطعــة احلشــيش البالــغ وزنهــا‬\n‫( ‪ ) 951‬تســعمائة وواحد وخمســن جرام ًا كانت يف منزله وأن املدعى‬\n‫عليــه الثانــي ‪ 0000‬حضــر وأخذهــا فعلــى فــرض ذلــك هــل اســتخدمت‬\n‫هاتفــك اجلــوال املذكــور نوعــه ورقمــه املصنعــي يف الدعــوى للتنســيق‬\n‫مــع املدعــى عليــه الثانــي ‪ 0000‬يف احلضــور وأخــذ قطعــة احلشــيش املخدر‬\n\n\n                                                                                     ‫‪58‬‬\n\f     ‫ا ‪ :‬ال لــم أســتخدم هاتفــي املذكــور يف الدعــوى‬       ‫املذكــورة فقــرر قائ ـ ً‬\n     ‫وإمنــا حضــر املدعــى عليــه الثانــي ‪ 000‬ملنزلــي ودخــل وأخذهــا حيــث أن‬\n     ‫معــه نســخه مــن مفتــاح املنــزل وابــن عمــي يشــهد بــأن مــع املدعــى عليــه‬\n     ‫الثانــي ‪ 0000‬نســخة مــن مفتــاح منزلــي ‪ ،‬ثــم قــرر املدعــى عليــه الثانــي‬\n     ‫ا ‪ :‬غيــر صحيــح أن معــي نســخة مــن مفتــاح منــزل املدعــى‬         ‫‪ 0000‬قائ ـ ً‬\n     ‫عليــه األول ‪ 0000‬ثــم قــرر املدعــي العــام عــدم وجــود مزيــد بينــة ســوى مــا‬\n     ‫ورد يف الئحــة الدعــوى وأوراق املعاملــة ثــم جــرى االطــاع علــى إقــرار‬\n     ‫املدعــى عليــه األول ‪ 0000‬املصــدق شــرع ًا املــدون علــى الصفحتــن رقــم‬\n     ‫( ‪ ) 22 - 21‬مــن ملــف ضبــط إجــراءات قضيــة مخــدرات املرفــق علــى‬\n     ‫اللفــة رقــم ( ‪ ) 22‬مــن طيــات املعاملــة وممــا تضمنــه مــا نصــه ( ‪-1‬أقــر‬\n     ‫أنــه قُ بــض علــي مــن قبلهــم إثــر قيامــي بإعطــاء املدعــو ‪ 000 /‬ســعودي‬\n     ‫اجلنســية كيلــو مــن احلشــيش املخــدر لغــرض بيعــه وإحضــار قيمتــه وقــام‬\n     ‫املذكــور ببيعــه وعندمــا أحضــر قيمتــه قُ بــض علــي وكانــت قيمتــه اثنــا‬\n     ‫عشــر ألــف ريــال وخمســمائة ‪ -2 .‬أقــر أنــه ُعثــر عنــدي يف املنــزل علــى‬\n     ‫كمية من احلشــيش املخدر عددها حوالي ( ‪ ) 16.100.50‬ســتة عشــر‬\n     ‫كيلــو ومائــة جــرام ونصــف اجلــرام وهــي عائــدة لــي أنــا واملدعــو ‪00000‬‬\n     ‫وقصــدي مــن حيازتهــا الترويــج ‪ -3 .‬كمــا أقــر أنــه ُعثــر عنــدي أيضـ ًا يف‬\n     ‫منزلــي علــى عــدد أربــع قطــع مــن احلشــيش املخــدر بلــغ وزنهــا ( ‪) 127.5‬‬\n     ‫جــرام وهــي عائــدة لــي وقصــدي مــن حيازتهــا التعاطــي الشــخصي ‪-4 .‬‬\n     ‫كمــا أقــر أنــه ُعثــر عنــدي يف منزلــي علــى عــدد ( ‪ ) 822‬حبــة كبتاجون‬\n     ‫وهــي عائــدة لــي وقصــدي مــن حيازتهــا التعاطــي الشــخصي ‪ -5 .‬كمــا‬\n     ‫أقــر أنــه ُعثــر يف منزلــي علــى مبلــغ وقــدره ( ‪ ) 43700‬ثالثــة وأربعــون‬\n     ‫ألــف وســبعمائة ريــال وهــي قيمــة حشــيش مخــدر ‪ ) .‬كما تضمــن إقراره‬\n\n\n‫‪59‬‬\n\f‫املصــدق شــرع ًا مــا نصــه ‪ -8 ( :‬كمــا أقــر أن دفتــر الديــون املســجل‬\n‫بخــط يــدي يعــود لــي والغــرض منــه تســجيل مديونيــات كميــة احلشــيش‬\n‫املخــدر ‪ -9‬كمــا أقــر أن هــذه الكميــات مــن احلشــيش نأخذهــا مــن‬\n‫شــخص ال نعرفــه باالســم وال نعــرف ســوى وجهــه ويدعــى ‪-10 .......‬‬\n‫كمــا أقــر أنــه ســبق أن أخذنــا مــن هــذا الشــخص كميــات من احلشــيش‬\n‫املخــدر حوالــي أربــع مــرات وكان أكبــر كميــة أخذناهــا مــن هــذا‬\n‫الشــخص خمســه وعشــرون كيلــو وقمنــا ببيــع تلــك الكميــات وإعطاؤه‬\n‫قيمتهــا ‪ -11‬وأقــر أن هــذه الكميــة األخيــرة كانــت عشــرون كيلــو‬\n‫ضبــط عندنــا ســتة عشــر كيلــو والباقــي مت بيعــه قبــل القبــض علينــا )‬\n‫ا‪:‬‬ ‫وبعــرض ذلــك اإلقــرار علــى املدعــى عليــه األول ‪ 0000‬أجــاب قائ ـ ً‬\n‫لقــد اعترفــت يف احملكمــة بهــذا اإلقــرار بســبب أنــه مت ضربــي يف‬\n‫مكافحــة املخــدرات و مت تهديــدي يف مكافحــة املخــدرات يف حالــة‬\n‫عــدم اعتــرايف بضربــي مــرة أخــرى وليــس لــدي بينــة ســوى مــا يوجــد يف‬\n‫جســمي مــن ضــرب ‪ .‬فنظــر ًا ملــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر‬\n‫املدعــى عليــه األول ‪ 0000‬بوجــود قطعــة احلشــيش املخــدر البالــغ وزنهــا (‬\n‫‪ ) 951‬تســعمائة وواحــد وخمســن جرام ـ ًا يف منزلــه وبــرر ذلــك مبــا‬\n‫ذكــره يف جوابــه وأنكــر تســليمها للمدعــى عليــه الثانــي ‪ 0000‬وحيــث‬\n‫أقــر املدعــى عليــه األول ‪ 0000‬مبوافقتــه يف أن يبقــي يف منزلــه مــا وجــد‬\n‫فيــه مــن مضبوطــات وبــرر ذلــك مبــا ذكــره يف جوابــه وأقــر كذلــك‬\n‫بــأن املبلــغ املوجــود يف منزلــه وقــدره ( ‪ ) 43700‬ثالثــة وأربعــون ألــف‬\n‫وســبعمائة ريــال ال يخصــه وأنــه يخــص املدعــى عليــه الثانــي ‪0000‬‬\n‫وحيــث أنكــر املدعــى عليــه الثانــي ‪ 0000‬مــا ذكــره املدعــى عليه األول‬\n‫‪ 0000‬بخصــوص املضبوطــات واملبلــغ املالــي التــي وجــدت يف منــزل‬\n\n\n                                                                                   ‫‪60‬‬\n\f     ‫املدعــى عليــه األول ‪ 00000‬وقــرر املدعــى عليــه الثانــي ‪ 0000‬أنــه ال‬\n     ‫عالقــه لــه بذلــك وحيــث أقــر املدعــى عليــه األول ‪ 0000‬بتعاطــي‬\n     ‫احلشــيش املخــدر وحبــوب األمفيتامــن وحيــث صــدر يف حقــه حكـ ٌـم‬\n     ‫بحــد املســكر املشــار إليــه يف قــرار الشــيخ ‪ 00000‬املذكــور أعــاه‬\n     ‫ـس واحــد ال ســيما وتاريــخ‬  ‫وحيــث أن احلــدود تتداخــل مــا دامــت مــن جنـ ٍ‬\n     ‫هــذه الدعــوى كمــا ورد يف الئحــة االدعــاء العــام ‪1432/9/9‬ه ـ بينمــا‬\n     ‫قــرار فضيلــة ‪00000‬صــادر بتاريــخ ‪1433/1/4‬ه ـ وحيــث أقــر املدعــى‬\n     ‫عليــه األول ‪ 0000‬بالهــرب مــن الفرقــة القابضــة وبــرر ذلــك مبــا ذكــره‬\n     ‫يف جوابــه ولتوجــه التهمــة يف حقــه بــأن هربــه مــن الفرقــة كان مــع علمــه‬\n     ‫أنهــم رجــال أمــن بداللــة مــا ُوجــد يف منزلــه مــن مضبوطــات محظــورة‬\n     ‫ـاء علــى إقــرار املدعــى عليــه األول ‪ 0000‬املصــدق شــرع ًا املشــار إليــه‬\n                                                                                 ‫وبنـ ً‬\n     ‫بعاليــه الــذي يثبــت إدانتــه يف ترويــج كميــة احلشــيش املذكــورة يف‬\n     ‫الدعــوى ويف حيازتــه للمضبوطــات املوجــودة يف منزلــه حســب القصــد‬\n     ‫املذكــور يف إقــراره ولتوجــه التهمــة يف حــق املدعــى عليــه األول ‪0000‬‬\n     ‫يف أن حيازتــه حلبــوب األمفيتامــن املذكــورة يف الدعوى وقطع احلشــيش‬\n     ‫البالــغ وزنهــا ( ‪ ) 127.5‬مائــة وســبعة وعشــرين جرام ـ ًا ونصــف اجلــرام‬\n     ‫كان بقصــد الترويــج باإلضافــة للتعاطــي بداللــة ترويجــه لكميــة‬\n     ‫احلشــيش املخــدر املذكــورة يف الدعــوى وحيــث أن اإلقــرار حجــة قاصرة‬\n     ‫علــى املقــر وحيــث صــادق املدعــى عليــه الثانــي ‪ 000000‬علــى دعــوى‬\n     ‫املدعــي العــام وأقــر ببيعــه علــى املصــدر كميــة احلشــيش املخــدر البالــغ‬\n     ‫وزنهــا ( ‪ ) 951‬تســعمائة وواحــد وخمســن جرامـ ًا بقصــد احلصــول علــى‬\n     ‫مبلــغ مالــي مــن خــال هــذه العمليــة وأقــر باســتالمه للمبلــغ احلكومــي‬\n     ‫واســتخدامه لهاتفــه وســيارته ‪ -‬املشــار إليهمــا يف الدعــوى ‪ -‬يف عمليــة‬\n\n\n‫‪61‬‬\n\f‫البيــع املذكــورة وأقــر كذلــك بــأن هــذه الكميــة قــد أخذهــا مــن‬\n‫املدعــى عليــه األول وبعــد االطــاع علــى طيــات املعاملــة ومــن ضمنهــا‬\n‫التقريــر الكيمــاوي الشــرعي الصــادر مــن املركــز اإلقليمــي ملراقبــة‬\n‫الســموم باملنطقــة الشــرقية برقــم ( ‪3058‬ك ش ) املتضمــن إيجابيــة‬\n‫العينات رقم ( ‪183‬س م ل‪ ) 1/‬و ( ‪183‬س م ل‪ ) 2/‬و ( ‪183‬س م ل‪)3/‬‬\n‫ملــادة احلشــيش املخــدر وإيجابيــة العينتــن رقــم ( ‪183‬س م ل‪ ) 4/‬و (‬\n‫‪183‬س م ل‪ ) 5/‬ملــادة األمفيتامــن وبعــد االطــاع علــى محضــر انتقــال‬\n‫وضبــط وتفتيــش املــؤرخ يف ‪1432/9/9-8‬ه ـ املــدون علــى الصفحــات‬\n‫رقــم ( ‪ ) 5-2‬مــن ملــف ضبــط إجــراءات قضيــة مخــدرات املشــار إليــه‬\n‫بعاليــه املتضمــن نحــو مــا جــاء يف الئحــة الدعــوى وحيــث أن هــذه الدعوى‬\n‫وقعــت يف شــهر رمضــان املبــارك ويف ذلــك انتهــاك حلرمــة هــذا الشــهر‬\n‫املروجــة والكميــة املضبوطــة يف منــزل‬       ‫الفضيــل ولكثــرة الكميــة ّ‬\n‫املدعــى عليــه األول ‪ 0000‬ممــا يــدل علــى عظــم جرمــه وتوجهــه التهمــة‬\n‫إليــه يف امتهــان ترويــج احلشــيش املخــدر وحبــوب األمفيتامــن ال ســيما‬\n‫مــع إقــراره بالترويــج يف الســابق ومــا وجــد يف منزلــه مــن دفتـ ٍـر أقــر بأنــه‬\n‫بخــط يــده وأن الغــرض منــه تســجيل مديونيــات كميــة احلشــيش املخــدر‬\n‫حســب إقــراره املصــدق شــرع ًا املشــار إليــه أعــاه وممــا يزيــد يف تهمــة‬\n‫امتهانــه لترويــج احلشــيش املخــدر وحبــوب األمفيتامــن مــا ُوجــد يف‬\n‫منزلــه مــن أســلحة وممــا يزيــد التهمــة يف ذلــك أبض ـ ًا أن مــن ضمــن‬\n‫ســوابقه ســابقتني يف تهريــب املســكرات وســابقة يف ترويــج وحيــازة‬\n‫ـاء علــى الفقــرة ( ‪ ) 2‬مــن املــادة رقــم ( ‪ ) 3‬والفقــرة ( ‪) 1‬‬\n                                                                 ‫املســكرات وبنـ ً‬\n‫مــن املــادة رقــم ( ‪ ) 38‬واملــادة رقــم ( ‪ ) 53‬والفقــرة ( ‪ ) 1‬مــن املــادة رقــم (‬\n‫‪ ) 56‬والفقــرة ( ‪ ) 1‬مــن املــادة رقــم ( ‪ ) 62‬مــن نظــام مكافحــة املخــدرات‬\n\n\n                                                                                          ‫‪62‬‬\n\f     ‫واملؤثــرات العقليــة ولعــدم وجــود البينــة القاطعــة يف اســتخدام املدعــى‬\n     ‫عليــه األول جلوالــه املذكــور يف الدعــوى يف التنســيق لعمليــة ترويــج مــا‬\n     ‫ـيش مخــدر لذلــك كلــه فقــد قــررت مــا يلــي‬     ‫ُذكــر يف الدعــوى مــن حشـ ٍ‬\n     ‫‪ :‬أوالً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه األول ‪ 0000‬بترويــج كميــة‬\n     ‫احلشــيش املخــدر املذكــورة يف الدعــوى البالــغ وزنهــا ( ‪ ) 951‬تســعمائة‬\n     ‫وواحــد وخمســن جرامـ ًا وذلــك عــن طريــق تســليمها للمدعــى عليه األول‬\n     ‫‪ 0000‬كمــا ثبــت لــدي إدانــة املدعــى عليــه األول ‪ 0000‬بحيــازة كميــة‬\n     ‫احلشــيش املخــدر املضبوطــة يف منزلــه البالــغ وزنهــا ( ‪ ) 13724.7‬ثالثــة‬\n     ‫عشــر كيلــو وســبعمائة وأربعــة وعشــرين جرامـ ًا وســبعة مــن العشــرة مــن‬\n     ‫اجلــرام وذلــك بقصــد الترويــج وقــررت معاقبتــه علــى ذلــك كلــه مبــا يلــي‬\n     ‫ـداء مــن تاريــخ إيقافــه وجلــده‬  ‫‪ :‬أ‪ -‬ســجنه ملــدة ثالثــة عشــرة ســنة ابتـ ً‬\n     ‫(‪ ) 1200‬ألــف ومائتــي جلــدة مفرقــة علــى أربعــه وعشــرين دفعــة بــن‬\n     ‫كل دفع ـ ٍة وأخــرى مــا اليقــل عــن خمســة عشــر يوم ـ ًا وتغرميــه مبلغ ـ ًا‬\n     ‫وقــدره ( ‪ ) 150000‬مائــة وخمســن ألــف ريــال ‪ .‬ب‪ -‬منعــه مــن الســفر‬\n     ‫ملــدة ثالثــة عشــر ســنة تبــدأ بعــد انتهــاء فتــرة الســجن املقــررة يف حقــه يف‬\n     ‫الفقــرة ( أ ) مــن هــذا البنــد ‪ .‬ثانيـاً‪ -‬مصــادرة املبلــغ املضبــوط يف منــزل‬\n     ‫املدعــى عليــه األول ‪ 0000‬وقــدره ( ‪ ) 43700‬ثالثــة وأربعــون ألف ـ ًا‬\n     ‫وســبعمائة ريــال كونــه قيمــة حشــيش مخــدر حســب إقــرار املدعــى عليه‬\n     ‫املذكــور يف إقــراره املصــدق شــرع ًا املشــار إليــه بعاليــه ‪ .‬ثالث ـاً‪ -‬ثبــت‬\n     ‫لدي إدانة املدعى عليه األول ‪ 0000‬بترويج احلشــيش املخدر يف الســابق‬\n     ‫حســب مــا ورد يف إقــراره املصــدق شــرع ًا املشــار إليــه بعاليــه وعقوبتــه يف‬\n     ‫ذلــك داخلــة يف العقوبــة الصــادرة يف حقــه يف البنــد ( أو ًال ) ‪ .‬رابعـاً‪ -‬ثبــت‬\n     ‫لــدي إدانــة املدعــى عليــه األول ‪ 0000‬بحيــازة قطــع احلشــيش املخــدر‬\n\n\n‫‪63‬‬\n\f‫املضبوطــة يف منزلــه البالــغ وزنهــا ( ‪ ) 127.5‬مائــة وســبعة وعشــرين‬\n‫جرامـ ًا ونصــف اجلــرام كمــا ثبــت لدي إدانته بحيــازة حبوب األمفيتامني‬\n‫املضبوطــة يف منزلــه البالــغ عددهــا ( ‪ ) 822‬ثمامنائــة واثنــن وعشــرين‬\n‫حبــة وذلــك كلــه بقصــد التعاطــي والتهمــة متوجهــة لــه يف حيازتهمــا‬\n‫بقصــد الترويــج وعقوبتــه يف ذلــك داخلــة يف العقوبــة الصــادرة يف حقــه‬\n‫ـاء بالعقوبــة األشــد ‪ .‬خامس ـاً‪ -‬ثبــت لــدي إدانــة‬ ‫يف البنــد ( أو ًال ) اكتفـ ً‬\n‫املدعــى عليــه األول‪0000‬بتعاطــي احلشــيش املخــدر واكتفيــت مبــا صدر‬\n‫عليــه مــن حــدٍ للمســكر املذكــور يف قــرار الشــيخ ‪ 0000‬املشــار إليــه‬\n‫بعاليــه ومبــا صــدر عليــه مــن منـ ٍـع مــن الســفر املذكــور يف الفقــرة ( ب )‬\n‫مــن البنــد ( أو ًال ) يف هــذا القــرار ‪ .‬سادس ـاً‪ -‬ثبــت لــدي إدانــة املدعــى‬\n‫عليــه األول ‪ 000‬بتعاطــي حبــوب األمفيتامــن واكتفيــت مبــا صــدر‬\n‫عليــه مــن حــدٍ للمســكر املذكــور يف قــرار الشــيخ ‪0000‬املشــار إليــه‬\n‫بعاليــه عــن تعزيــره لقــاء ذلــك كمــا اكتفيــت مبــا صــدر عليــه مــن منـ ٍـع‬\n‫مــن الســفر املذكــور يف الفقــرة ( ب ) مــن البنــد ( أو ًال ) يف هــذا القــرار‬\n‫‪ .‬ســابعاً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه األول ‪ 0000‬بالهــرب مــن الفرقــة‬\n‫القابضــة وتوجــه التهمــة يف حقــه يف علمــه أثنــاء هربــه أن هــذه الفرقــة‬\n‫مــن رجــال األمــن وعقوبتــه يف ذلــك داخلــة يف عقوبــة الســجن واجللــد‬\n‫املذكــورة يف الفقــرة ( أ ) مــن البنــد ( أو ًال )‪ .‬ثامن ـاً‪ -‬دخــول العقوبــة‬\n‫التعزيريــة يف حــق املدعــى عليــه األول ‪ 0000‬علــى ســوابقه املشــار إليهــا‬\n‫يف الدعــوى مبــا صــدر عليــه مــن حكـ ٍـم بالســجن واجللــد املذكــور يف‬\n‫الفقــرة ( أ ) مــن البنــد ( أو ًال ) ‪ .‬تاســعاً‪ -‬لــم يظهــر لــي مصــادرة الهاتــف‬\n‫اجلــوال املذكــور يف الدعــوى خــاص باملدعــى عليــه األول ‪ 0000‬لعــدم‬\n‫وجــود البينــة القاطعــة يف اســتخدامه يف التســيق لعمليــة الترويــج‬\n\n\n                                                                                        ‫‪64‬‬\n\f     ‫املذكــورة ‪ .‬عاشــراً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه الثانــي ‪ 0000‬بترويج‬\n     ‫كميــة احلشــيش املخــدر املذكــورة يف الدعــوى البالــغ وزنهــا ( ‪) 951‬‬\n     ‫تســعمائة وواحــد وخمســن جرام ـ ًا وذلــك عــن طريــق البيــع و قــررت‬\n     ‫ـداء مــن‬\n            ‫معاقبتــه علــى ذلــك مبــا يلــي ‪ :‬أ‪ -‬ســجنه ملــدة ســبع ســنوات ابتـ ً‬\n     ‫تاريــخ إيقافــه وجلــده ( ‪ ) 600‬ســتمائة جلــدة مفرقــة علــى اثنــي عشــر‬\n     ‫دفعــة بــن كل دفعـ ٍة وأخــرى مــا اليقــل عــن خمســة عشــر يومـ ًا وتغرميــه‬\n     ‫مبلغـ ًا وقــدره ( ‪ ) 14500‬أربعــة عشــر ألــف وخمســمائة ريــال ‪ .‬ب‪ -‬منعــه‬\n     ‫مــن الســفر ملــدة ســبع ســنوات تبــدأ بعــد انتهــاء فتــرة الســجن املقــررة يف‬\n     ‫حقه يف الفقرة ( أ ) من هذا البند ‪ .‬ج‪ -‬مصادرة هاتفه اجلوال املذكور‬\n     ‫نوعــه ورقمــه املصنعــي يف الدعــوى وكذلــك ســيارته املذكــورة يف‬\n     ‫الدعــوى الســتخدامهما يف عمليــة ترويــج كميــة احلشــيش املذكــورة يف‬\n     ‫الدعــوى مــع إســقاط شــريحة الهاتــف اجلــوال وعــدم صرفهــا لنفــس‬\n     ‫املدعــى عليــه وبذلــك أجمــع حكمــت وبعــرض احلكــم علــى الطرفــن‬\n     ‫قــرر املدعــى عليــه األول ‪ 000‬االعتــراض علــى احلكــم وطلــب رفعــه‬\n     ‫حملكمــة االســتئناف بالئح ـ ٍة اعتراضيــة مقدم ـ ٍة منــه ف ُأجيــب لطلبــه‬\n     ‫وجرى إفهامه أنه ســوف يتم طلبه يوم الســبت ‪1433/6/14‬هـ لتســليمه‬\n     ‫صــورة مــن احلكــم وأنــه يف التاريــخ املشــار إليــه ســوف يتــم إيــداع القــرار‬\n     ‫ملــف الدعــوى وســوف يكــون ذلــك اإليــداع مجريـ ًا مليعــاد الثالثــن يومـ ًا‬\n     ‫يقــدم خاللهــا الئحتــه االعتراضيــة وأنــه مبضيهــا دون تقــدمي الالئحــة‬\n     ‫ويرفــع احلكــم حملكمــة االســتئناف‬          ‫ســوف يســقط حقــه يف تقدميهــا ُ‬\n     ‫بدونهــا فامتثــل وقــرر املدعــى عليــه الثانــي القناعــة باحلكــم وقــرر‬\n     ‫املدعــي العــام االعتــراض وطلــب رفــع احلكــم حملكمــة االســتئناف‬\n     ‫واكتفــى بالئحــة الدعــوى وأوراق املعاملــة عــن تقــدمي الئحـ ٍة اعتراضيــة‬\n\n\n‫‪65‬‬\n\f     ‫ف ُأجيب لطلبه واهلل املوفق وصلى اهلل على نبينا محمد وآله وسلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت ‪1433/6/14‬ه ـ ُفتحــت اجللســة‬\n‫وفيهــا حضــر املدعــى عليــه األول ‪ 000‬وجــرى تســليمه صــورة مــن‬\n‫احلكــم الصــادر برقــم ‪ 0000‬يف ‪1433/6/14‬ه ـ وجــرى إفهامــه أن عليه‬\n‫تقــدمي الئحتــه االعتراضيــة خــال املــدة النظاميــة ثالثــن يومـ ًا مــن تاريــخ‬\n‫اليــوم وأنــه مبضــي هــذه املــدة بــدون تقــدمي الالئحــة ســوف يســقط حقــه‬\n‫ويرفــع احلكــم حملكمــة االســتئناف بدونهــا فامتثــل واهلل‬        ‫يف تقدميهــا ُ‬\n                          ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافق‪1433/07/09‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــى عليــه األول وقــدم الئحتــه‬\n‫االعتراضيــة املكونــة مــن ســبع صفحــات واملقيــدة برقــم ‪ 0000‬يف‬\n‫‪1433/7/9‬ه ـ وجــرى االطــاع عليهــا ولــم أجــد فيهــا مــا يوجــب الرجــوع‬\n‫عمــا حكمــت بــه وســوف يتــم رفــع احلكــم حملكمــة االســتئناف‬\n  ‫بالشــرقية واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يوم األربعاء املوافق‪1434/02/06‬هـ افتتحت‬\n‫اجللســة وقــد وردت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n‫وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة األولــى رقــم‬\n‫‪ 000‬يف ‪1433/11/1‬ه ـ ونــص احلاجــة منــه ( وبدراســة القــرار وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ أن فضيلــة ناظــر‬\n‫القصيــة حكــم علــى املدعــى عليــه األول بغرامــة ماليــة قــدره مائــة‬\n‫وخمســون ألــف ريــال خــاف مــا نصــت عليــه املــادة الثامنــة والثالثــون‬\n‫مــن نظــام مكافحــة املخــدرات ملالحظــة ذلــك وإكمــال الــازم ومــن‬\n‫ثــم إعــادة املعاملــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n                                                                                       ‫‪66‬‬\n\f     ‫وصحبــه وســلم حــرر يف ‪1433/10/28‬ه ـ قاضــي اســتئناف ‪ 0000‬ختمه‬\n     ‫وتوقيعــه قاضــي اســتئناف ‪ 000‬ختمــه وتوقيعــه ؤئيــس الدائــرة ‪0000‬‬\n     ‫ختمــه وتوقيعــه ) ولوجاهــة مــا ذكــره أصحــاب الفضيلــة وبعــد إعــادة‬\n     ‫ـاء علــى املــادة رقــم ( ‪ ) 38‬مــن نظــام‬\n                                              ‫االطــاع علــى طيــات املعاملــة وبنـ ً‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة فقــد رجعــت عمــا حكمــت بــه‬\n     ‫ســابق ًا مــن الغرامــة املاليــة املقــررة يف حــق املدعــى عليــه األول ‪0000‬‬\n     ‫وقــررت تغرميــه مبلغ ـ ًا وقــدره ( ‪ ) 50000‬خمســون ألــف ريــال مــع بقيــة‬\n     ‫جميــع بنــود احلكــم األخــرى علــى مــا هــي عليــه وبذلــك أجمــع حكمــت‬\n     ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه األول ‪0000‬‬\n     ‫االعتــراض وطلــب رفــع احلكــم حملكمــة االســتئناف بنفــس الالئحــة‬\n     ‫االعتراضيــة الســابقة ف ُأجيــب لطلبــه واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                                 ‫محمــد وآلــه وســلم ‪.‬‬\n     ‫احلمــدهلل وحــده وبعــد ويف يــوم االثنــن املوافق‪1434/04/22‬ه ـ فتحــت‬\n     ‫اجللســة وقــد وردت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n     ‫مبوجــب اخلطــاب رقــم يف ‪1434/04/06‬ه ـ وبرفقهــا قــرار أصحــاب‬\n     ‫الفضيلــة قضــاة الدائــرة اجلزائيــة األولــى مبحكمــة االســتئناف باملنطقه‬\n     ‫الشــرقية رقــم يف ‪1434/03/29‬ه ـ املتضمــن املصادقــة علــى احلكــم‬\n     ‫بعــد االجــراء األخيــر لــذا جــرى إحلاقــه واهلل املوفــق وصلــى اهلل علــى‬\n                                                          ‫نبينــا محمــد وآلــه وســلم ‪.‬‬\n\n\n\n\n‫‪67‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":50,"source_page_end":67,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b7092348d032bdf1ac7132cf1e358e92a74b464c423ddad9fe737f9ae97bd4a4","normalized_text_hash":"3c32152d56b75c2805001c8bb51a756bb0804008f2e9d3aa4a93a7cd5b3002e6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p50-33297215"}]$archive_payload$::jsonb) AS x LIMIT 25
